import jwt from 'jsonwebtoken';
import bcrypt from 'bcrypt';
import crypto from 'crypto';
import { config } from '../config/index.js';
import { logger } from '../utils/logger.js';
import { AppDataSource } from '../database.js';

// User interface
export interface User {
  id: string;
  username: string;
  email: string;
  password: string;
  role: 'admin' | 'user' | 'viewer';
  isActive: boolean;
  lastLogin?: Date;
  createdAt: Date;
  updatedAt: Date;
}

// Authentication result interface
export interface AuthResult {
  success: boolean;
  user?: Omit<User, 'password'>;
  token?: string;
  refreshToken?: string;
  error?: string;
  mfaRequired?: boolean;
  pendingToken?: string;
}

// JWT Payload interface
export interface JWTPayload {
  userId: string;
  username: string;
  role: string;
  iat?: number;
  exp?: number;
}
export class AuthService {
  // Generate a long‑lived refresh token (default 7 days)
  generateRefreshToken(user: User): string {
    const payload: JWTPayload = {
      userId: user.id,
      username: user.username,
      role: user.role,
    };
    const expires = process.env.JWT_REFRESH_EXPIRES_IN || '7d';
    try {
      return jwt.sign(payload, config.jwtSecret, {
        expiresIn: expires,
        issuer: 'home-security-system',
        audience: 'home-security-client',
      } as jwt.SignOptions);
    } catch (error) {
      logger.error(`Refresh JWT signing error: ${error}`, 'AuthService');
      throw error;
    }
  }

  generateToken(user: User): string {
    const payload: JWTPayload = {
      userId: user.id,
      username: user.username,
      role: user.role,
    };

    try {
      return jwt.sign(payload, config.jwtSecret, {
        expiresIn: config.jwtExpiresIn,
        issuer: 'home-security-system',
        audience: 'home-security-client',
      } as jwt.SignOptions);
    } catch (error) {
      logger.error(`JWT signing error: ${error}`, 'AuthService');
      throw error;
    }
  }

  verifyToken(token: string): JWTPayload | null {
    try {
      const decoded = jwt.verify(token, config.jwtSecret, {
        issuer: 'home-security-system',
        audience: 'home-security-client',
      }) as JWTPayload;

      return decoded;
    } catch (error) {
      logger.warn(`JWT verification failed: ${error}`, 'AuthService');
      return null;
    }
  }

  hashPassword(password: string): Promise<string> {
    return bcrypt.hash(password, config.security.bcryptRounds);
  }

  comparePassword(password: string, hash: string): Promise<boolean> {
    return bcrypt.compare(password, hash);
  }

  async register(userData: {
    username: string;
    email: string;
    password: string;
    role?: 'admin' | 'user' | 'viewer';
  }): Promise<AuthResult> {
    try {
      if (!AppDataSource.isInitialized) {
        return { success: false, error: 'Database not available' };
      }

      const result = await AppDataSource.query(
        `SELECT id FROM users WHERE username = $1 OR email = $2`,
        [userData.username, userData.email],
      );

      if (result && result.length > 0) {
        return {
          success: false,
          error: 'User with this username or email already exists',
        };
      }

      const hashedPassword = await this.hashPassword(userData.password);
      const roleResult = await AppDataSource.query(`SELECT id FROM roles WHERE name = $1`, [
        userData.role || 'user',
      ]);
      const roleId = roleResult && roleResult.length > 0 ? roleResult[0].id : null;

      const newUserResult = await AppDataSource.query(
        `INSERT INTO users (username, email, password_hash, role_id, status, mfa_enabled, email_verified, failed_login_attempts, created_at, updated_at)
         VALUES ($1, $2, $3, $4, 'active', false, true, 0, NOW(), NOW())
         RETURNING id, username, email, created_at, updated_at`,
        [userData.username, userData.email, hashedPassword, roleId],
      );

      if (newUserResult && newUserResult.length > 0) {
        const dbUser = newUserResult[0];
        try {
          await AppDataSource.query(
            'UPDATE users SET failed_login_attempts = 0, locked_until = NULL, updated_at = NOW() WHERE id = $1',
            [dbUser.id],
          );
        } catch (resetError) {
          logger.error(
            `Failed to reset lockout counters for user ${dbUser.id}: ${resetError}`,
            'AuthService',
          );
        }

        const user: User = {
          id: dbUser.id,
          username: dbUser.username,
          email: dbUser.email,
          password: hashedPassword,
          role: userData.role || 'user',
          isActive: true,
          createdAt: dbUser.created_at,
          updatedAt: dbUser.updated_at,
        };

        logger.info(`New user registered: ${user.username}`, 'AuthService');

        const token = this.generateToken(user);
        const { password, ...userWithoutPassword } = user;

        return {
          success: true,
          user: userWithoutPassword,
          token,
        };
      }

      return { success: false, error: 'Registration failed' };
    } catch (error) {
      logger.error(`Registration error: ${error}`, 'AuthService');
      return { success: false, error: 'Registration failed' };
    }
  }

  async login(credentials: { username: string; password: string }): Promise<AuthResult> {
    try {
      if (!AppDataSource.isInitialized) {
        return { success: false, error: 'Database not available' };
      }

      const result = await AppDataSource.query(
        `SELECT u.id, u.username, u.email, u.password_hash, u.status,
                u.failed_login_attempts, u.locked_until, u.mfa_enabled,
                r.name as role_name, u.created_at, u.updated_at
         FROM users u
         LEFT JOIN roles r ON u.role_id = r.id
         WHERE u.username = $1`,
        [credentials.username],
      );

      if (!result || result.length === 0) {
        await bcrypt.compare('dummy-password', '$2b$10$0000000000000000000000000000000000000');
        return { success: false, error: 'Invalid username or password' };
      }

      const dbUser = result[0];

      if (dbUser.status !== 'active') {
        return { success: false, error: 'Account is disabled' };
      }

      if (dbUser.locked_until && new Date(dbUser.locked_until) > new Date()) {
        return {
          success: false,
          error:
            'Account is temporarily locked due to too many failed login attempts. Try again later.',
        };
      }

      const isPasswordValid = await this.comparePassword(
        credentials.password,
        dbUser.password_hash,
      );

      if (!isPasswordValid) {
        const attempts = (dbUser.failed_login_attempts || 0) + 1;
        const lockUntil =
          attempts >= config.security.maxLoginAttempts
            ? new Date(Date.now() + config.security.lockoutDuration)
            : null;

        await AppDataSource.query(
          'UPDATE users SET failed_login_attempts = $1, locked_until = $2, updated_at = NOW() WHERE id = $3',
          [attempts, lockUntil, dbUser.id],
        );

        return { success: false, error: 'Invalid username or password' };
      }

      if (dbUser.failed_login_attempts > 0 || dbUser.locked_until) {
        await AppDataSource.query(
          'UPDATE users SET failed_login_attempts = 0, locked_until = NULL, updated_at = NOW() WHERE id = $1',
          [dbUser.id],
        );
      }

      await AppDataSource.query('UPDATE users SET last_login = NOW() WHERE id = $1', [dbUser.id]);

      if (dbUser.mfa_enabled) {
        const pendingToken = jwt.sign({ userId: dbUser.id, purpose: 'mfa' }, config.jwtSecret, {
          expiresIn: '5m',
        } as jwt.SignOptions);
        return {
          success: true,
          mfaRequired: true,
          pendingToken,
          user: {
            id: dbUser.id,
            username: dbUser.username,
            email: dbUser.email,
            role: (dbUser.role_name as 'admin' | 'user' | 'viewer') || 'user',
            isActive: true,
            createdAt: dbUser.created_at,
            updatedAt: dbUser.updated_at,
          },
        };
      }

      const user: User = {
        id: dbUser.id,
        username: dbUser.username,
        email: dbUser.email,
        password: dbUser.password_hash,
        role: (dbUser.role_name as 'admin' | 'user' | 'viewer') || 'user',
        isActive: true,
        createdAt: dbUser.created_at,
        updatedAt: dbUser.updated_at,
      };

      logger.info(`User logged in: ${user.username}`, 'AuthService');

      const token = this.generateToken(user);
      const { password, ...userWithoutPassword } = user;

      return {
        success: true,
        user: userWithoutPassword,
        token,
      };
    } catch (error) {
      logger.error(`Login error: ${error}`, 'AuthService');
      return { success: false, error: 'Login failed' };
    }
  }

  async getUserById(userId: string): Promise<Omit<User, 'password'> | null> {
    try {
      if (!AppDataSource.isInitialized) {
        return null;
      }

      const result = await AppDataSource.query(
        `SELECT u.id, u.username, u.email, u.status, r.name as role_name, u.created_at, u.updated_at, u.last_login
         FROM users u
         LEFT JOIN roles r ON u.role_id = r.id
         WHERE u.id = $1`,
        [userId],
      );

      if (!result || result.length === 0) {
        return null;
      }

      const dbUser = result[0];
      return {
        id: dbUser.id,
        username: dbUser.username,
        email: dbUser.email,
        role: (dbUser.role_name as 'admin' | 'user' | 'viewer') || 'user',
        isActive: dbUser.status === 'active',
        createdAt: dbUser.created_at,
        updatedAt: dbUser.updated_at,
        lastLogin: dbUser.last_login,
      };
    } catch (error) {
      logger.error(`getUserById error: ${error}`, 'AuthService');
      return null;
    }
  }

  async getAllUsers(): Promise<Omit<User, 'password'>[]> {
    try {
      if (!AppDataSource.isInitialized) {
        return [];
      }

      const result = await AppDataSource.query(
        `SELECT u.id, u.username, u.email, u.status, r.name as role_name, u.created_at, u.updated_at, u.last_login
         FROM users u
         LEFT JOIN roles r ON u.role_id = r.id
         ORDER BY u.created_at DESC`,
      );

      return result.map((dbUser: any) => ({
        id: dbUser.id,
        username: dbUser.username,
        email: dbUser.email,
        role: (dbUser.role_name as 'admin' | 'user' | 'viewer') || 'user',
        isActive: dbUser.status === 'active',
        createdAt: dbUser.created_at,
        updatedAt: dbUser.updated_at,
        lastLogin: dbUser.last_login,
      }));
    } catch (error) {
      logger.error(`getAllUsers error: ${error}`, 'AuthService');
      return [];
    }
  }

  async changePassword(
    userId: string,
    currentPassword: string,
    newPassword: string,
  ): Promise<AuthResult> {
    try {
      if (!AppDataSource.isInitialized) {
        return { success: false, error: 'Database not available' };
      }

      const result = await AppDataSource.query(
        `SELECT id, password_hash FROM users WHERE id = $1`,
        [userId],
      );

      if (!result || result.length === 0) {
        return { success: false, error: 'User not found' };
      }

      const dbUser = result[0];
      const isCurrentPasswordValid = await this.comparePassword(
        currentPassword,
        dbUser.password_hash,
      );

      if (!isCurrentPasswordValid) {
        return { success: false, error: 'Current password is incorrect' };
      }

      const historyEntries = await AppDataSource.query(
        'SELECT password_hash FROM password_history WHERE user_id = $1 ORDER BY created_at DESC LIMIT 5',
        [userId],
      );
      for (const entry of historyEntries) {
        const isReused = await this.comparePassword(newPassword, entry.password_hash);
        if (isReused) {
          return { success: false, error: 'Cannot reuse a recent password' };
        }
      }

      const newPasswordHash = await this.hashPassword(newPassword);
      await AppDataSource.query(
        `UPDATE users SET password_hash = $1, updated_at = NOW() WHERE id = $2`,
        [newPasswordHash, userId],
      );

      await AppDataSource.query(
        `INSERT INTO password_history (id, user_id, password_hash, created_at)
         VALUES (gen_random_uuid(), $1, $2, NOW())`,
        [userId, dbUser.password_hash],
      );

      logger.info(`Password changed for user: ${userId}`, 'AuthService');
      return { success: true };
    } catch (error) {
      logger.error(`Password change error: ${error}`, 'AuthService');
      return { success: false, error: 'Password change failed' };
    }
  }
}

export const authService = new AuthService();

export default authService;

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { logger } from '../utils/logger.js';
import { decryptCredential, isEncryptedCredential } from '../services/credentialEncryption.js';
import { config, type CameraConfig } from './index.js';
import { AppDataSource } from '../database.js';
import { SecurityEvent } from '../models/SecurityEvent.js';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

async function logSecurityEventDeferred(
  eventType: string,
  details: Record<string, unknown>,
): Promise<void> {
  try {
    if (!AppDataSource.isInitialized) {
      logger.warn(`Security event (database not ready): ${eventType}`, 'Config', details);
      return;
    }
    const securityEventRepo = AppDataSource.getRepository(SecurityEvent);
    const event = securityEventRepo.create({
      eventType: eventType as any,
      details,
    });
    await securityEventRepo.save(event);
  } catch (error) {
    logger.error('Failed to log security event', 'Config', error);
  }
}

function decryptStreamPath(streamPath: string | any): string {
  if (isEncryptedCredential(streamPath)) {
    try {
      const decrypted = decryptCredential(streamPath);
      logger.debug('Successfully decrypted RTSP credential', 'Config');
      return decrypted;
    } catch (error) {
      logger.error('Failed to decrypt credential, logging security event', 'Config', error);
      logSecurityEventDeferred('CREDENTIAL_DECRYPTION_FAILED', {
        error: error instanceof Error ? error.message : String(error),
        timestamp: new Date().toISOString(),
      }).catch((err: unknown) => {
        logger.error('Deferred security log (decryption failed) failed', 'Config', err);
      });
      throw error;
    }
  } else {
    logger.warn('Detected plaintext RTSP credential in configuration', 'Config');
    logSecurityEventDeferred('PLAINTEXT_CREDENTIALS_DETECTED', {
      timestamp: new Date().toISOString(),
    }).catch((err: unknown) => {
      logger.error('Deferred security log (plaintext) failed', 'Config', err);
    });
    return streamPath;
  }
}

function convertLegacyCameraConfig(camera: any): CameraConfig {
  return {
    id: camera.id,
    name: camera.name,
    enabled: true,
    streams: [
      {
        path: camera.rtspUrl,
        roles: ['detect', 'record', 'live'],
        width: parseInt(camera.resolution?.split('x')[0]) || 1920,
        height: parseInt(camera.resolution?.split('x')[1]) || 1080,
        fps: camera.frameRate || 15,
      },
    ],
    detect: {
      width: 640,
      height: 360,
      fps: 5,
      minInitialized: 2,
      maxDisappeared: 25,
    },
    record: {
      enabled: true,
      retainDays: 30,
      mode: 'active_objects',
      alerts: {
        preCapture: 5,
        postCapture: 5,
        retainDays: 14,
      },
    },
    objects: {
      track: ['person', 'car', 'dog', 'cat'],
      filters: {
        person: {
          minArea: 5000,
          maxArea: 100000,
          threshold: 0.7,
        },
        car: {
          minArea: 10000,
          maxArea: 200000,
          threshold: 0.7,
        },
      },
    },
    nightMode: camera.nightMode || false,
    credentialId: camera.credentialId,
  };
}

export function setCameras(cameras: CameraConfig[]): void {
  config.cameras = cameras;
}

export function loadCamerasFromFile(): CameraConfig[] {
  try {
    if (process.env.CAMERAS) {
      const parsed = JSON.parse(process.env.CAMERAS);
      return parsed
        .map((camera: any) => {
          if (camera.streams && Array.isArray(camera.streams)) return camera;
          return convertLegacyCameraConfig(camera);
        })
        .map((camera: any) => ({
          ...camera,
          streams: camera.streams.map((stream: any) => ({
            ...stream,
            path: decryptStreamPath(stream.path),
          })),
        }));
    }
    const camerasPath = path.join(__dirname, '../../cameras.json');
    if (fs.existsSync(camerasPath)) {
      const camerasData = fs.readFileSync(camerasPath, 'utf8');
      const parsed = JSON.parse(camerasData);
      return parsed
        .map((camera: any) => {
          if (camera.streams && Array.isArray(camera.streams)) return camera;
          return convertLegacyCameraConfig(camera);
        })
        .map((camera: any) => ({
          ...camera,
          streams: camera.streams.map((stream: any) => ({
            ...stream,
            path: decryptStreamPath(stream.path),
          })),
        }));
    }
    return [];
  } catch (error) {
    logger.warn(
      'Failed to load cameras from file (non-critical, DB is primary source)',
      'Config',
      error,
    );
    return [];
  }
}

import dotenv from 'dotenv';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

// Get __dirname equivalent in ESM
const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

// Load environment variables
dotenv.config();

export function getOpenCVServiceUrl(): string {
  return process.env.OPENCV_SERVICE_URL || 'http://opencv:8084';
}

export interface CameraStreamConfig {
  path: string;
  roles: ('detect' | 'record' | 'live')[];
  width?: number;
  height?: number;
  fps?: number;
}

export interface ZoneConfig {
  id: string;
  name: string;
  coordinates: number[][]; // Polygon coordinates as [x, y] normalized 0-1
  objects?: string[]; // Objects that can trigger this zone
  inertia?: number; // Consecutive frames required
  loiteringTime?: number; // Seconds before considered in zone
}

export interface ObjectFilterConfig {
  minArea?: number;
  maxArea?: number;
  minRatio?: number;
  maxRatio?: number;
  minScore?: number;
  threshold?: number;
  mask?: string;
}

export interface DetectConfig {
  width: number;
  height: number;
  fps: number;
  minInitialized?: number;
  maxDisappeared?: number;
}

export interface RecordConfig {
  enabled: boolean;
  retainDays?: number;
  mode?: 'all' | 'motion' | 'active_objects';
  alerts?: {
    preCapture?: number;
    postCapture?: number;
    retainDays?: number;
  };
}

export interface LiveConfig {
  fps?: number;
}

export interface CameraConfig {
  id: string;
  name: string;
  enabled: boolean;
  streams: CameraStreamConfig[];
  detect: DetectConfig;
  live?: LiveConfig;
  record?: RecordConfig;
  zones?: ZoneConfig[];
  objects?: {
    track?: string[];
    filters?: Record<string, ObjectFilterConfig>;
  };
  motion?: {
    enabled?: boolean;
    threshold?: number;
    contourArea?: number;
    mask?: string;
  };
  nightMode: boolean;
  credentialId?: string;
  pythonEnabled?: boolean;
}

export interface DatabaseConfig {
  host: string;
  port: number;
  name: string;
  username?: string;
  password?: string;
}

export interface MQTTConfig {
  enabled?: boolean;
  host?: string;
  port?: number;
  topicPrefix?: string;
  user?: string;
  password?: string;
  qos?: 0 | 1 | 2;
}

export interface PipelineConfig {
  mode: 'legacy' | 'dual' | 'python-only';
  pythonWsUrl: string;
}

export interface AppConfig {
  port: number;
  nodeEnv: string;
  jwtSecret: string;
  jwtExpiresIn: string;
  database: DatabaseConfig;
  mqtt: MQTTConfig;
  cameras: CameraConfig[];
  security: {
    bcryptRounds: number;
    maxLoginAttempts: number;
    lockoutDuration: number;
    rateLimitWindow: number;
    rateLimitMax: number;
  };
  storage: {
    snapshotsDir: string;
    eventsDir: string;
    detectionsDir: string;
    retentionDays: number;
    archivePath: string;
    enableFileIndexing: boolean;
    fileIndexOnSave: boolean;
  };
  streaming: {
    frameInterval: number;
    lowResourceMode: boolean;
    inactivityTimeout: number;
    threads: number;
    defaultFps: number;
    defaultResolution: string;
  };
  pipeline: PipelineConfig;
}

export const config: AppConfig = {
  port: parseInt(process.env.PORT || '9753', 10),
  nodeEnv: process.env.NODE_ENV || 'development',
  jwtSecret: (() => {
    const jwtSecret = process.env.JWT_ACCESS_SECRET || process.env.JWT_SECRET;
    if (!jwtSecret) throw new Error('JWT_ACCESS_SECRET or JWT_SECRET must be configured');
    return jwtSecret;
  })(),
  jwtExpiresIn: process.env.JWT_EXPIRES_IN || '24h',
  database: {
    host: process.env.DB_HOST || 'localhost',
    port: parseInt(process.env.DB_PORT || '5432', 10),
    name: process.env.DB_NAME || 'sentryvision',
    username: process.env.DB_USER || process.env.DB_USERNAME,
    password: process.env.DB_PASSWORD,
  },
  mqtt: {
    enabled: process.env.MQTT_ENABLED === 'true',
    host: process.env.MQTT_HOST,
    port: parseInt(process.env.MQTT_PORT || '1883', 10),
    topicPrefix: process.env.MQTT_TOPIC_PREFIX || 'sentryvision',
    user: process.env.MQTT_USER,
    password: process.env.MQTT_PASSWORD,
    qos: parseInt(process.env.MQTT_QOS || '0', 10) as 0 | 1 | 2,
  },
  cameras: [] as CameraConfig[],
  security: {
    bcryptRounds: parseInt(process.env.BCRYPT_ROUNDS || '12', 10),
    maxLoginAttempts: parseInt(process.env.MAX_LOGIN_ATTEMPTS || '5', 10),
    lockoutDuration: parseInt(process.env.LOCKOUT_DURATION || '900000', 10), // 15 minutes
    rateLimitWindow: parseInt(process.env.RATE_LIMIT_WINDOW || '900000', 10), // 15 minutes
    rateLimitMax: parseInt(process.env.RATE_LIMIT_MAX || '100', 10),
  },
  storage: {
    snapshotsDir: process.env.SNAPSHOTS_DIR || path.join(process.cwd(), '../public/snapshots'),
    eventsDir: process.env.EVENTS_DIR || path.join(process.cwd(), '../public/events'),
    detectionsDir: process.env.DETECTIONS_DIR || path.join(process.cwd(), '../data/detections'),
    retentionDays: parseInt(process.env.DETECTIONS_RETENTION_DAYS || '7', 10),
    archivePath:
      process.env.DETECTIONS_ARCHIVE_PATH || path.join(process.cwd(), '../data/detections/archive'),
    enableFileIndexing: process.env.ENABLE_FILE_INDEXING === 'true',
    fileIndexOnSave: process.env.FILE_INDEX_ON_SAVE === 'true',
  },
  streaming: {
    frameInterval: parseInt(process.env.FRAME_INTERVAL || '1000', 10),
    lowResourceMode: process.env.LOW_RESOURCE_MODE === 'true',
    inactivityTimeout: parseInt(process.env.STREAM_INACTIVITY_TIMEOUT || '300000', 10),
    threads: parseInt(process.env.FFMPEG_THREADS || '2', 10),
    defaultFps: parseInt(process.env.DEFAULT_FPS || '2', 10),
    defaultResolution: process.env.DEFAULT_RESOLUTION || '640x360',
  },
  pipeline: {
    mode: (process.env.PIPELINE_MODE as PipelineConfig['mode']) || 'python-only',
    pythonWsUrl: process.env.PYTHON_WS_URL || 'ws://opencv:9090',
  },
};

export interface StreamingConfig {
  frameInterval: number;
  lowResourceMode: boolean;
  inactivityTimeout: number;
  threads: number;
  defaultFps: number;
  defaultResolution: string;
}

export const getCameraById = (id: string): CameraConfig | undefined => {
  return config.cameras.find((camera) => camera.id === id);
};

export function setCameras(cameras: CameraConfig[]): void {
  config.cameras = cameras;
}

export const validateConfig = (): void => {
  const errors: string[] = [];

  if (!Number.isInteger(config.port) || config.port <= 0 || config.port > 65535) {
    errors.push(`Invalid port: ${config.port}`);
  }

  if (!['development', 'test', 'production'].includes(config.nodeEnv)) {
    errors.push(`Invalid NODE_ENV: ${config.nodeEnv}`);
  }

  if (!config.jwtSecret || config.jwtSecret.length < 32) {
    errors.push('JWT_ACCESS_SECRET must be at least 32 characters long');
  }

  if (
    config.database.host &&
    config.database.port &&
    (config.database.port <= 0 || config.database.port > 65535)
  ) {
    errors.push(`Invalid database port: ${config.database.port}`);
  }

  if (config.security.bcryptRounds < 4 || config.security.bcryptRounds > 15) {
    errors.push(`Invalid BCRYPT_ROUNDS: ${config.security.bcryptRounds} (expected 4-15)`);
  }

  if (config.security.maxLoginAttempts < 1) {
    errors.push(`Invalid MAX_LOGIN_ATTEMPTS: ${config.security.maxLoginAttempts}`);
  }

  if (config.streaming.frameInterval <= 0) {
    errors.push(`Invalid FRAME_INTERVAL: ${config.streaming.frameInterval}`);
  }

  if (config.streaming.defaultFps <= 0 || config.streaming.defaultFps > 60) {
    errors.push(`Invalid DEFAULT_FPS: ${config.streaming.defaultFps}`);
  }

  if (config.storage.retentionDays < 1) {
    errors.push(`Invalid DETECTIONS_RETENTION_DAYS: ${config.storage.retentionDays}`);
  }

  if (!['legacy', 'dual', 'python-only'].includes(config.pipeline.mode)) {
    errors.push(`Invalid PIPELINE_MODE: ${config.pipeline.mode}`);
  }

  if (config.mqtt.enabled && !config.mqtt.host) {
    errors.push('MQTT_ENABLED requires MQTT_HOST to be set');
  }

  for (const camera of config.cameras) {
    if (!camera.id || !camera.name) {
      errors.push('Every camera must have an id and name');
    }
    if (!Array.isArray(camera.streams) || camera.streams.length === 0) {
      errors.push(`Camera ${camera.id || 'unknown'} must have at least one stream`);
    }
  }

  if (errors.length > 0) {
    throw new Error(`Configuration validation failed:\n- ${errors.join('\n- ')}`);
  }
};

import { logger } from '../utils/logger.js';
import { Request, Response } from 'express';
import { BaseController } from './BaseController.js';
import { inMemoryState } from '../services/inMemoryStateService.js';

export class AnalyticsController extends BaseController {
  async getStorageStats(req: Request, res: Response): Promise<void> {
    try {
      const { AppDataSource } = await import('../database.js');
      const dbResult = await AppDataSource.query(
        `SELECT COALESCE(SUM(file_size), 0) as total_bytes FROM detection_files WHERE is_deleted = FALSE`,
      );
      const storageUsed = parseInt(dbResult[0]?.total_bytes) || 0;

      const { config } = await import('../config/index.js');
      let storageTotal = 0;
      try {
        const fs = await import('node:fs');
        const detectionsPath = config.storage.detectionsDir;
        if (fs.existsSync(detectionsPath)) {
          const stat = fs.statfsSync(detectionsPath);
          storageTotal = stat.blocks * stat.bsize;
        }
      } catch (err) {
        logger.warn('Failed to get filesystem storage stats', 'Analytics', err);
      }

      this.ok(res, { storageUsed, storageTotal });
    } catch (error) {
      this.serverError(res, error, 'getStorageStats');
    }
  }

  async getHourly(req: Request, res: Response): Promise<void> {
    try {
      const { AppDataSource } = await import('../database.js');
      const startDate = (req.query.startDate as string) || new Date().toISOString().split('T')[0];
      const endDate = (req.query.endDate as string) || new Date().toISOString();

      const result = await AppDataSource.query(
        `SELECT EXTRACT(HOUR FROM timestamp) as hour, COUNT(*) as count
         FROM events
         WHERE timestamp >= $1::timestamptz AND timestamp <= $2::timestamptz
         GROUP BY hour
         ORDER BY hour`,
        [startDate, endDate],
      );

      const hourlyData = Array(24)
        .fill(null)
        .map((_, hour) => ({ hour, count: 0 }));
      result.forEach((row: { hour: number; count: number }) => {
        const h = parseInt(String(row.hour));
        if (h >= 0 && h < 24) {
          hourlyData[h].count = parseInt(String(row.count));
        }
      });

      this.ok(res, { hourlyData });
    } catch (error) {
      this.serverError(res, error, 'getHourly');
    }
  }

  getWeekly(req: Request, res: Response): void {
    try {
      const today = new Date();
      const oneWeekAgo = new Date(today.getTime() - 7 * 24 * 60 * 60 * 1000);
      const recentEvents = inMemoryState.getRecentEvents();
      const weeklyEvents = recentEvents.filter((event) => {
        const eventDate = new Date(event.timestamp);
        return eventDate >= oneWeekAgo && eventDate <= today;
      });

      this.ok(res, {
        weeklyData: {
          totalEvents: weeklyEvents.length,
          dailyBreakdown: Array(7)
            .fill(null)
            .map((_, dayIndex) => {
              const date = new Date(today.getTime() - dayIndex * 24 * 60 * 60 * 1000);
              const dayStart = new Date(date.getFullYear(), date.getMonth(), date.getDate());
              const dayEnd = new Date(dayStart.getTime() + 24 * 60 * 60 * 1000);
              const dayEvents = weeklyEvents.filter((event) => {
                const eventDate = new Date(event.timestamp);
                return eventDate >= dayStart && eventDate < dayEnd;
              });
              return { date: dayStart.toISOString().split('T')[0], count: dayEvents.length };
            })
            .reverse(),
        },
      });
    } catch (error) {
      this.serverError(res, error, 'getWeekly');
    }
  }

  getMonthly(req: Request, res: Response): void {
    try {
      const today = new Date();
      const oneMonthAgo = new Date(today.getFullYear(), today.getMonth() - 1, today.getDate());
      const recentEvents = inMemoryState.getRecentEvents();
      const monthlyEvents = recentEvents.filter((event) => {
        const eventDate = new Date(event.timestamp);
        return eventDate >= oneMonthAgo && eventDate <= today;
      });

      this.ok(res, {
        monthlyData: {
          totalEvents: monthlyEvents.length,
          weeklyBreakdown: Array(4)
            .fill(null)
            .map((_, weekIndex) => {
              const weekStart = new Date(
                today.getTime() - (weekIndex + 1) * 7 * 24 * 60 * 60 * 1000,
              );
              const weekEnd = new Date(weekStart.getTime() + 7 * 24 * 60 * 60 * 1000);
              const weekEvents = monthlyEvents.filter((event: any) => {
                const eventDate = new Date(event.timestamp);
                return eventDate >= weekStart && eventDate < weekEnd;
              });
              return { week: `Week ${4 - weekIndex}`, count: weekEvents.length };
            })
            .reverse(),
        },
      });
    } catch (error) {
      this.serverError(res, error, 'getMonthly');
    }
  }
}

export const analyticsController = new AnalyticsController();

import { Request, Response } from 'express';
import crypto from 'crypto';
import jwt from 'jsonwebtoken';
import speakeasy from 'speakeasy';
import QRCode from 'qrcode';
import { BaseController } from './BaseController.js';
import authService, { AuthService, User, JWTPayload } from '../auth/index.js';
import { config } from '../config/index.js';
import { AppDataSource } from '../database.js';
import auditLogger from '../utils/auditLogger.js';
import { logger } from '../utils/logger.js';
import { invalidateSessionCache } from '../middleware/auth.js';

export class AuthController extends BaseController {
  private authService: AuthService;

  constructor(authServiceInstance: AuthService) {
    super();
    this.authService = authServiceInstance;
  }

  async register(req: Request, res: Response): Promise<void> {
    try {
      const { username, email, password, role } = req.body;
      const result = await this.authService.register({ username, email, password, role });

      if (result.success) {
        auditLogger.log({
          level: 'INFO',
          category: 'AUTH',
          action: 'USER_REGISTER',
          userId: result.user?.id,
          username: result.user?.username,
          ip: auditLogger.getClientIP(req),
          userAgent: req.get('User-Agent'),
          details: { email, role: role || 'user' },
          success: true,
        });
        logger.info(`User registered successfully: ${username}`, 'AuthRoutes');
        this.created(res, {
          message: 'User registered successfully',
          user: result.user as Record<string, unknown>,
          token: result.token,
        });
      } else {
        auditLogger.log({
          level: 'WARN',
          category: 'AUTH',
          action: 'USER_REGISTER_FAILED',
          username: username,
          ip: auditLogger.getClientIP(req),
          userAgent: req.get('User-Agent'),
          details: { email, error: result.error },
          success: false,
        });
        this.badRequest(res, result.error || 'Registration failed');
      }
    } catch (error) {
      this.serverError(res, error, 'register');
    }
  }

  async login(req: Request, res: Response): Promise<void> {
    try {
      const { username, password } = req.body;
      const result = await this.authService.login({ username, password });

      if (result.success) {
        auditLogger.log({
          level: 'INFO',
          category: 'AUTH',
          action: 'USER_LOGIN',
          userId: result.user?.id,
          username: result.user?.username,
          ip: auditLogger.getClientIP(req),
          userAgent: req.get('User-Agent'),
          details: { loginMethod: 'password' },
          success: true,
        });
        if (result.user?.id && result.token) {
          const sessionIp1 = req.ip && req.ip !== '' ? req.ip : '0.0.0.0';
          const refreshTokenHash = crypto.createHash('sha256').update(result.token).digest('hex');
          const accessTokenHash = crypto.createHash('sha256').update(result.token).digest('hex');
          await AppDataSource.query(
            `INSERT INTO user_sessions (id, user_id, refresh_token, access_token_hash, ip_address, user_agent, device_info, is_active, expires_at)
             VALUES (gen_random_uuid(), $1, $2, $3, $4, $5, '{}'::jsonb, true, NOW() + INTERVAL '7 days')`,
            [
              result.user.id,
              refreshTokenHash,
              accessTokenHash,
              sessionIp1,
              req.get('User-Agent') || '',
            ],
          ).catch((err) => logger.error(`Failed to create user session: ${err}`, 'AuthRoutes'));
        }
        if (result.mfaRequired) {
          this.ok(res, {
            message: 'MFA verification required',
            mfaRequired: true,
            pendingToken: result.pendingToken,
            user: result.user as Record<string, unknown>,
          });
          return;
        }
        logger.info(`User logged in successfully: ${username}`, 'AuthRoutes');
        this.ok(res, {
          message: 'Login successful',
          user: result.user as Record<string, unknown>,
          token: result.token,
        });
      } else {
        auditLogger.log({
          level: 'WARN',
          category: 'AUTH',
          action: 'USER_LOGIN_FAILED',
          username: username,
          ip: auditLogger.getClientIP(req),
          userAgent: req.get('User-Agent'),
          details: { error: result.error },
          success: false,
        });
        res.status(401).json({ success: false, error: result.error });
      }
    } catch (error) {
      this.serverError(res, error, 'login');
    }
  }

  async getProfile(req: Request, res: Response): Promise<void> {
    try {
      if (!req.user) {
        res.status(401).json({ success: false, error: 'User not authenticated' });
        return;
      }

      const user = await this.authService.getUserById(req.user.userId);

      if (!user) {
        this.notFound(res, 'User not found');
        return;
      }

      this.ok(res, { user: user as unknown as Record<string, unknown> });
    } catch (error) {
      this.serverError(res, error, 'getProfile');
    }
  }

  async changePassword(req: Request, res: Response): Promise<void> {
    try {
      if (!req.user) {
        res.status(401).json({ success: false, error: 'User not authenticated' });
        return;
      }

      const { currentPassword, newPassword } = req.body;
      const result = await this.authService.changePassword(
        req.user.userId,
        currentPassword,
        newPassword,
      );

      if (result.success) {
        logger.info(`Password changed for user: ${req.user.username}`, 'AuthRoutes');
        this.ok(res, { message: 'Password changed successfully' });
      } else {
        this.badRequest(res, result.error || 'Password change failed');
      }
    } catch (error) {
      this.serverError(res, error, 'changePassword');
    }
  }

  async refreshToken(req: Request, res: Response): Promise<void> {
    try {
      if (!req.user) {
        res.status(401).json({ success: false, error: 'Not authenticated' });
        return;
      }

      const payload: JWTPayload = {
        userId: req.user.userId,
        username: req.user.username,
        role: req.user.role,
      };

      const user = await this.authService.getUserById(payload.userId);

      if (!user) {
        this.notFound(res, 'User not found');
        return;
      }

      try {
        const userForToken: User = {
          id: user.id,
          username: user.username,
          email: user.email,
          password: '',
          role: user.role,
          isActive: user.isActive,
          createdAt: new Date(user.createdAt),
          updatedAt: new Date(user.updatedAt),
        };
        const newToken = this.authService.generateToken(userForToken);
        this.ok(res, { token: newToken });
      } catch (error) {
        logger.error(`Token refresh error during JWT signing: ${error}`, 'AuthRoutes');
        this.serverError(res, error, 'Token refresh failed - JWT signing error');
      }
    } catch (error) {
      this.serverError(res, error, 'refreshToken');
    }
  }

  async logout(req: Request, res: Response): Promise<void> {
    try {
      auditLogger.log({
        level: 'INFO',
        category: 'AUTH',
        action: 'USER_LOGOUT',
        userId: req.user?.userId,
        username: req.user?.username,
        ip: auditLogger.getClientIP(req),
        userAgent: req.get('User-Agent'),
        success: true,
      });
      if (req.user?.userId) {
        await AppDataSource.query('DELETE FROM user_sessions WHERE user_id = $1', [
          req.user.userId,
        ]).catch((err) =>
          logger.error(`Failed to delete user sessions on logout: ${err}`, 'AuthRoutes'),
        );
        invalidateSessionCache(req.user.userId);
      }
      logger.info(`User logged out: ${req.user?.username}`, 'AuthRoutes');
      this.ok(res, { message: 'Logout successful' });
    } catch (error) {
      auditLogger.log({
        level: 'ERROR',
        category: 'AUTH',
        action: 'USER_LOGOUT_FAILED',
        userId: req.user?.userId,
        username: req.user?.username,
        ip: auditLogger.getClientIP(req),
        userAgent: req.get('User-Agent'),
        details: { error: error instanceof Error ? error.message : 'Unknown error' },
        success: false,
      });
      this.serverError(res, error, 'logout');
    }
  }

  async disableMfa(req: Request, res: Response): Promise<void> {
    try {
      const userId = req.user?.userId;
      if (!userId) {
        res.status(401).json({ success: false, error: 'Not authenticated' });
        return;
      }

      await AppDataSource.query(
        'UPDATE users SET mfa_enabled = false, mfa_secret = NULL, updated_at = NOW() WHERE id = $1',
        [userId],
      );

      auditLogger.log({
        level: 'INFO',
        category: 'AUTH',
        action: 'MFA_DISABLED',
        userId: req.user?.userId,
        username: req.user?.username,
        ip: auditLogger.getClientIP(req),
        userAgent: req.get('User-Agent'),
        success: true,
      });

      this.ok(res, { message: 'MFA disabled successfully' });
    } catch (error) {
      this.serverError(res, error, 'disableMfa');
    }
  }

  async setupMfa(req: Request, res: Response): Promise<void> {
    try {
      const userId = req.user?.userId;
      if (!userId) {
        res.status(401).json({ success: false, error: 'Not authenticated' });
        return;
      }

      const secret = speakeasy.generateSecret({
        name: `SentryVision:${req.user?.username || userId}`,
        length: 20,
      });

      await AppDataSource.query(
        'UPDATE users SET mfa_secret = $1, updated_at = NOW() WHERE id = $2',
        [secret.base32, userId],
      );

      const qrCode = await QRCode.toDataURL(secret.otpauth_url || '');

      this.ok(res, {
        qrCode,
        secretPreview: `...${secret.base32.slice(-4)}`,
      });
    } catch (error) {
      this.serverError(res, error, 'setupMfa');
    }
  }

  async mfaChallenge(req: Request, res: Response): Promise<void> {
    try {
      const { pendingToken, code } = req.body;
      if (!pendingToken || !code) {
        this.badRequest(res, 'pendingToken and code are required');
        return;
      }

      let payload: { userId: string; purpose: string };
      try {
        const decoded = jwt.verify(pendingToken, config.jwtSecret) as {
          userId: string;
          purpose: string;
        };
        payload = decoded;
      } catch {
        res.status(401).json({ success: false, error: 'Invalid or expired pending token' });
        return;
      }

      if (payload.purpose !== 'mfa') {
        res.status(401).json({ success: false, error: 'Invalid token purpose' });
        return;
      }

      const [user] = await AppDataSource.query(
        'SELECT mfa_secret, username, email FROM users WHERE id = $1',
        [payload.userId],
      );

      if (!user || !user.mfa_secret) {
        this.badRequest(res, 'MFA not configured');
        return;
      }

      const verified = speakeasy.totp.verify({
        secret: user.mfa_secret,
        encoding: 'base32',
        token: code,
        window: 2,
      });

      if (!verified) {
        auditLogger.log({
          level: 'WARN',
          category: 'AUTH',
          action: 'MFA_CHALLENGE_FAILED',
          userId: payload.userId,
          ip: auditLogger.getClientIP(req),
          userAgent: req.get('User-Agent'),
          success: false,
        });
        this.badRequest(res, 'Invalid MFA code');
        return;
      }

      const result = await AppDataSource.query(
        `SELECT u.id, u.username, u.email, u.status, r.name as role_name, u.created_at, u.updated_at
         FROM users u
         LEFT JOIN roles r ON u.role_id = r.id
         WHERE u.id = $1`,
        [payload.userId],
      );

      const dbUser = result[0];
      const userForToken: User = {
        id: dbUser.id,
        username: dbUser.username,
        email: dbUser.email,
        password: '',
        role: (dbUser.role_name as 'admin' | 'user' | 'viewer') || 'user',
        isActive: dbUser.status === 'active',
        createdAt: dbUser.created_at,
        updatedAt: dbUser.updated_at,
      };

      const token = this.authService.generateToken(userForToken);

      auditLogger.log({
        level: 'INFO',
        category: 'AUTH',
        action: 'MFA_CHALLENGE_SUCCESS',
        userId: payload.userId,
        username: dbUser.username,
        ip: auditLogger.getClientIP(req),
        userAgent: req.get('User-Agent'),
        success: true,
      });

      const sessionIp2 = req.ip && req.ip !== '' ? req.ip : '0.0.0.0';
      const refreshTokenHash2 = crypto.createHash('sha256').update(token).digest('hex');
      const accessTokenHash2 = crypto.createHash('sha256').update(token).digest('hex');
      await AppDataSource.query(
        `INSERT INTO user_sessions (id, user_id, refresh_token, access_token_hash, ip_address, user_agent, device_info, is_active, expires_at)
          VALUES (gen_random_uuid(), $1, $2, $3, $4, $5, '{}'::jsonb, true, NOW() + INTERVAL '7 days')`,
        [dbUser.id, refreshTokenHash2, accessTokenHash2, sessionIp2, req.get('User-Agent') || ''],
      ).catch((err) => logger.error(`Failed to create user session: ${err}`, 'AuthRoutes'));

      const { password: _, ...userWithoutPassword } = userForToken;
      this.ok(res, {
        message: 'Login successful',
        user: userWithoutPassword as unknown as Record<string, unknown>,
        token,
      });
    } catch (error) {
      this.serverError(res, error, 'mfaChallenge');
    }
  }

  async verifyMfa(req: Request, res: Response): Promise<void> {
    try {
      const { code } = req.body;
      if (!code) {
        this.badRequest(res, 'MFA code is required');
        return;
      }

      const userId = req.user?.userId;
      if (!userId) {
        res.status(401).json({ success: false, error: 'Not authenticated' });
        return;
      }

      const [user] = await AppDataSource.query(
        'SELECT mfa_secret, mfa_enabled FROM users WHERE id = $1',
        [userId],
      );

      if (!user || !user.mfa_secret) {
        this.badRequest(res, 'MFA not set up. Call setup first.');
        return;
      }

      const verified = speakeasy.totp.verify({
        secret: user.mfa_secret,
        encoding: 'base32',
        token: code,
        window: 2,
      });

      if (verified) {
        if (!user.mfa_enabled) {
          await AppDataSource.query(
            'UPDATE users SET mfa_enabled = true, updated_at = NOW() WHERE id = $1',
            [userId],
          );
        }

        auditLogger.log({
          level: 'INFO',
          category: 'AUTH',
          action: 'MFA_VERIFIED',
          userId: req.user?.userId,
          username: req.user?.username,
          ip: auditLogger.getClientIP(req),
          userAgent: req.get('User-Agent'),
          success: true,
        });
        this.ok(res, { message: 'MFA verified successfully' });
      } else {
        this.badRequest(res, 'Invalid MFA code');
      }
    } catch (error) {
      this.serverError(res, error, 'verifyMfa');
    }
  }
}

