export const nvidiaController = new NvidiaController();

import { logger } from '../utils/logger.js';
import { Request, Response } from 'express';
import { BaseController } from './BaseController.js';
import { serviceRegistry } from '../services/serviceRegistry.js';

export class StreamController extends BaseController {
  getMetrics(req: Request, res: Response): void {
    try {
      const streamManager = serviceRegistry.getStreamManager();
      const cameras = streamManager.getAllCameras();
      const metrics = cameras.map((camera: any) => ({
        cameraId: camera.id,
        cameraName: camera.name,
        viewerCount: camera.activeViewers?.size || 0,
        adaptiveFps: camera.adaptiveFps || 4,
        isActive: camera.isActive,
        bandwidth: camera.lastFrame?.length || 0,
        fps: camera.adaptiveFps || 4,
      }));

      res.json({
        success: true,
        metrics,
        totalViewers: metrics.reduce((sum: number, m: any) => sum + m.viewerCount, 0),
        timestamp: new Date().toISOString(),
      });
    } catch (error) {
      res.status(500).json({
        success: false,
        error: 'Failed to get streaming metrics',
        details: error instanceof Error ? error.message : 'Unknown error',
      });
    }
  }

  getSnapshot(req: Request, res: Response): void {
    const cameraId = req.params.cameraId;
    if (!cameraId || !/^[a-zA-Z0-9_-]+$/.test(cameraId) || cameraId.length > 100) {
      res.status(400).json({ success: false, error: 'Invalid camera ID format' });
      return;
    }

    try {
      const streamManager = serviceRegistry.getStreamManager();
      const camera = streamManager.getAllCameras().find((c: any) => c.id === cameraId);
      if (!camera) {
        res.status(404).json({ success: false, error: 'Camera not found' });
        return;
      }

      if (!camera.isActive || !camera.lastFrame) {
        const placeholder = Buffer.from([
          0xff, 0xd8, 0xff, 0xe0, 0x00, 0x10, 0x4a, 0x46, 0x49, 0x46, 0x00, 0x01, 0x01, 0x01, 0x00,
          0x48, 0x00, 0x48, 0x00, 0x00, 0xff, 0xdb, 0x00, 0x43,
        ]);
        res.writeHead(200, {
          'Content-Type': 'image/jpeg',
          'Content-Length': placeholder.length.toString(),
          'Cache-Control': 'no-cache, no-store, must-revalidate',
          Pragma: 'no-cache',
        });
        res.end(placeholder);
        return;
      }

      res.writeHead(200, {
        'Content-Type': 'image/jpeg',
        'Content-Length': camera.lastFrame.length.toString(),
        'Cache-Control': 'no-cache, no-store, must-revalidate',
        Pragma: 'no-cache',
        'Access-Control-Allow-Origin': '*',
      });
      res.end(camera.lastFrame);
    } catch (error) {
      logger.error(`Error getting snapshot for camera ${cameraId}`, 'Stream', error);
      res.status(500).json({ success: false, error: 'Failed to get snapshot' });
    }
  }

  getMjpegStream(req: Request, res: Response): void {
    const cameraId = req.params.cameraId;
    if (!cameraId || !/^[a-zA-Z0-9_-]+$/.test(cameraId) || cameraId.length > 100) {
      res.status(400).json({ success: false, error: 'Invalid camera ID format' });
      return;
    }

    try {
      const streamManager = serviceRegistry.getStreamManager();
      const camera = streamManager.getAllCameras().find((c: any) => c.id === cameraId);
      if (!camera) {
        res.status(404).json({ success: false, error: 'Camera not found' });
        return;
      }
      if (!camera.isActive) {
        res.status(503).json({ success: false, error: 'Camera is not streaming' });
        return;
      }

      const boundary = '--myboundary';
      res.writeHead(200, {
        'Content-Type': `multipart/x-mixed-replace; boundary=${boundary}`,
        'Cache-Control': 'no-cache, no-store, must-revalidate',
        Pragma: 'no-cache',
        Connection: 'close',
        'Access-Control-Allow-Origin': '*',
        'Access-Control-Allow-Headers': 'Cache-Control',
      });

      let isActive = true;
      const sendFrame = () => {
        if (!isActive || !camera.lastFrame) return;
        const frame = camera.lastFrame;
        try {
          res.write(
            `--${boundary}\r\nContent-Type: image/jpeg\r\nContent-Length: ${frame.length}\r\n\r\n`,
          );
          res.write(frame);
          res.write(`\r\n--${boundary}\r\n`);
        } catch {
          isActive = false;
        }
      };
      const interval = setInterval(sendFrame, 250);
      res.write(`--${boundary}\r\n`);
      req.on('close', () => {
        isActive = false;
        clearInterval(interval);
        try {
          res.write(`--${boundary}--\r\n`);
          res.end();
        } catch {}
      });
      req.on('aborted', () => {
        isActive = false;
        clearInterval(interval);
      });
    } catch (error) {
      logger.error(`Error serving stream for camera ${cameraId}`, 'Stream', error);
      if (!res.headersSent)
        res.status(500).json({ success: false, error: 'Failed to serve stream' });
    }
  }

  getDetectStream(req: Request, res: Response): void {
    const cameraId = req.params.cameraId;
    if (!cameraId || !/^[a-zA-Z0-9_-]+$/.test(cameraId) || cameraId.length > 100) {
      res.status(400).json({ success: false, error: 'Invalid camera ID format' });
      return;
    }

    try {
      const streamManager = serviceRegistry.getStreamManager();
      const camera = streamManager.getCamera(cameraId);
      if (!camera) {
        res.status(404).json({ success: false, error: 'Camera not found' });
        return;
      }

      if (!camera.isActive) streamManager.startStream(cameraId, 'live');

      const boundary = '--myboundary';
      res.writeHead(200, {
        'Content-Type': `multipart/x-mixed-replace; boundary=${boundary}`,
        'Cache-Control': 'no-cache, no-store, must-revalidate',
        Pragma: 'no-cache',
        Connection: 'close',
        'Access-Control-Allow-Origin': '*',
        'Access-Control-Allow-Headers': 'Cache-Control',
      });

      let isActive = true;
      const sendFrame = () => {
        if (!isActive || !camera.lastFrame) return;
        const frame = camera.lastFrame;
        try {
          res.write(
            `--${boundary}\r\nContent-Type: image/jpeg\r\nContent-Length: ${frame.length}\r\n\r\n`,
          );
          res.write(frame);
          res.write(`\r\n--${boundary}\r\n`);
        } catch {
          isActive = false;
        }
      };
      const interval = setInterval(sendFrame, 250);
      res.write(`--${boundary}\r\n`);
      req.on('close', () => {
        isActive = false;
        clearInterval(interval);
        try {
          res.write(`--${boundary}--\r\n`);
          res.end();
        } catch {}
      });
      req.on('aborted', () => {
        isActive = false;
        clearInterval(interval);
      });
    } catch (error) {
      logger.error(`Error serving detect stream for camera ${cameraId}`, 'Stream', error);
      if (!res.headersSent)
        res.status(500).json({ success: false, error: 'Failed to serve detect stream' });
    }
  }

  getLiveStream(req: Request, res: Response): void {
    const cameraId = req.params.cameraId;
    if (!cameraId || !/^[a-zA-Z0-9_-]+$/.test(cameraId) || cameraId.length > 100) {
      res.status(400).json({ success: false, error: 'Invalid camera ID format' });
      return;
    }

    try {
      const streamManager = serviceRegistry.getStreamManager();
      const camera = streamManager.getCamera(cameraId);
      if (!camera) {
        res.status(404).json({ success: false, error: 'Camera not found' });
        return;
      }

      if (!camera.isActive) streamManager.startStream(cameraId, 'live');

      const boundary = '--myboundary';
      res.writeHead(200, {
        'Content-Type': `multipart/x-mixed-replace; boundary=${boundary}`,
        'Cache-Control': 'no-cache, no-store, must-revalidate',
        Pragma: 'no-cache',
        Connection: 'close',
        'Access-Control-Allow-Origin': '*',
        'Access-Control-Allow-Headers': 'Cache-Control',
      });

      let isActive = true;
      const sendFrame = () => {
        if (!isActive || !camera.lastFrame) return;
        const frame = camera.lastFrame;
        try {
          res.write(
            `--${boundary}\r\nContent-Type: image/jpeg\r\nContent-Length: ${frame.length}\r\n\r\n`,
          );
          res.write(frame);
          res.write(`\r\n--${boundary}\r\n`);
        } catch {
          isActive = false;
        }
      };
      const interval = setInterval(sendFrame, 250);
      res.write(`--${boundary}\r\n`);
      req.on('close', () => {
        isActive = false;
        clearInterval(interval);
        try {
          res.write(`--${boundary}--\r\n`);
          res.end();
        } catch {}
      });
      req.on('aborted', () => {
        isActive = false;
        clearInterval(interval);
      });
    } catch (error) {
      logger.error(`Error serving live stream for camera ${cameraId}`, 'Stream', error);
      if (!res.headersSent)
        res.status(500).json({ success: false, error: 'Failed to serve live stream' });
    }
  }

  getFrame(req: Request, res: Response): void {
    const cameraId = req.params.cameraId;
    if (!cameraId || !/^[a-zA-Z0-9_-]+$/.test(cameraId) || cameraId.length > 100) {
      res.status(400).json({ success: false, error: 'Invalid camera ID format' });
      return;
    }

    try {
      const streamManager = serviceRegistry.getStreamManager();
      const camera = streamManager.getCamera(cameraId);
      if (!camera) {
        res.status(404).json({ success: false, error: 'Camera not found' });
        return;
      }

      if (!camera.lastFrame) {
        res.status(503).json({ success: false, error: 'No frame available' });
        return;
      }

      res.writeHead(200, {
        'Content-Type': 'image/jpeg',
        'Content-Length': camera.lastFrame.length.toString(),
        'Cache-Control': 'no-cache, no-store, must-revalidate',
        'Access-Control-Allow-Origin': '*',
      });
      res.end(camera.lastFrame);
    } catch (error) {
      logger.error(`Error getting frame for camera ${cameraId}`, 'Stream', error);
      res.status(500).json({ success: false, error: 'Failed to get frame' });
    }
  }

  getStreamStatus(req: Request, res: Response): void {
    const cameraId = req.params.cameraId;
    if (!cameraId || !/^[a-zA-Z0-9_-]+$/.test(cameraId) || cameraId.length > 100) {
      res.status(400).json({ success: false, error: 'Invalid camera ID format' });
      return;
    }

    try {
      const streamManager = serviceRegistry.getStreamManager();
      const camera = streamManager.getCamera(cameraId);
      if (!camera) {
        res.status(404).json({ success: false, error: 'Camera not found' });
        return;
      }

      const streams = {
        live: {
          isActive: camera.isActive,
          fps: camera.adaptiveFps || 4,
          hasFrame: !!camera.lastFrame,
          frameSize: camera.lastFrame?.length || 0,
        },
      };

      res.json({
        success: true,
        cameraId,
        cameraName: camera.name,
        isActive: camera.isActive,
        streams,
        timestamp: new Date().toISOString(),
      });
    } catch (error) {
      logger.error(`Error getting stream status for camera ${cameraId}`, 'Stream', error);
      res.status(500).json({ success: false, error: 'Failed to get stream status' });
    }
  }
}

export const streamController = new StreamController();

import { logger } from '../utils/logger.js';
import { Request, Response } from 'express';
import path from 'node:path';
import fs from 'node:fs';
import { promises as fsp } from 'node:fs';
import os from 'node:os';
import { fileURLToPath } from 'url';
import { BaseController } from './BaseController.js';
import { serviceRegistry } from '../services/serviceRegistry.js';
import { inMemoryState, MotionEvent } from '../services/inMemoryStateService.js';
import { AutomatedCleanupService } from '../services/automatedCleanupService.js';
import type { Camera } from '../streams/rtspManager.js';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

export class SystemController extends BaseController {
  async health(req: Request, res: Response): Promise<void> {
    let db = 'unknown';
    try {
      const { AppDataSource } = await import('../database.js');
      await AppDataSource.query('SELECT 1');
      db = 'ok';
    } catch {
      db = 'error';
    }

    let pipeline = 'unknown';
    try {
      const pythonWs = serviceRegistry.getPythonWsClient();
      pipeline = pythonWs.connected ? 'connected' : 'disconnected';
    } catch {
      pipeline = 'unavailable';
    }

    try {
      const streamManager = serviceRegistry.getStreamManager();
      const cameras = streamManager.getAllCameras();
      const overallStatus = db === 'ok' && pipeline === 'connected' ? 'ok' : 'degraded';
      res.json({
        status: overallStatus,
        timestamp: new Date().toISOString(),
        activeCameras: cameras.filter((c: Camera) => c.isActive).length,
        db,
        pipeline,
      });
    } catch (error) {
      res.json({
        status: db === 'ok' ? 'degraded' : 'error',
        timestamp: new Date().toISOString(),
        activeCameras: 0,
        db,
        pipeline,
      });
    }
  }

  async stats(req: Request, res: Response): Promise<void> {
    try {
      const { AppDataSource } = await import('../database.js');
      const { Event } = await import('../models/index.js');

      const eventRepo = AppDataSource.getRepository(Event);
      const totalEvents = await eventRepo.count();

      const streamManager = serviceRegistry.getStreamManager();
      const cameras = streamManager.getAllCameras();
      const activeCameras = cameras.filter((c: Camera) => c.isActive).length;

      let knownVisitors = 0;
      try {
        const visitorResult = await AppDataSource.query(
          'SELECT COUNT(Distinct visitor_id) as count FROM visitor_timeline',
        );
        knownVisitors = parseInt(visitorResult?.[0]?.count) || 0;
      } catch (err) {
        logger.warn('Failed to query visitor count', 'System', err);
      }

      let storageUsed = 0;
      let storageTotal = 0;
      try {
        const { config } = await import('../config/index.js');
        const dbResult = await AppDataSource.query(
          `SELECT COALESCE(SUM(file_size), 0) as total_bytes FROM detection_files WHERE is_deleted = FALSE`,
        );
        storageUsed = parseInt(dbResult[0]?.total_bytes) || 0;
        const fs = await import('node:fs');
        const detectionsPath = config.storage.detectionsDir;
        if (
          (fs as any).existsSync(detectionsPath) &&
          typeof (fs as any).statfsSync === 'function'
        ) {
          const stat = (fs as any).statfsSync(detectionsPath);
          storageTotal = stat.blocks * stat.bsize;
        }
      } catch (err) {
        logger.warn('Failed to query storage stats', 'System', err);
      }
      this.ok(res, {
        stats: {
          totalEvents,
          totalCameras: cameras.length,
          activeCameras,
          knownVisitors,
          storageUsed,
          storageTotal,
        },
      });
    } catch (error: unknown) {
      this.serverError(res, error, 'stats');
    }
  }

  async cleanupImages(req: Request, res: Response): Promise<void> {
    try {
      const retentionDays = parseInt(req.body.retentionDays) || 7;
      if (retentionDays < 1 || retentionDays > 365) {
        this.badRequest(res, 'Retention days must be between 1 and 365');
        return;
      }

      logger.info(`Admin triggered image cleanup with ${retentionDays} days retention`, 'System');
      const cleanupService = AutomatedCleanupService.getInstance();
      const result = await cleanupService.cleanupOldImages(retentionDays);

      res.json({
        success: true,
        message: 'Cleanup complete',
        retentionDays,
        deleted: result.deleted,
        preserved: result.preserved,
        freedBytes: result.freedBytes,
        freedMB: (result.freedBytes / 1024 / 1024).toFixed(2),
      });
    } catch (error: unknown) {
      this.serverError(res, error, 'cleanupImages');
    }
  }

  async runFullCleanup(_req: Request, res: Response): Promise<void> {
    try {
      logger.info('Admin triggered full retention cleanup', 'System');
      const cleanupService = AutomatedCleanupService.getInstance();
      await cleanupService.runAutomaticCleanup();
      res.json({ success: true, message: 'Full cleanup completed' });
    } catch (error: unknown) {
      this.serverError(res, error, 'runFullCleanup');
    }
  }

  async cleanupStatus(_req: Request, res: Response): Promise<void> {
    try {
      const { AppDataSource } = await import('../database.js');
      const lastCleanup = await AppDataSource.query(
        `SELECT value FROM system_settings WHERE key = 'last_cleanup_timestamp'`,
      );
      const cleanupService = AutomatedCleanupService.getInstance();
      const inProgress = cleanupService.isCleanupInProgress();
      res.json({
        success: true,
        data: {
          lastRun: lastCleanup[0]?.value || null,
          status: inProgress ? 'running' : 'idle',
          nextScheduled: 'Daily at 3:00 AM',
        },
      });
    } catch (error) {
      const cleanupService = AutomatedCleanupService.getInstance();
      const inProgress = cleanupService?.isCleanupInProgress?.() ?? false;
      res.json({
        success: true,
        data: {
          lastRun: null,
          status: inProgress ? 'running' : 'idle',
          nextScheduled: 'Daily at 3:00 AM',
        },
      });
    }
  }

  async overview(req: Request, res: Response): Promise<void> {
    try {
      const streamManager = serviceRegistry.getStreamManager();
      const cameras = streamManager.getAllCameras();

      let storageUsed = 0;
      let storageTotal = 0;
      try {
        const { AppDataSource } = await import('../database.js');
        const { config } = await import('../config/index.js');
        const dbResult = await AppDataSource.query(
          `SELECT COALESCE(SUM(file_size), 0) as total_bytes FROM detection_files WHERE is_deleted = FALSE`,
        );
        storageUsed = parseInt(dbResult[0]?.total_bytes) || 0;
        if (
          fs.existsSync(config.storage.detectionsDir) &&
          typeof (fs as any).statfsSync === 'function'
        ) {
          const stat = (fs as any).statfsSync(config.storage.detectionsDir);
          storageTotal = stat.blocks * stat.bsize;
        }
      } catch (err) {
        logger.warn('Failed to query storage stats in overview', 'System', err);
      }

      const recentEvents = inMemoryState.getRecentEvents();
      const overview = {
        status: 'healthy',
        uptime: process.uptime(),
        totalCameras: cameras.length,
        onlineCameras: cameras.filter((c: Camera) => c.isActive).length,
        totalEvents: recentEvents.length,
        todayEvents: recentEvents.filter((e: MotionEvent) => {
          const eventDate = new Date(e.timestamp);
          const today = new Date();
          return (
            eventDate.getDate() === today.getDate() &&
            eventDate.getMonth() === today.getMonth() &&
            eventDate.getFullYear() === today.getFullYear()
          );
        }).length,
        storageUsed,
        storageTotal,
      };

      this.ok(res, { data: overview });
    } catch (error) {
      this.serverError(res, error, 'overview');
    }
  }

  async systemHealth(req: Request, res: Response): Promise<void> {
    try {
      const streamManager = serviceRegistry.getStreamManager();
      const cameras = streamManager.getAllCameras();
      const onlineCameras = cameras.filter((c: Camera) => c.isActive);
      const offlineCameras = cameras.filter((c: Camera) => !c.isActive);

      let status = 'healthy';
      const issues: string[] = [];
      if (offlineCameras.length > 0) {
        status = 'warning';
        issues.push(`${offlineCameras.length} camera(s) offline`);
      }
      if (onlineCameras.length === 0 && cameras.length > 0) {
        status = 'critical';
        issues.push('All cameras offline');
      }

      const uptime = process.uptime();
      if (uptime < 300) issues.push('System recently restarted');

      let dbHealthy = false;
      try {
        const { AppDataSource } = await import('../database.js');
        await AppDataSource.query('SELECT 1');
        dbHealthy = true;
      } catch (err) {
        logger.warn('Database health check failed', 'System', err);
      }
      if (!dbHealthy) issues.push('Database connectivity issue');

      const recentEvents = inMemoryState.getRecentEvents();

      const cpus = os.cpus();
      const loadAvg = os.loadavg();
      const cpuUsage = (loadAvg[0] / cpus.length) * 100;

      let opencvBreakerState = 'unknown';
      try {
        const { getOpenCVClient } = await import('../services/opencvMicroserviceClient.js');
        opencvBreakerState = getOpenCVClient().getBreakerState();
      } catch {
        /* OpenCV client not initialized yet */
      }

      res.json({
        success: true,
        health: {
          status,
          uptime,
          issues,
          cameras: {
            total: cameras.length,
            online: onlineCameras.length,
            offline: offlineCameras.length,
          },
          memory: {
            used: Math.round((process.memoryUsage().heapUsed / 1024 / 1024) * 100) / 100,
            total: Math.round((process.memoryUsage().heapTotal / 1024 / 1024) * 100) / 100,
            systemTotal: Math.round((os.totalmem() / 1024 / 1024) * 100) / 100,
            systemFree: Math.round((os.freemem() / 1024 / 1024) * 100) / 100,
          },
          cpu: {
            usage: Math.min(100, Math.round(cpuUsage * 100) / 100),
            cores: cpus.length,
            model: cpus[0].model,
            loadAvg: loadAvg,
          },
          circuitBreakers: {
            opencv: opencvBreakerState,
          },
          events: {
            recent: recentEvents.length,
            today: recentEvents.filter((e) => {
              const eventDate = new Date(e.timestamp);
              const today = new Date();
              return (
                eventDate.getDate() === today.getDate() &&
                eventDate.getMonth() === today.getMonth() &&
                eventDate.getFullYear() === today.getFullYear()
              );
            }).length,
          },
        },
      });
    } catch (error) {
      this.serverError(res, error, 'systemHealth');
    }
  }

  async getLogs(req: Request, res: Response): Promise<void> {
    try {
      const { level, limit } = req.query;
      const logs: Array<{ timestamp: string; level: string; message: string; context?: string }> =
        [];

      const logsDir = path.join(__dirname, '../../logs');
      const errorLogFile = path.join(logsDir, 'error.log');
      const combinedLogFile = path.join(logsDir, 'combined.log');

      const parseLogFile = async (
        filePath: string,
        targetLevel?: string,
      ): Promise<
        Array<{ timestamp: string; level: string; message: string; context?: string }>
      > => {
        const entries: Array<{
          timestamp: string;
          level: string;
          message: string;
          context?: string;
        }> = [];
        try {
          await fsp.access(filePath);
        } catch {
          return entries;
        }
        const content = await fsp.readFile(filePath, 'utf-8');
        const lines = content.split('\n');
        for (const line of lines) {
          if (!line.trim()) continue;
          const match = line.match(/^\[([\d-T:.Z]+)\]\s+\[([A-Z]+)\](?:\s+\[([^\]]+)\])?\s+(.+)$/);
          if (match) {
            const [, timestamp, logLevel, context, message] = match;
            if (!targetLevel || logLevel === targetLevel) {
              entries.push({ timestamp, level: logLevel, message, context });
            }
          }
        }
        return entries;
      };
      const combinedEntries = await parseLogFile(combinedLogFile, level as string);
      logs.push(...combinedEntries);
      const errorEntries = await parseLogFile(errorLogFile, 'ERROR');
      logs.push(...errorEntries);

      const maxLogs = parseInt(limit as string) || 100;
      this.ok(res, { logs: logs.slice(-maxLogs).reverse() });
    } catch (error) {
      this.serverError(res, error, 'getLogs');
    }
  }

  async clearLogs(req: Request, res: Response): Promise<void> {
    try {
      const logsDir = path.join(__dirname, '../../logs');
      const errorLogFile = path.join(logsDir, 'error.log');
      const combinedLogFile = path.join(logsDir, 'combined.log');

      const cleared: string[] = [];
      if (fs.existsSync(errorLogFile)) {
        fs.writeFileSync(errorLogFile, '');
        cleared.push('error.log');
      }
      if (fs.existsSync(combinedLogFile)) {
        fs.writeFileSync(combinedLogFile, '');
        cleared.push('combined.log');
      }

      this.ok(res, { message: 'Logs cleared', cleared });
    } catch (error) {
      this.serverError(res, error, 'clearLogs');
    }
  }
}

