  return isDev ? true : ['http://localhost:3000', 'http://localhost:5173'];
})();

app.use(
  cors({
    origin: corsOrigins,
    credentials: true,
  }),
);

const go2rtcUrl = process.env.GO2RTC_URL || 'http://go2rtc:1984';
app.use(
  '/go2rtc',
  createProxyMiddleware({
    target: go2rtcUrl,
    changeOrigin: true,
    pathRewrite: { '^/go2rtc': '' },
  }),
);

app.use(express.json());
app.use(
  helmet({
    strictTransportSecurity:
      process.env.NODE_ENV === 'production'
        ? {
            maxAge: 31536000,
            includeSubDomains: true,
          }
        : false,
    contentSecurityPolicy: {
      directives: {
        defaultSrc: ["'self'"],
        scriptSrc: ["'self'"],
        styleSrc: ["'self'", "'unsafe-inline'"],
        imgSrc: ["'self'", 'data:', 'blob:'],
        connectSrc: ["'self'", 'ws:', 'wss:'],
        mediaSrc: ["'self'", 'blob:', 'data:'],
        workerSrc: ["'self'", 'blob:'],
        fontSrc: ["'self'", 'https://fonts.gstatic.com'],
        objectSrc: ["'none'"],
        upgradeInsecureRequests: process.env.NODE_ENV === 'production' ? [] : null,
      },
    },
  }),
);

const server = http.createServer(app);

const go2rtcParsed = new URL(go2rtcUrl);
server.on('upgrade', (req, socket, head) => {
  if (!req.url?.startsWith('/go2rtc')) return;

  const targetPath = req.url.replace('/go2rtc', '') || '/';
  const headers: Record<string, string> = {};
  const blockedHeaders = new Set([
    'authorization',
    'cookie',
    'cookie2',
    'proxy-authorization',
    'proxy-connection',
    'x-forwarded-for',
    'x-real-ip',
    'forwarded',
  ]);
  for (let i = 0; i < req.rawHeaders.length; i += 2) {
    const key = req.rawHeaders[i].toLowerCase();
    if (blockedHeaders.has(key)) continue;
    if (key === 'host') {
      headers['host'] = `${go2rtcParsed.hostname}:${go2rtcParsed.port || 1984}`;
    } else {
      headers[key] = req.rawHeaders[i + 1];
    }
  }

  const proxyReq = http.request({
    hostname: go2rtcParsed.hostname,
    port: parseInt(go2rtcParsed.port || '1984'),
    path: targetPath,
    method: req.method || 'GET',
    headers,
  });

  proxyReq.on('upgrade', (_proxyRes, proxySocket, proxyHead) => {
    proxySocket.on('error', () => {
      try {
        socket.destroy();
      } catch {}
    });
    socket.on('error', () => {
      try {
        proxySocket.destroy();
      } catch {}
    });
    socket.on('close', () => {
      try {
        proxySocket.destroy();
      } catch {}
    });
    proxySocket.on('close', () => {
      try {
        socket.destroy();
      } catch {}
    });

    let responseLine = 'HTTP/1.1 101 Switching Protocols\r\n';
    for (const [k, v] of Object.entries(_proxyRes.headers)) {
      if (v !== undefined) responseLine += `${k}: ${v}\r\n`;
    }
    responseLine += '\r\n';
    socket.write(responseLine);

    if (proxyHead.length > 0) proxySocket.write(proxyHead);
    if (head.length > 0) proxySocket.write(head);

    proxySocket.pipe(socket);
    socket.pipe(proxySocket);
  });

  proxyReq.on('error', () => {
    try {
      socket.destroy();
    } catch {}
  });
  proxyReq.end();
});
const io = new SocketIOServer(server, {
  cors: {
    origin: corsOrigins,
    credentials: true,
  },
});

await initializeServices(io);
configureRoutes(app, io);

// SPA Fallback
app.get('*', (req: express.Request, res: express.Response) => {
  res.sendFile(path.join(process.cwd(), 'public', 'index.html'));
});

logger.info('Routes configured successfully', 'SERVER');

app.use(staticRoutes);

// SPA fallback: after all API routes, serve index.html for client-side routing
const frontendDistPath = process.env.FRONTEND_DIST_PATH || path.join(process.cwd(), 'public');
if (fs.existsSync(frontendDistPath)) {
  app.get('/{*path}', (_req, res) => {
    res.sendFile(path.join(frontendDistPath, 'index.html'));
  });
}

process.on('SIGTERM', () => gracefulShutdown('SIGTERM', server, io));
process.on('SIGINT', () => gracefulShutdown('SIGINT', server, io));

process.on('unhandledRejection', (reason, promise) => {
  logger.error('Unhandled Rejection', 'SERVER', reason);
});

const PORT = process.env.PORT || 9753;

server.listen(PORT, () => {
  logger.info(`SentryVision Server started on port ${PORT}`, 'SERVER');
});

server.on('error', (error: any) => {
  if (error.code === 'EADDRINUSE') {
    logger.error(`Port ${PORT} is already in use. Kill the process or change PORT.`, 'SERVER');
    logger.error(`  Run: fuser -k ${PORT}/tcp`, 'SERVER');
    process.exit(1);
  }
  throw error;
});

import { Server as SocketIOServer } from 'socket.io';
import { logger } from '../utils/logger.js';
import { AppDataSource } from '../database.js';
import { setCameras, loadCamerasFromFile } from '../config/cameraLoader.js';
import { config, type CameraConfig } from '../config/index.js';
import { setupRTSPStreams } from '../streams/rtspManager.js';
import { consolidatedDetectionService } from '../detection/consolidatedDetectionService.js';
import { ReviewService } from '../services/review/reviewService.js';
import { TimelineService } from '../services/timeline/timelineService.js';
import { DetectionService } from '../services/detection/detectionService.js';
import { PreviewService } from '../services/preview/previewService.js';
import { TimelapseService } from '../services/timelapse/timelapseService.js';
import { setTimelapseService } from '../routes/timelapse.js';
import { retentionPolicyService } from '../services/retentionPolicyService.js';
import { automatedCleanupService } from '../services/automatedCleanupService.js';
import NotificationService from '../services/notificationService.js';
import { serviceRegistry } from '../services/serviceRegistry.js';
import { inMemoryState } from '../services/inMemoryStateService.js';
import { PythonWsClient, TrackingEvent } from '../services/pythonWsClient.js';
import { persistDetectionEvent } from '../pipeline/detectionPersistence.js';
import { ReviewSegment } from '../models/ReviewSegment.js';
import { UserReviewStatus } from '../models/UserReviewStatus.js';
import { Timeline } from '../models/Timeline.js';
import { AdaptiveRegion } from '../models/AdaptiveRegion.js';
import { DetectionConfig } from '../models/DetectionConfig.js';

export async function initializeServices(io: SocketIOServer): Promise<void> {
  serviceRegistry.setAppDataSource(AppDataSource);
  serviceRegistry.setDetectionService(consolidatedDetectionService);

  try {
    await consolidatedDetectionService.loadSettingsFromDb();
    logger.info('Detection settings loaded from database', 'INIT');
  } catch (error: unknown) {
    const msg = error instanceof Error ? error.message : String(error);
    logger.warn(`Could not load detection settings from DB: ${msg}`, 'INIT');
  }

  try {
    await inMemoryState.loadAlertsFromDb();
    logger.info('Alerts loaded from database', 'INIT');
  } catch (error: unknown) {
    const msg = error instanceof Error ? error.message : String(error);
    logger.warn(`Could not load alerts from DB: ${msg}`, 'INIT');
  }

  try {
    logger.info('Initializing Python WebSocket client...', 'INIT');
    const pythonWsClient = new PythonWsClient(config.pipeline.pythonWsUrl);
    pythonWsClient.connect();
    serviceRegistry.setPythonWsClient(pythonWsClient);

    const persistedTracks = new Set<string>();
    const lastSavedPerCameraClass = new Map<
      string,
      { bbox: { x: number; y: number; w: number; h: number }; ts: number }
    >();

    pythonWsClient.on('trackingEvent', (ev: TrackingEvent) => {
      const {
        cameraId,
        event: eventType,
        trackId,
        class: className,
        score,
        bbox,
        identity,
        identityConfidence,
      } = ev;
      if (!cameraId) return;

      if (eventType === 'track_started' || eventType === 'track_updated') {
        const detection = {
          class: className,
          confidence: Math.round(score * 100),
          bbox: { x: bbox[0] ?? 0, y: bbox[1] ?? 0, width: bbox[2] ?? 0, height: bbox[3] ?? 0 },
          trackId,
          identity,
          identityConfidence,
        };

        if (className === 'person') {
          io.emit('personDetected', {
            cameraId,
            timestamp: new Date(ev.timestamp).toISOString(),
            persons: [detection],
            trackId,
          });
        }

        if (identity && identity !== 'unknown') {
          io.emit('faceDetected', {
            cameraId,
            timestamp: new Date(ev.timestamp).toISOString(),
            faces: [
              {
                id: `track_${trackId}`,
                name: identity,
                confidence: identityConfidence ?? 0,
                bbox: detection.bbox,
              },
            ],
          });
        }

        io.to(`camera-${cameraId}-live`).emit('detection', {
          cameraId,
          detections: [detection],
          timestamp: new Date(ev.timestamp).toISOString(),
        });
      }

      const trackKey = `${cameraId}:${trackId}`;
      if (
        !persistedTracks.has(trackKey) &&
        (eventType === 'track_started' || eventType === 'track_updated')
      ) {
        const sceneKey = `${cameraId}:${className}`;
        const prev = lastSavedPerCameraClass.get(sceneKey);
        const now = Date.now();

        if (prev && className !== 'person') {
          const dx = Math.abs((bbox[0] ?? 0) - prev.bbox.x);
          const dy = Math.abs((bbox[1] ?? 0) - prev.bbox.y);
          const dw = Math.abs((bbox[2] ?? 0) - prev.bbox.w);
          const dh = Math.abs((bbox[3] ?? 0) - prev.bbox.h);
          const bboxShift = Math.sqrt(dx * dx + dy * dy + dw * dw + dh * dh);
          const elapsed = now - prev.ts;

          if (bboxShift < 80 && elapsed < 10 * 60 * 1000) {
            persistedTracks.add(trackKey);
            return;
          }
        }

        if (className !== 'person') {
          lastSavedPerCameraClass.set(sceneKey, {
            bbox: { x: bbox[0] ?? 0, y: bbox[1] ?? 0, w: bbox[2] ?? 0, h: bbox[3] ?? 0 },
            ts: now,
          });
          return;
        }

        const minPersonConfidence = parseFloat(process.env.PERSON_MIN_CONFIDENCE || '0.45');
        if ((score ?? 0) < minPersonConfidence) {
          persistedTracks.add(trackKey);
          return;
        }

        persistedTracks.add(trackKey);
        persistDetectionEvent(ev).catch((err: unknown) => {
          logger.error(`Failed to persist detection event for ${cameraId}`, 'INIT', err);
        });
      }

      if (eventType === 'track_started') {
        io.emit('motionDetected', {
          id: `track_${trackId}_${Date.now()}`,
          cameraId,
          timestamp: new Date(ev.timestamp).toISOString(),
          confidence: Math.round(score * 100),
          labels: [className],
          detections: [
            {
              class: className,
              confidence: Math.round(score * 100),
              bbox: { x: bbox[0] ?? 0, y: bbox[1] ?? 0, width: bbox[2] ?? 0, height: bbox[3] ?? 0 },
              trackId,
            },
          ],
          trackId,
        });
      }
    });

    pythonWsClient.on('connected', () => {
      logger.info('Python WebSocket client connected', 'PythonWsClient');
      config.cameras.forEach((cam: CameraConfig) => pythonWsClient.subscribe(cam.id));
    });

    pythonWsClient.on('disconnected', () => {
      logger.warn('Disconnected from Python WebSocket server', 'PythonWsClient');
    });

    logger.info('Python WebSocket client initialized successfully', 'INIT');
  } catch (error) {
    logger.error('FATAL: Python WebSocket client initialization failed', 'INIT', error);
    process.exit(1);
  }

  let cameras: CameraConfig[] = [];

  try {
    const dbRows = await AppDataSource.query(
      'SELECT id, name, config, enabled FROM cameras ORDER BY created_at',
    );
    if (dbRows.length > 0) {
      cameras = dbRows.map((row: any) => {
        const cfg = typeof row.config === 'string' ? JSON.parse(row.config) : row.config;
        return { ...cfg, enabled: row.enabled };
      });
      logger.info(`Loaded ${cameras.length} cameras from database`, 'INIT');
    }
  } catch (error) {
    logger.warn(`Failed to load cameras from database: ${error}`, 'INIT');
  }

  if (cameras.length === 0) {
    cameras = loadCamerasFromFile();
    if (cameras.length > 0) {
      logger.info(
        `Loaded ${cameras.length} cameras from cameras.json (first-time bootstrap)`,
        'INIT',
      );
      try {
        for (const cam of cameras) {
          await AppDataSource.query(
            'INSERT INTO cameras (id, name, config, enabled) VALUES ($1, $2, $3::jsonb, $4) ON CONFLICT (id) DO UPDATE SET name = $2, config = $3::jsonb, enabled = $4',
            [cam.id, cam.name, JSON.stringify(cam), cam.enabled !== false],
          );
        }
        logger.info('Bootstrapped cameras.json cameras into database', 'INIT');
      } catch (error) {
        logger.warn(`Failed to seed cameras to database: ${error}`, 'INIT');
      }
    }
  }

  setCameras(cameras);

  try {
    logger.info('Initializing stream manager...', 'INIT');
    const streamManagerInstance = await setupRTSPStreams(io, cameras);
    serviceRegistry.setStreamManager(streamManagerInstance);
    NotificationService.loadCameraNames(streamManagerInstance);
    logger.info('Stream manager initialized successfully', 'INIT');
  } catch (error) {
    logger.error('FATAL: Stream manager initialization failed', 'INIT', error);
    process.exit(1);
  }

  try {
    logger.info('Initializing review, timeline and detection services...', 'INIT');
    const reviewSegmentRepo = AppDataSource.getRepository(ReviewSegment);
    const reviewStatusRepo = AppDataSource.getRepository(UserReviewStatus);
    const timelineRepo = AppDataSource.getRepository(Timeline);
    const regionRepo = AppDataSource.getRepository(AdaptiveRegion);

    const timelineServiceInstance = new TimelineService(timelineRepo, regionRepo);
    const previewServiceInstance = new PreviewService(timelineServiceInstance);
    const timelapseServiceInstance = new TimelapseService();
    setTimelapseService(timelapseServiceInstance);
    const detectionServiceInstance = new DetectionService();
    const reviewServiceInstance = new ReviewService(
      reviewSegmentRepo,
      reviewStatusRepo,
      timelineServiceInstance,
      previewServiceInstance,
    );

    serviceRegistry.setTimelineService(timelineServiceInstance);
    serviceRegistry.setTimelapseService(timelapseServiceInstance);
    serviceRegistry.setDetectionConfigService(detectionServiceInstance);
    serviceRegistry.setReviewService(reviewServiceInstance);
    logger.info(
      'Review, timeline, timelapse and detection services initialized successfully',
      'INIT',
    );
  } catch (error) {
    logger.error('Review/timeline/detection services failed (non-critical)', 'INIT', error);
  }

  try {
    logger.info('Initializing notification service...', 'INIT');
    await NotificationService.initialize();
    serviceRegistry.setNotificationService(NotificationService);
    logger.info('Notification service initialized successfully', 'INIT');
  } catch (error) {
    logger.error('Notification service failed (non-critical)', 'INIT', error);
  }

  try {
    logger.info('Initializing cleanup services...', 'INIT');
    await retentionPolicyService.initialize();
    await automatedCleanupService.initialize();
    serviceRegistry.setRetentionPolicyService(retentionPolicyService);
    serviceRegistry.setAutomatedCleanupService(automatedCleanupService);
    logger.info('Cleanup services initialized successfully', 'INIT');
  } catch (error) {
    logger.error('Cleanup services failed (non-critical)', 'INIT', error);
  }
}

import { Request, Response, NextFunction } from 'express';
import { authService, JWTPayload } from '../auth/index.js';
import { logger } from '../utils/logger.js';
import { AppDataSource } from '../database.js';
import cacheService from '../services/cacheService.js';

// Extend Request interface to include user
declare module 'express-serve-static-core' {
  interface Request {
    user?: JWTPayload;
  }
}

export interface AuthOptions {
  required?: boolean;
  roles?: string[];
  skipValidation?: boolean;
}

// Cache session validity per-user to avoid a DB round-trip on every request.
// TTL bounds the window a logged-out user could keep using cached sessions.
const SESSION_CHECK_TTL_SECONDS = 30;

function sessionCacheKey(userId: string): string {
  return `auth:session:${userId}`;
}

export function invalidateSessionCache(userId: string): void {
  void cacheService.del(sessionCacheKey(userId));
}

async function hasActiveSession(userId: string): Promise<boolean> {
  const cached = await cacheService.get(sessionCacheKey(userId));
  if (cached !== null) {
    return cached === '1';
  }

  const session = await AppDataSource.query(
    'SELECT id FROM user_sessions WHERE user_id = $1 AND is_active = true LIMIT 1',
    [userId],
  );
  const active = !!session && session.length > 0;
  await cacheService.set(sessionCacheKey(userId), active ? '1' : '0', SESSION_CHECK_TTL_SECONDS);
  return active;
}

export function authenticate(options: AuthOptions = {}) {
  const { required = true, roles = [], skipValidation = false } = options;

  return async (req: Request, res: Response, next: NextFunction) => {
    try {
      // Get token from Authorization header
      const authHeader = req.headers.authorization;
      const token = authHeader && authHeader.startsWith('Bearer ') ? authHeader.substring(7) : null;

      // If no token and authentication is required
      if (!token) {
        if (required) {
          return res.status(401).json({
            success: false,
            error: 'Authentication token is required',
          });
        }
        return next(); // Continue without authentication
      }

      // Verify token
      const payload = authService.verifyToken(token);

      if (!payload) {
        if (required) {
          return res.status(401).json({
            success: false,
            error: 'Invalid or expired authentication token',
          });
        }
        return next(); // Continue without authentication
      }

      // Check role requirements
      if (roles.length > 0 && !roles.includes(payload.role)) {
        return res.status(403).json({
          success: false,
          error: 'Insufficient permissions',
        });
      }

      // Verify user has an active session (not logged out)
      try {
        if (AppDataSource.isInitialized) {
          const active = await hasActiveSession(payload.userId);
          if (!active) {
            if (required) {
              return res.status(401).json({
                success: false,
                error: 'Session expired. Please login again.',
              });
            }
            return next();
          }
        }
      } catch (err) {
        logger.error(`Session check error: ${err}`, 'AuthMiddleware');
        if (required) {
          return res.status(500).json({
            success: false,
            error: 'Authentication error',
          });
        }
        return next();
      }

      // Add user payload to request
      req.user = payload;

      // Log authentication success
      logger.debug(`User authenticated: ${payload.username} (${payload.role})`, 'AuthMiddleware');

      next();
    } catch (error) {
      logger.error(`Authentication middleware error: ${error}`, 'AuthMiddleware');

      if (required) {
        return res.status(500).json({
          success: false,
          error: 'Authentication error',
        });
      }

      next();
    }
  };
}

// Role-based authentication helpers
export const requireAdmin = authenticate({ roles: ['admin'] });
export const requireUser = authenticate({ roles: ['admin', 'user'] });
export const requireViewer = authenticate({ roles: ['admin', 'user', 'viewer'] });
export const optionalAuth = authenticate({ required: false });

export default authenticate;

import { Request, Response, NextFunction } from 'express';
import { logger } from '../utils/logger.js';

// Validation schema interface
export interface ValidationSchema {
  body?: Record<string, ValidationRule>;
  query?: Record<string, ValidationRule>;
  params?: Record<string, ValidationRule>;
}

export interface ValidationRule {
  type: 'string' | 'number' | 'boolean' | 'email' | 'url' | 'object' | 'array';
  required?: boolean;
  minLength?: number;
  maxLength?: number;
  min?: number;
  max?: number;
  pattern?: RegExp;
  enum?: string[];
  custom?: (value: unknown) => boolean | string;
}

// Validation error class
export class ValidationError extends Error {
  constructor(
    public field: string,
    public message: string,
  ) {
    super(`Validation failed for ${field}: ${message}`);
    this.name = 'ValidationError';
  }
}

// Main validation middleware
export function validate(schema: ValidationSchema) {
  return (req: Request, res: Response, next: NextFunction) => {
    try {
      const errors: ValidationError[] = [];

      // Validate request body
      if (schema.body) {
        validateObject(req.body, schema.body, 'body', errors);
      }

      // Validate query parameters
      if (schema.query) {
        validateObject(req.query, schema.query, 'query', errors);
      }

      // Validate route parameters
      if (schema.params) {
        validateObject(req.params, schema.params, 'params', errors);
      }

      if (errors.length > 0) {
        logger.warn(`Validation failed: ${errors.map((e) => e.message).join(', ')}`, 'Validation');
        return res.status(400).json({
          success: false,
          error: 'Validation failed',
          details: errors.map((e) => ({ field: e.field, message: e.message })),
        });
      }

      next();
    } catch (error) {
      logger.error(`Validation middleware error: ${error}`, 'Validation');
      return res.status(500).json({
        success: false,
        error: 'Internal server error during validation',
      });
    }
  };
}

// Validate object against schema
function validateObject(
  obj: Record<string, unknown>,
  schema: Record<string, ValidationRule>,
  context: string,
  errors: ValidationError[],
) {
  for (const [field, rule] of Object.entries(schema)) {
    const value = obj?.[field];

    // Check if required field is missing
    if (rule.required && (value === undefined || value === null || value === '')) {
      errors.push(new ValidationError(`${context}.${field}`, `${field} is required`));
      continue;
    }

    // Skip validation if field is not provided and not required
    if (value === undefined || value === null) {
      continue;
    }

    // Type validation
    if (!validateType(value, rule.type)) {
      errors.push(
        new ValidationError(`${context}.${field}`, `${field} must be of type ${rule.type}`),
      );
      continue;
    }

    // String validations
    if (rule.type === 'string') {
      const strValue = String(value);

      if (rule.minLength !== undefined && strValue.length < rule.minLength) {
        errors.push(
          new ValidationError(
            `${context}.${field}`,
            `${field} must be at least ${rule.minLength} characters long`,
          ),
        );
      }

      if (rule.maxLength !== undefined && strValue.length > rule.maxLength) {
        errors.push(
          new ValidationError(
            `${context}.${field}`,
            `${field} must be no more than ${rule.maxLength} characters long`,
          ),
        );
      }

      if (rule.pattern && !rule.pattern.test(strValue)) {
        errors.push(new ValidationError(`${context}.${field}`, `${field} format is invalid`));
      }

      if (rule.enum && !rule.enum.includes(strValue)) {
        errors.push(
          new ValidationError(
            `${context}.${field}`,
            `${field} must be one of: ${rule.enum.join(', ')}`,
          ),
        );
      }
    }

    // Number validations
    if (rule.type === 'number') {
      const numValue = Number(value);

      if (rule.min !== undefined && numValue < rule.min) {
        errors.push(
          new ValidationError(`${context}.${field}`, `${field} must be at least ${rule.min}`),
        );
      }

      if (rule.max !== undefined && numValue > rule.max) {
        errors.push(
          new ValidationError(`${context}.${field}`, `${field} must be no more than ${rule.max}`),
        );
      }
    }

    // Custom validation
    if (rule.custom) {
      const customResult = rule.custom(value);
      if (customResult !== true) {
        errors.push(new ValidationError(`${context}.${field}`, customResult as string));
      }
    }
  }
}

// Validate value type
function validateType(value: unknown, type: string): boolean {
  switch (type) {
    case 'string':
      return typeof value === 'string';
    case 'number':
      return !isNaN(Number(value)) && isFinite(Number(value));
    case 'boolean':
      return typeof value === 'boolean' || value === 'true' || value === 'false';
    case 'email':
      return typeof value === 'string' && /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value);
    case 'url':
      try {
        new URL(value as string);
        return true;
      } catch {
        return false;
      }
    case 'object':
      return typeof value === 'object' && value !== null && !Array.isArray(value);
    case 'array':
      return Array.isArray(value);
    default:
      return true;
  }
}

// Input sanitization middleware
export const sanitizeInput = (req: Request, res: Response, next: NextFunction): void => {
  // Remove potentially dangerous HTML/JS from string inputs
  const sanitizeString = (str: string): string => {
    return str
      .replace(/<script\b[^<]*(?:(?!<\/script>)<[^<]*)*<\/script>/gi, '')
      .replace(/<iframe\b[^<]*(?:(?!<\/iframe>)<[^<]*)*<\/iframe>/gi, '')
      .replace(/<\/?(?:script|iframe|object|embed|form|link|meta|style|title)\b[^>]*>/gi, '')
      .replace(/<[a-z][a-z0-9-]*(?:\s+[a-z0-9-]+=(?:"[^"]*"|'[^']*'|[^\s>]*))*\s*\/?>/gi, (tag) =>
        tag
          .replace(/\bon[a-z]+\s*=\s*("[^"]*"|'[^']*'|[^\s>]*)/gi, '')
          .replace(/javascript:/gi, ''),
      )
      .replace(/javascript:/gi, '')
      .replace(/\bon[a-z]+\s*=/gi, '')
      .replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F]/g, '');
  };

  const sanitizeValue = (value: unknown): unknown => {
    if (typeof value === 'string') return sanitizeString(value).trim();
    if (Array.isArray(value)) return value.map(sanitizeValue);
    if (value && typeof value === 'object') {
      const result: Record<string, unknown> = {};
      for (const key of Object.keys(value)) {
        result[key] = sanitizeValue((value as Record<string, unknown>)[key]);
      }
      return result;
    }
    return value;
  };

  // Sanitize query parameters (query values can be strings or arrays)
  for (const key in req.query) {
    req.query[key] = sanitizeValue(req.query[key]) as never;
  }

  // Sanitize body parameters (recursively, including nested objects/arrays)
  if (req.body && typeof req.body === 'object') {
    req.body = sanitizeValue(req.body);
  }

  next();
};

