const CAMERA_ID_PATTERN = /^[a-zA-Z0-9_-]+$/;
function validateCameraId(cameraId: string): boolean {
  return CAMERA_ID_PATTERN.test(cameraId) && cameraId.length <= 100;
}

const router = Router();

router.post(
  '/person/:cameraId/trigger',
  requireUser,
  validateParams(
    z.object({
      cameraId: z
        .string()
        .regex(/^[a-zA-Z0-9_-]+$/)
        .min(1)
        .max(100),
    }),
  ),
  async (req: Request, res: Response) => {
    try {
      const streamManager = serviceRegistry.getStreamManager();
      const cameraId = req.params.cameraId;
      if (!cameraId || !validateCameraId(cameraId)) {
        res.status(400).json({ success: false, error: 'Invalid camera ID format' });
        return;
      }
      const camera = streamManager.getAllCameras().find((c: any) => c.id === cameraId);
      if (!camera) {
        res.status(404).json({ success: false, error: 'Camera not found' });
        return;
      }
      if (!camera.isActive) {
        res.status(400).json({ success: false, error: 'Camera is not active' });
        return;
      }
      const currentFrame = streamManager.getCurrentFrame(cameraId);
      if (!currentFrame) {
        res.status(400).json({ success: false, error: 'No frame available from camera' });
        return;
      }
      let detections: any[] = [];
      try {
        const result = await consolidatedDetectionService.detectObjects(cameraId, currentFrame);
        detections = result.detections;
      } catch (error) {
        res.status(501).json({
          success: false,
          error: error instanceof Error ? error.message : 'Detection endpoint disabled',
          details:
            'Detection runs via Python WebSocket pipeline. This HTTP endpoint is no longer supported.',
        });
        return;
      }
      const persons = detections.filter((d: any) => d.class === 'person') || [];
      if (persons.length > 0) {
        const io: SocketIOServer = (req.app as any).get('io');
        io.emit('personDetected', {
          cameraId,
          timestamp: new Date().toISOString(),
          persons: persons.map((p: any) => ({
            confidence: p.confidence,
            boundingBox: p.bbox,
            timestamp: new Date().toISOString(),
          })),
          imagePath: currentFrame,
        });
        inMemoryState.addAlert({
          type: 'motion',
          severity: 'warning',
          message: `Person detected on camera ${camera.name || cameraId}`,
          cameraId,
        });
      }
      res.json({
        success: true,
        persons: persons.length,
        detections: detections || [],
        timestamp: new Date().toISOString(),
      });
    } catch (error) {
      logger.error(
        `Error triggering person detection for camera ${req.params.cameraId}`,
        'Detection',
        error,
      );
      res.status(500).json({ success: false, error: 'Failed to trigger person detection' });
    }
  },
);

