export function configureRoutes(app: Express, io: SocketIOServer) {
  // Store io on app for route files that need it
  app.set('io', io);

  // Controller-delegated routes (unique paths that can't be grouped under /api prefix)
  app.get('/api/streaming/metrics', optionalAuth, (req, res) =>
    streamController.getMetrics(req, res),
  );
  app.get('/snapshot/:cameraId.jpg', optionalAuth, (req, res) =>
    streamController.getSnapshot(req, res),
  );
  app.get('/stream/:cameraId/test', optionalAuth, (req, res) =>
    streamController.getMjpegStream(req, res),
  );
  app.get('/stream/:cameraId', optionalAuth, (req, res) =>
    streamController.getMjpegStream(req, res),
  );

  // System routes
  app.get('/api/health', (req, res) => systemController.health(req, res));
  app.get('/api/stats', optionalAuth, (req, res) => systemController.stats(req, res));
  app.get('/api/system/overview', requireUser, (req, res) => systemController.overview(req, res));
  app.get('/api/system/health', optionalAuth, (req, res) =>
    systemController.systemHealth(req, res),
  );
  app.get('/api/system/logs', requireUser, (req, res) => systemController.getLogs(req, res));
  app.delete('/api/system/logs', requireAdmin, (req, res) => systemController.clearLogs(req, res));
  app.post('/api/maintenance/cleanup-images', requireAdmin, (req, res) =>
    systemController.cleanupImages(req, res),
  );
  app.post('/api/maintenance/cleanup-full', requireAdmin, (req, res) =>
    systemController.runFullCleanup(req, res),
  );
  app.get('/api/maintenance/cleanup-status', requireAdmin, (req, res) =>
    systemController.cleanupStatus(req, res),
  );

  // Detection image with overlays
  app.get('/detections/image/:imageId', optionalAuth, async (req: Request, res: Response) => {
    try {
      const { imageId } = req.params;
      const { overlays } = req.query;
      const dataSource = serviceRegistry.getAppDataSource();
      const isUuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(
        imageId,
      );
      if (!isUuid && !imageId.includes('.')) {
        return res.status(400).json({ success: false, error: 'Invalid image ID format' });
      }

      const detectionFields =
        overlays === 'true'
          ? `COALESCE(e.object_detections, '[]') as object_detections, COALESCE(e.face_detections, '[]') as face_detections,`
          : '';

      const results = await dataSource.query(
        `SELECT COALESCE(df.file_uuid::text, e.id::text) as file_uuid, COALESCE(df.storage_path, e.file_path) as file_path, COALESCE(df.storage_path, e.file_path) as imagePath, COALESCE(df.metadata, e.metadata) as metadata, COALESCE(df.camera_id, e.camera_id) as camera_id, ${detectionFields} COALESCE(df.original_filename, e.file_path) as original_filename FROM events e LEFT JOIN detection_files df ON e.file_path = df.storage_path OR e.file_path LIKE '%' || df.original_filename WHERE df.file_uuid = $1 OR e.file_path = $1 OR df.original_filename = $1 ORDER BY COALESCE(df.created_at, e.created_at) DESC LIMIT 1`,
        [imageId],
      );

      if (results.length === 0) {
        res.status(404).json({ success: false, error: 'Detection image not found' });
        return;
      }

      const detection = results[0];
      let imagePath = detection.storage_path;
      if (!path.isAbsolute(imagePath))
        imagePath = path.join(process.cwd(), 'data', 'detections', imagePath);
      if (!fs.existsSync(imagePath)) {
        res.status(404).json({ success: false, error: 'Image file not found on disk' });
        return;
      }

      if (overlays === 'true') {
        const sharp = (await import('sharp')).default;
        const objectDetections: Array<Record<string, unknown>> =
          typeof detection.object_detections === 'string'
            ? JSON.parse(detection.object_detections)
            : detection.object_detections || [];
        const faceDetections: Array<Record<string, unknown>> =
          typeof detection.face_detections === 'string'
            ? JSON.parse(detection.face_detections)
            : detection.face_detections || [];
        const allDetections = [...objectDetections, ...faceDetections];

        if (allDetections.length > 0) {
          const svgOverlays = allDetections
            .map((d, i) => {
              const box = (d.box || d.bounding_box || d.box) as Record<string, number> | undefined;
              if (!box) return '';
              const x = box.x ?? box.xmin ?? 0;
              const y = box.y ?? box.ymin ?? 0;
              const w = box.w ?? box.width ?? (box.xmax ? box.xmax - x : 0);
              const h = box.h ?? box.height ?? (box.ymax ? box.ymax - y : 0);
              const label = (d.label || d.class || 'unknown') as string;
              const conf = d.confidence ? `${Math.round((d.confidence as number) * 100)}%` : '';
              const color = i % 2 === 0 ? '#00ff00' : '#ff4444';
              return `<rect x="${x}" y="${y}" width="${w}" height="${h}" fill="none" stroke="${color}" stroke-width="3"/><text x="${x}" y="${y - 5}" fill="${color}" font-size="16" font-family="monospace">${label} ${conf}</text>`;
            })
            .filter(Boolean)
            .join('\n');

          const overlaidImage = await sharp(imagePath)
            .composite([
              {
                input: Buffer.from(
                  `<svg xmlns="http://www.w3.org/2000/svg" width="100%" height="100%">${svgOverlays}</svg>`,
                ),
                top: 0,
                left: 0,
              },
            ])
            .jpeg({ quality: 90 })
            .toBuffer();
          res.set('Content-Type', 'image/jpeg');
          return res.send(overlaidImage);
        }
      }

      res.json({
        success: true,
        imageUrl: `/events/${detection.original_filename}`,
        imagePath: detection.storage_path,
        metadata: detection.metadata ? JSON.parse(detection.metadata) : null,
        overlaysEnabled: overlays === 'true',
      });
    } catch (error) {
      logger.error('Error getting detection image', 'API', error);
      res.status(500).json({ success: false, error: 'Failed to get detection image' });
    }
  });

  // Snapshots list
  app.get('/api/snapshots/list', optionalAuth, async (req: Request, res: Response) => {
    try {
      const results = await AppDataSource.query(
        `SELECT COALESCE(df.storage_path, e.file_path) as file_path, COALESCE(df.capture_timestamp, e.timestamp) as timestamp FROM events e LEFT JOIN detection_files df ON e.file_path = df.storage_path OR e.file_path LIKE '%' || df.original_filename WHERE COALESCE(df.file_type, e.event_type) = 'snapshot' ORDER BY COALESCE(df.capture_timestamp, e.timestamp) DESC LIMIT 1000`,
      );
      res.json({ success: true, files: results.map((row: any) => row.file_path) });
    } catch (error) {
      logger.error('Error listing snapshots', 'API', error);
      res.status(500).json({ success: false, error: 'Failed to list snapshots' });
    }
  });

  // Domain routers
  app.use('/api/auth', authRoutes);
  app.use('/api/cameras', cameraRoutes);
  app.use('/api/streams', streamRoutes);
  app.use('/api/analytics', analyticsRoutes);
  app.use('/api/settings', settingsRoutes);
  app.use('/api/nvidia', nvidiaRoutes);
  app.use('/api/motion', motionRoutes);
  app.use('/api/events', eventSearchRoutes);
  app.use('/api/events', eventRoutes);
  app.use('/api/alerts', alertRoutes);
  app.use('/api/notifications', notificationRoutes);
  app.use('/api/detection', detectionOperationsRoutes);
  app.use('/api/detection', detectionRoutes);
  app.use('/api/detection-redo', detectionRedoRoutes);
  app.use('/api/highlights', highlightsRoutes);
  app.use('/api/timelapse', timelapseRoutes);

  app.use(createApiRateLimit());
}

import { logger } from '../utils/logger.js';
import { Router, Request, Response } from 'express';
import { z } from 'zod';
import { validateQuery, validateParams, validateBody } from '../middleware/zodValidation.js';
import { Server as SocketIOServer } from 'socket.io';
import { serviceRegistry } from '../services/serviceRegistry.js';
import { consolidatedDetectionService } from '../detection/consolidatedDetectionService.js';
import { inMemoryState } from '../services/inMemoryStateService.js';
import eventSearchService from '../services/eventSearchService.js';
import { optionalAuth, requireUser, requireAdmin } from '../middleware/auth.js';

const router = Router();

const limitQuerySchema = z.object({
  limit: z.preprocess(
    (v) => (v ? parseInt(v as string, 10) : undefined),
    z.number().min(1).max(1000).optional(),
  ),
});

const cameraIdParamsSchema = z.object({
  cameraId: z.string().regex(/^[a-zA-Z0-9_-]+$/),
});

const analyzeBodySchema = z.object({
  enablePersonDetection: z.boolean().optional(),
  enableFaceDetection: z.boolean().optional(),
});

router.get(
  '/events',
  optionalAuth,
  validateQuery(limitQuerySchema),
  async (req: Request, res: Response) => {
    try {
      const limit = Math.min(parseInt(req.query.limit as string) || 100, 1000);
      const events = await eventSearchService.getMotionEvents(limit);
      res.json({ success: true, events });
    } catch (error) {
      logger.error('Error getting motion events', 'Motion', error);
      res.status(500).json({ success: false, error: 'Failed to get motion events' });
    }
  },
);

router.get(
  '/:cameraId/events',
  optionalAuth,
  validateParams(cameraIdParamsSchema),
  validateQuery(limitQuerySchema),
  async (req: Request, res: Response) => {
    try {
      const limit = Math.min(parseInt(req.query.limit as string) || 20, 1000);
      const events = await eventSearchService.getCameraMotionEvents(req.params.cameraId, limit);
      res.json({ success: true, events });
    } catch (error) {
      logger.error(
        `Error getting motion events for camera ${req.params.cameraId}`,
        'Motion',
        error,
      );
      res.status(500).json({ success: false, error: 'Failed to get motion events' });
    }
  },
);

router.post(
  '/:cameraId/simulate',
  requireAdmin,
  validateParams(cameraIdParamsSchema),
  (req: Request, res: Response) => {
    try {
      const streamManager = serviceRegistry.getStreamManager();
      const camera = streamManager.getAllCameras().find((c: any) => c.id === req.params.cameraId);
      if (!camera) {
        res.status(404).json({ success: false, error: 'Camera not found' });
        return;
      }
      streamManager.simulateMotionDetection(req.params.cameraId);
      res.json({ success: true, message: 'Motion simulation triggered' });
    } catch (error) {
      logger.error(`Error simulating motion for camera ${req.params.cameraId}`, 'Motion', error);
      res.status(500).json({ success: false, error: 'Failed to simulate motion' });
    }
  },
);

router.post(
  '/:cameraId/analyze',
  requireUser,
  validateParams(cameraIdParamsSchema),
  validateBody(analyzeBodySchema),
  async (req: Request, res: Response) => {
    try {
      const streamManager = serviceRegistry.getStreamManager();
      const cameraId = req.params.cameraId;
      const { enablePersonDetection, enableFaceDetection } = req.body;
      const camera = streamManager.getAllCameras().find((c: any) => c.id === cameraId);
      if (!camera) {
        res.status(404).json({ success: false, error: 'Camera not found' });
        return;
      }
      const currentFrame = streamManager.getCurrentFrame(cameraId);
      if (!currentFrame) {
        res.status(400).json({ success: false, error: 'No frame available from camera' });
        return;
      }

      const analysisResults: any = { persons: [], faces: [], timestamp: new Date().toISOString() };
      if (enablePersonDetection) {
        try {
          const personResult = await consolidatedDetectionService.detectObjects(
            cameraId,
            currentFrame,
          );
          analysisResults.persons = personResult.detections.filter(
            (d: any) => d.class === 'person',
          );
        } catch (error) {
          logger.warn(`Person detection unavailable: ${error}`, 'Motion');
        }
      }
      if (enableFaceDetection) {
        try {
          const faceResult = await consolidatedDetectionService.detectFaces(cameraId, currentFrame);
          analysisResults.faces = faceResult.faces;
        } catch (error) {
          logger.warn(`Face detection unavailable: ${error}`, 'Motion');
        }
      }

      const io: SocketIOServer = (req.app as any).get('io');
      io.emit('enhancedMotionDetected', {
        cameraId,
        timestamp: new Date().toISOString(),
        hasPersons: analysisResults.persons.length > 0,
        hasFaces: analysisResults.faces.length > 0,
        personCount: analysisResults.persons.length,
        faceCount: analysisResults.faces.length,
        knownFaces: analysisResults.faces.filter((f: any) => f.isKnown).length,
        unknownFaces: analysisResults.faces.filter((f: any) => !f.isKnown).length,
        analysis: analysisResults,
      });
      res.json({ success: true, analysis: analysisResults });
    } catch (error) {
      logger.error(`Error analyzing motion for camera ${req.params.cameraId}`, 'Motion', error);
      res.status(500).json({ success: false, error: 'Failed to analyze motion' });
    }
  },
);

export default router;

