export default BatchProcessingDatabasePostgres;

import { logger } from '../utils/logger.js';
import { parentPort, workerData } from 'worker_threads';
import path from 'node:path';
import fs from 'node:fs';
import crypto from 'node:crypto';
import pkg from 'pg';
const { Client } = pkg;

interface WorkerMessage {
  type: 'progress' | 'completed' | 'error';
  progress?: {
    total: number;
    processed: number;
    successful: number;
    failed: number;
    currentFile?: string;
  };
  results?: {
    totalImages: number;
    personDetections: number;
    faceDetections: number;
    processingTime: number;
    details: Array<{
      filename: string;
      timestamp: string;
      cameraId: string;
      persons: Array<{
        confidence: number;
        boundingBox: {
          x: number;
          y: number;
          width: number;
          height: number;
        };
      }>;
      faces: Array<{
        confidence: number;
        boundingBox: {
          x: number;
          y: number;
          width: number;
          height: number;
        };
        personId?: string;
        personName?: string;
        isKnown: boolean;
      }>;
