/**
 * DetectionService — Normalization & filtering logic.
 * Normalizes raw detection data, filters by class thresholds, calculates medians.
 * Triggers EnhancedDetectionService for DB persistence.
 * See: consolidatedDetectionService (settings), enhancedDetectionService (DB persistence).
 */
import { Repository, IsNull } from 'typeorm';
import { DetectionConfig } from '../../models/DetectionConfig.js';
import { Event } from '../../models/Event.js';
import { Timeline } from '../../models/Timeline.js';
import { AdaptiveRegion } from '../../models/AdaptiveRegion.js';
import { AppDataSource } from '../../database.js';
import { TimelineService } from '../timeline/timelineService.js';
import { EnhancedDetectionService } from './enhancedDetectionService.js';
import { cacheService } from '../cacheService.js';

interface ThresholdConfig {
  min_score: number;
  threshold: number;
}

interface ScoreHistory {
  scores: number[];
  median: number;
  add(score: number): number;
}

const DEFAULT_THRESHOLDS: Record<string, ThresholdConfig> = {
  person: { min_score: 0.3, threshold: 0.5 },
  car: { min_score: 0.4, threshold: 0.6 },
  dog: { min_score: 0.3, threshold: 0.4 },
  package: { min_score: 0.25, threshold: 0.35 },
  cat: { min_score: 0.3, threshold: 0.45 },
  bicycle: { min_score: 0.35, threshold: 0.55 },
  motorcycle: { min_score: 0.35, threshold: 0.55 },
  truck: { min_score: 0.4, threshold: 0.6 },
  bus: { min_score: 0.4, threshold: 0.6 },
};

const DEFAULT_LABELMAP: Record<string, string> = {
  truck: 'car',
  bus: 'car',
  motorcycle: 'car',
  bicycle: 'person',
};

const CACHE_TTL = 3600;

export class DetectionService {
  private scoreHistories = new Map<string, ScoreHistory>();
  private configRepo: Repository<DetectionConfig> | null = null;

  constructor(configRepo?: Repository<DetectionConfig>) {
    if (configRepo) {
      this.configRepo = configRepo;
    }
  }

  private async getRepo(): Promise<Repository<DetectionConfig>> {
    if (!this.configRepo) {
      this.configRepo = AppDataSource.getRepository(DetectionConfig);
    }
    return this.configRepo;
  }

  async getConfig(camera?: string): Promise<{
    thresholds: Record<string, ThresholdConfig>;
    labelmap: Record<string, string>;
    score_history_length: number;
  }> {
    const cacheKey = `detection:config:${camera || 'global'}`;
    const cached = await cacheService.getJSON(cacheKey);
    if (cached) return cached;

    const repo = await this.getRepo();
    let config: DetectionConfig | null = null;

    if (camera) {
      config = await repo.findOne({ where: { camera } });
    }

    if (!config) {
      config = await repo.findOne({ where: { camera: IsNull() } });
    }

    const result = {
      thresholds: config?.config?.thresholds || DEFAULT_THRESHOLDS,
      labelmap: config?.config?.labelmap || DEFAULT_LABELMAP,
      score_history_length: config?.config?.score_history_length || 7,
    };

    await cacheService.set(cacheKey, result, CACHE_TTL);
    return result;
  }

  async updateConfig(
    camera: string | null,
    config: Partial<{
      thresholds: Record<string, ThresholdConfig>;
      labelmap: Record<string, string>;
      score_history_length: number;
    }>,
  ): Promise<void> {
    const repo = await this.getRepo();
    let existing = camera
      ? await repo.findOne({ where: { camera } })
      : await repo.findOne({ where: { camera: IsNull() } });

    const currentConfig = existing?.config || {
      thresholds: DEFAULT_THRESHOLDS,
      labelmap: DEFAULT_LABELMAP,
      score_history_length: 7,
    };

    const newConfig = {
      ...currentConfig,
      ...config,
      last_updated: new Date().toISOString(),
    };

    if (existing) {
      await repo.update(existing.id, {
        config: newConfig,
        updated_at: new Date(),
      });
    } else {
      await repo.save({
        camera,
        config: newConfig,
      });
    }

    await cacheService.del('detection:config:*');
  }

  filterDetections(
    detections: Array<{
      label: string;
      score: number;
      object_id?: string;
    }>,
    camera?: string,
  ): Array<{
    label: string;
    score: number;
    object_id?: string;
    filtered: boolean;
    reason?: string;
  }> {
    const config = this.getConfigSync(camera);
    const result: Array<{
      label: string;
      score: number;
      object_id?: string;
      filtered: boolean;
      reason?: string;
    }> = [];

    for (const detection of detections) {
      const mappedLabel = config.labelmap[detection.label] || detection.label;
      const threshold = config.thresholds[mappedLabel] || config.thresholds[detection.label];

      if (!threshold) {
        result.push({ ...detection, label: mappedLabel, filtered: false });
        continue;
      }

      const objectKey = detection.object_id || detection.label;
      let history = this.scoreHistories.get(objectKey);
      if (!history) {
        history = this.createScoreHistory(config.score_history_length);
        this.scoreHistories.set(objectKey, history);
      }

      const medianScore = history.add(detection.score);

      if (medianScore < threshold.min_score) {
        result.push({
          ...detection,
          label: mappedLabel,
          score: medianScore,
          filtered: true,
          reason: 'below_min_score',
        });
      } else {
        result.push({
          ...detection,
          label: mappedLabel,
          score: medianScore,
          filtered: false,
        });
      }
    }

    return result.filter((d) => !d.filtered);
  }

  private getConfigSync(camera?: string): {
    thresholds: Record<string, ThresholdConfig>;
    labelmap: Record<string, string>;
    score_history_length: number;
  } {
    return {
      thresholds: DEFAULT_THRESHOLDS,
      labelmap: DEFAULT_LABELMAP,
      score_history_length: 7,
    };
  }

  private createScoreHistory(maxLength: number): ScoreHistory {
    const scores: number[] = [];

    return {
      scores,
      get median() {
        if (scores.length === 0) return 0;
        const sorted = [...scores].sort((a, b) => a - b);
        const mid = Math.floor(sorted.length / 2);
        return sorted.length % 2 ? sorted[mid] : (sorted[mid - 1] + sorted[mid]) / 2;
      },
      add(score: number) {
        scores.push(score);
        if (scores.length > maxLength) {
          scores.shift();
        }
        return this.median;
      },
    };
  }

  clearScoreHistory(objectId?: string): void {
    if (objectId) {
      this.scoreHistories.delete(objectId);
    } else {
      this.scoreHistories.clear();
    }
  }

  getScoreHistory(objectId: string): number[] {
    return this.scoreHistories.get(objectId)?.scores || [];
  }

  /**
   * Process detection results using enhanced detection service
   */
  async processEnhancedDetection(
    cameraId: string,
    frame: Buffer,
    detections: Array<{
      label: string;
      score: number;
      object_id?: string;
    }>,
    eventType: 'motion' | 'person' | 'face' | 'object' | 'vehicle' | 'animal' = 'object',
    processingTime: number = 0,
    filePath?: string,
  ): Promise<Event> {
    if (!AppDataSource.isInitialized) {
      throw new Error('Database not initialized');
    }

    const eventRepo = AppDataSource.getRepository(Event);
    const configRepo = AppDataSource.getRepository(DetectionConfig);
    const timelineService = new TimelineService(
      AppDataSource.getRepository(Timeline),
      AppDataSource.getRepository(AdaptiveRegion),
    );
    const enhancedDetectionService = new EnhancedDetectionService(
      eventRepo,
      timelineService,
      configRepo,
    );

    // Convert detections to the format expected by EnhancedDetectionService
    const convertedDetections = detections.map((d) => ({
      class: d.label,
      confidence: d.score,
      bbox: { x: 0, y: 0, width: 0, height: 0 }, // Placeholder, will be filled by detection service
      label: d.object_id,
    }));

    return await enhancedDetectionService.processDetectionResults(
      cameraId,
      frame,
      convertedDetections,
      eventType,
      processingTime,
      filePath,
    );
  }
}

export const detectionService = new DetectionService();

/**
 * EnhancedDetectionService — Persistence & Timeline gateway.
 * Canonical service for DB persistence of detections (`Event`, `Timeline`).
 * NOT responsible for: configuration, raw detection logic, filtering.
 * See: consolidatedDetectionService (settings), detectionService (normalization).
 */
import { Repository } from 'typeorm';
import { DetectionConfig } from '../../models/DetectionConfig.js';
import { Event } from '../../models/Event.js';
import { Timeline } from '../../models/Timeline.js';
import { TimelineService } from '../timeline/timelineService.js';
import { DetectionResult } from '../../detection/consolidatedDetectionService.js';
import { cacheService } from '../cacheService.js';

export interface EnhancedDetectionData {
  id: string;
  cameraId: string;
  timestamp: Date;
  eventType: 'motion' | 'person' | 'face' | 'object' | 'vehicle' | 'animal';
  confidence: number;
  detections: Array<{
    class: string;
    confidence: number;
    bbox: {
      x: number;
      y: number;
      width: number;
      height: number;
    };
    label?: string;
    isKnown?: boolean;
  }>;
  metadata: {
    personCount: number;
    faceCount: number;
    vehicleCount: number;
    animalCount: number;
    objectCounts: Record<string, number>;
    processingTime: number;
    lightLevel?: number;
    motionArea?: number;
    hasPersons: boolean;
    hasFaces: boolean;
    knownFaces: number;
    unknownFaces: number;
    totalDetections: number;
    uniqueClasses: string[];
    [key: string]: any;
  };
  filePath?: string;
  thumbnailPath?: string;
}

export interface DetectionQuery {
  cameraId?: string;
  eventType?: string;
  after?: Date;
  before?: Date;
  minConfidence?: number;
  limit?: number;
  offset?: number;
}

export class EnhancedDetectionService {
  constructor(
    private readonly eventRepo: Repository<Event>,
    private readonly timelineService: TimelineService,
    private readonly configRepo: Repository<DetectionConfig>,
  ) {}

  /**
   * Save detection event to both events table and timeline
   */
  async saveDetection(detectionData: EnhancedDetectionData): Promise<Event> {
    // Create event record
    const event = this.eventRepo.create({
      event_type: detectionData.eventType,
      file_path: detectionData.filePath || '',
      thumbnail_path: detectionData.thumbnailPath || null,
      timestamp: detectionData.timestamp,
      camera_id: detectionData.cameraId,
      metadata: JSON.stringify(detectionData.metadata),
      confidence: detectionData.confidence,
      persons_detected: detectionData.metadata.personCount,
      faces_detected: detectionData.metadata.faceCount,
      known_faces_count: detectionData.metadata.knownFaces,
      unknown_faces_count: detectionData.metadata.unknownFaces,
      object_detections: detectionData.detections,
      face_detections: detectionData.detections.filter((d) => d.class.includes('face')),
    });

    const savedEvent = await this.eventRepo.save(event);

    // Add to timeline as well for unified tracking
    await this.timelineService.addTimelineEvent({
      timestamp: detectionData.timestamp,
      camera: detectionData.cameraId,
      source: 'tracked_object',
      sourceId: savedEvent.id,
      classType: detectionData.eventType,
      data: {
        ...detectionData.metadata,
        detections: detectionData.detections,
        confidence: detectionData.confidence,
      },
    });

    return savedEvent;
  }

  /**
   * Process and save detection results with enhanced metadata
   */
  async processDetectionResults(
    cameraId: string,
    frame: Buffer,
    detections: DetectionResult[],
    eventType: 'motion' | 'person' | 'face' | 'object' | 'vehicle' | 'animal' = 'object',
    processingTime: number = 0,
    filePath?: string,
  ): Promise<Event> {
    // Calculate enhanced metadata
    const metadata = this.calculateEnhancedMetadata(detections, processingTime);

    // Determine primary confidence as the highest among all detections
    const confidence =
      metadata.totalDetections > 0 ? Math.max(...detections.map((d) => d.confidence)) : 0;

    // Create detection data object
    const detectionData: EnhancedDetectionData = {
      id: `det_${Date.now()}_${Math.random().toString(36).substring(2, 8)}`,
      cameraId,
      timestamp: new Date(),
      eventType,
      confidence,
      detections: detections.map((d) => ({
        class: d.class,
        confidence: d.confidence,
        bbox: d.bbox,
      })),
      metadata,
      filePath,
    };

    // Save to database
    return await this.saveDetection(detectionData);
  }

  /**
   * Calculate enhanced metadata from detection results
   */
  private calculateEnhancedMetadata(
    detections: DetectionResult[],
    processingTime: number,
  ): EnhancedDetectionData['metadata'] {
    const personCount = detections.filter((d) => d.class === 'person').length;
    const faceCount = detections.filter(
      (d) => d.class.includes('face') || d.class === 'face',
    ).length;
    const vehicleCount = detections.filter((d) =>
      ['car', 'truck', 'bus', 'motorcycle', 'bicycle'].includes(d.class),
    ).length;
    const animalCount = detections.filter((d) =>
      ['dog', 'cat', 'bird', 'horse', 'sheep', 'cow'].includes(d.class),
    ).length;

    // Count unique object classes
    const uniqueClasses = new Set(detections.map((d) => d.class));
    const objectCounts: Record<string, number> = {};
    uniqueClasses.forEach((cls) => {
      objectCounts[cls] = detections.filter((d) => d.class === cls).length;
    });

    // Determine if there are known/unknown faces
    const knownFaces = detections.filter(
      (d) => d.class.includes('face') && d.label && d.label !== 'Unknown',
    ).length;
    const unknownFaces = detections.filter(
      (d) => d.class.includes('face') && (!d.label || d.label === 'Unknown'),
    ).length;

    return {
      personCount,
      faceCount,
      vehicleCount,
      animalCount,
      objectCounts,
      processingTime,
      hasPersons: personCount > 0,
      hasFaces: faceCount > 0,
      knownFaces,
      unknownFaces,
      totalDetections: detections.length,
      uniqueClasses: Array.from(uniqueClasses),
    };
  }

  /**
   * Get detection events with advanced filtering
   */
  async getDetections(query: DetectionQuery): Promise<{
    events: Event[];
    totalCount: number;
  }> {
    let queryBuilder = this.eventRepo.createQueryBuilder('event').where('1 = 1'); // Base condition

    if (query.cameraId) {
      queryBuilder = queryBuilder.andWhere('event.camera_id = :cameraId', {
        cameraId: query.cameraId,
      });
    }

    if (query.eventType) {
      queryBuilder = queryBuilder.andWhere('event.event_type = :eventType', {
        eventType: query.eventType,
      });
    }

    if (query.after) {
      queryBuilder = queryBuilder.andWhere('event.timestamp >= :after', { after: query.after });
    }

    if (query.before) {
      queryBuilder = queryBuilder.andWhere('event.timestamp <= :before', { before: query.before });
    }

    if (query.minConfidence !== undefined) {
      queryBuilder = queryBuilder.andWhere('event.confidence >= :minConfidence', {
        minConfidence: query.minConfidence,
      });
    }

    // Get total count
    const totalCount = await queryBuilder.getCount();

    // Apply ordering and limits
    queryBuilder = queryBuilder.orderBy('event.timestamp', 'DESC').limit(query.limit || 50);

    if (query.offset) {
      queryBuilder = queryBuilder.offset(query.offset);
    }

    const events = await queryBuilder.getMany();

    return { events, totalCount };
  }

  /**
   * Get detection statistics
   */
  async getDetectionStats(cameraId?: string): Promise<{
    totalDetections: number;
    byType: Record<string, number>;
    byDay: Record<string, number>;
    avgConfidence: number;
  }> {
    let queryBuilder = this.eventRepo
      .createQueryBuilder('event')
      .select([
        'COUNT(*) as totalDetections',
        'event.event_type as eventType',
        'DATE(event.timestamp) as day',
        'AVG(event.confidence) as avgConfidence',
      ])
      .groupBy('event.event_type')
      .addGroupBy('DATE(event.timestamp)');

    if (cameraId) {
      queryBuilder = queryBuilder.where('event.camera_id = :cameraId', { cameraId });
    }

    const results = await queryBuilder.getRawMany();

    const stats = {
      totalDetections: 0,
      byType: {} as Record<string, number>,
      byDay: {} as Record<string, number>,
      avgConfidence: 0,
    };

    let totalConfidence = 0;
    let confidenceCount = 0;

    results.forEach((row) => {
      stats.totalDetections += parseInt(row.totalDetections);
      stats.byType[row.eventType] =
        (stats.byType[row.eventType] || 0) + parseInt(row.totalDetections);
      stats.byDay[row.day] = (stats.byDay[row.day] || 0) + parseInt(row.totalDetections);

      if (row.avgConfidence !== null) {
        totalConfidence += parseFloat(row.avgConfidence) * parseInt(row.totalDetections);
        confidenceCount += parseInt(row.totalDetections);
      }
    });

    stats.avgConfidence = confidenceCount > 0 ? totalConfidence / confidenceCount : 0;

    return stats;
  }

  /**
   * Update detection event
   */
  async updateDetection(id: string, updates: Partial<Event>): Promise<Event | null> {
    const existing = await this.eventRepo.findOne({ where: { id } });
    if (!existing) {
      return null;
    }

    Object.assign(existing, updates);
    return await this.eventRepo.save(existing);
  }

  /**
   * Delete detection event
   */
  async deleteDetection(id: string): Promise<boolean> {
    const result = await this.eventRepo.delete(id);
    return result.affected !== 0;
  }
}

import { logger } from '../../utils/logger.js';
import { AppDataSource } from '../../database.js';
import { Event } from '../../models/Event.js';
import { DetectionDataNormalizer } from '../../utils/detectionDataNormalizer.js';
import { serviceRegistry } from '../serviceRegistry.js';
import type {
  EventSearchFilters,
  EventSearchResponse,
  ListEnhancedFilters,
  HistoryFilters,
  LegacySearchFilters,
  DetectionEventFilters,
} from './types.js';

export class EventSearchService {
  private eventRepository = AppDataSource.getRepository(Event);

  private getConfidenceThreshold(level: string): number {
    switch (level) {
      case 'low':
        return 0;
      case 'medium':
        return 0.5;
      case 'high':
        return 0.8;
      default:
        return 0;
    }
  }

  private extractConfidence(metadata: any): number {
    let confidence = 0.75;
    if (metadata && typeof metadata === 'object') {
      if (metadata.confidence !== undefined) confidence = metadata.confidence;
      else if (metadata.persons?.length > 0) confidence = metadata.persons[0].confidence || 0.75;
      else if (metadata.faces?.length > 0) confidence = metadata.faces[0].confidence || 0.75;
    }
    if (confidence > 1) confidence /= 100;
    return confidence;
  }

  async searchEvents(filters: EventSearchFilters): Promise<EventSearchResponse> {
    const query = this.eventRepository.createQueryBuilder('event');

    if (filters.startDate)
      query.andWhere('event.timestamp >= :startDate', { startDate: filters.startDate });
    if (filters.endDate)
      query.andWhere('event.timestamp <= :endDate', { endDate: filters.endDate });
    if (filters.cameraId)
      query.andWhere('event.camera_id = :cameraId', { cameraId: filters.cameraId });
    if (filters.eventType)
      query.andWhere('event.event_type = :eventType', { eventType: filters.eventType });

    if (filters.confidence) {
      query.andWhere('event.confidence >= :minConfidence', {
        minConfidence: this.getConfidenceThreshold(filters.confidence),
      });
    }

    if (filters.faceStatus === 'recognized') query.andWhere('event.known_faces_count > 0');
    else if (filters.faceStatus === 'unknown')
      query.andWhere('event.faces_detected > 0').andWhere('event.known_faces_count = 0');
    else if (filters.faceStatus === 'none') query.andWhere('event.faces_detected = 0');

    const page = filters.page || 1;
    const pageSize = Math.min(filters.pageSize || 20, 100);
    const sortBy = filters.sortBy || 'timestamp';
    const sortOrder = filters.sortOrder || 'DESC';
    const validSortFields = ['timestamp', 'confidence', 'camera_id'];
    const sortField = validSortFields.includes(sortBy) ? sortBy : 'timestamp';

    query.orderBy(`event.${sortField}`, sortOrder);

    const [events, totalEvents] = await query
      .skip((page - 1) * pageSize)
      .take(pageSize)
      .getManyAndCount();

    return {
      events: events.map((event) => ({
        id: event.id,
        eventType: event.event_type,
        timestamp: event.timestamp,
        cameraId: event.camera_id,
        confidence: event.confidence,
        personsDetected: event.persons_detected,
        facesDetected: event.faces_detected,
        knownFacesCount: event.known_faces_count,
        unknownFacesCount: event.unknown_faces_count,
        objectDetections: event.object_detections || [],
        faceDetections: event.face_detections || [],
        imageUrl: event.file_path ? `/api/events/image/${event.file_path.split('/').pop()}` : null,
        metadata: event.metadata ? JSON.parse(event.metadata) : null,
      })),
      pagination: {
        page,
        pageSize,
        totalEvents,
        totalPages: Math.ceil(totalEvents / pageSize),
        hasNext: page < Math.ceil(totalEvents / pageSize),
        hasPrevious: page > 1,
      },
    };
  }

  async listEnhanced(filters: ListEnhancedFilters): Promise<{
    events: Record<string, unknown>[];
    pagination: { totalEvents: number; currentPage: number; pageSize: number; totalPages: number };
  }> {
    const {
      page = '1',
      pageSize = '100',
      event_type,
      camera_id,
      start_date,
      end_date,
      searchQuery,
      sortBy = 'newest',
      min_confidence,
      max_confidence,
      face_status,
    } = filters;

    const currentPage = Math.max(1, parseInt(page));
    const size = Math.min(500, Math.max(1, parseInt(pageSize)));
    const offset = (currentPage - 1) * size;

    const conditions: string[] = [
      "e.event_type IN ('motion', 'face', 'person', 'visitor', 'recognition', 'event_motion', 'event_face')",
      "e.file_path IS NOT NULL AND e.file_path != ''",
    ];
    const queryParams: unknown[] = [];
    let paramIndex = 1;

    if (camera_id && camera_id !== 'all') {
      conditions.push(`e.camera_id = $${paramIndex++}`);
      queryParams.push(camera_id);
    }
    if (start_date) {
      conditions.push(`e.timestamp >= $${paramIndex++}::timestamptz`);
      queryParams.push(start_date.replace(' 00:00:00', ''));
    }
    if (end_date) {
      conditions.push(`e.timestamp <= $${paramIndex++}::timestamptz`);
      queryParams.push(end_date.replace(' 23:59:59', ''));
    }
    if (searchQuery?.trim()) {
      conditions.push(`(e.camera_id ILIKE $${paramIndex} OR e.file_path ILIKE $${paramIndex})`);
      queryParams.push(`%${searchQuery.toLowerCase().trim()}%`);
      paramIndex++;
    }
    if (event_type && event_type !== 'all') {
      if (event_type === 'face') conditions.push(`COALESCE(e.faces_detected, 0) > 0`);
      else if (event_type === 'person') conditions.push(`COALESCE(e.persons_detected, 0) > 0`);
      else if (event_type === 'vehicle')
        conditions.push(
          `e.object_detections IS NOT NULL AND e.object_detections::jsonb @> ANY(ARRAY['[{"class":"car"}]','[{"class":"truck"}]','[{"class":"motorcycle"}]','[{"class":"bicycle"}]','[{"class":"bus"}]','[{"class":"van"}]','[{"class":"suv"}]']::jsonb[])`,
        );
      else if (event_type === 'motion')
        conditions.push(`e.event_type IN ('motion', 'event_motion')`);
    }
    if (min_confidence) {
      conditions.push(`(COALESCE(e.confidence, 0) >= $${paramIndex++})`);
      queryParams.push(parseFloat(min_confidence));
    }
    if (max_confidence) {
      conditions.push(`(COALESCE(e.confidence, 0) <= $${paramIndex++})`);
      queryParams.push(parseFloat(max_confidence));
    }
    if (face_status && face_status !== 'all') {
      switch (face_status) {
        case 'has_faces':
          conditions.push(`COALESCE(e.faces_detected, 0) > 0`);
          break;
        case 'known_faces':
          conditions.push(`COALESCE(e.known_faces_count, 0) > 0`);
          break;
        case 'unknown_faces':
          conditions.push(
            `COALESCE(e.faces_detected, 0) > 0 AND COALESCE(e.known_faces_count, 0) = 0`,
          );
          break;
        case 'no_faces':
          conditions.push(`(COALESCE(e.faces_detected, 0) = 0 OR e.faces_detected IS NULL)`);
          break;
      }
    }

    const whereClause = `WHERE ${conditions.join(' AND ')}`;
    const orderClause =
      sortBy === 'oldest'
        ? 'ORDER BY e.timestamp ASC'
        : sortBy === 'confidence'
          ? 'ORDER BY e.confidence DESC, e.timestamp DESC'
          : 'ORDER BY e.timestamp DESC';

    const countResult = await AppDataSource.query(
      `SELECT COUNT(*) as total FROM events e ${whereClause}`,
      queryParams,
    );
    const totalEvents = parseInt(countResult[0]?.total || '0');

    const events = await AppDataSource.query(
      `SELECT e.id, e.event_type, e.timestamp, e.camera_id, e.confidence,
        e.file_path, e.metadata, e.persons_detected, e.faces_detected,
        e.known_faces_count, e.object_detections, e.face_detections,
        e.unknown_faces_count,
        a.scene_description, a.scene_context, a.threat_level, a.threat_confidence,
        a.detected_people, a.detected_vehicles, a.detected_objects,
        a.detected_animals, a.recommended_actions, a.additional_observations,
        a.model_used, a.processing_time_ms, a.analyzed_at
      FROM events e
      LEFT JOIN ai_analysis_results a ON e.id::text = a.event_id
      ${whereClause} ${orderClause} LIMIT $${paramIndex++} OFFSET $${paramIndex}`,
      [...queryParams, size, offset],
    );

    const safeJson = (val: any) => {
      if (!val) return [];
      try {
        return typeof val === 'object' ? val : JSON.parse(val);
      } catch {
        return [];
      }
    };

    const mapped = events.map((row: Record<string, unknown>) => ({
      id: row.id,
      event_type: row.event_type,
      cameraId: row.camera_id || 'unknown',
      timestamp: row.timestamp,
      imageUrl: row.file_path
        ? `/api/events/image/${String(row.file_path).split('/').pop()}`
        : null,
      confidence: row.confidence || 0,
      persons_detected: row.persons_detected || 0,
      faces_detected: row.faces_detected || 0,
      known_faces_count: row.known_faces_count || 0,
      label: row.label,
      is_read: row.is_read,
      object_detections:
        typeof row.object_detections === 'string'
          ? JSON.parse(row.object_detections as string)
          : row.object_detections,
      face_detections:
        typeof row.face_detections === 'string'
          ? JSON.parse(row.face_detections as string)
          : row.face_detections,
      analysis: row.scene_description
        ? (() => {
            const rawDesc = row.scene_description || '';
            const plainDesc =
              typeof rawDesc === 'string' && rawDesc.trim().startsWith('{')
                ? (() => {
                    try {
                      const p = JSON.parse(rawDesc.trim());
                      return (
                        p.scene_description ||
                        p.sceneDescription ||
                        p.description ||
                        p.summary ||
                        p.overall_summary ||
                        rawDesc
                      );
                    } catch {
                      try {
                        const match = rawDesc
                          .trim()
                          .match(/"scene_description"\s*:\s*"((?:[^\n"\\]|\\.)*)"/);
                        if (match) return match[1];
                      } catch {}
                      return rawDesc;
                    }
                  })()
                : rawDesc;
            return {
              sceneDescription: plainDesc,
              sceneContext: row.scene_context
                ? typeof row.scene_context === 'string'
                  ? JSON.parse(row.scene_context)
                  : row.scene_context
                : { environment: 'unknown' },
              threatAssessment: {
                level: row.threat_level || 'low',
                factors: [] as string[],
                confidence: row.threat_confidence || 0,
              },
              detectedEntities: {
                people: safeJson(row.detected_people),
                vehicles: safeJson(row.detected_vehicles),
                objects: safeJson(row.detected_objects),
                animals: safeJson(row.detected_animals),
              },
              recommendedActions: safeJson(row.recommended_actions),
              modelUsed: row.model_used,
              processingTime: row.processing_time_ms,
              analyzedAt: row.analyzed_at,
            };
          })()
        : null,
    }));

    let streamManager: ReturnType<typeof serviceRegistry.getStreamManager> | null = null;
    try {
      streamManager = serviceRegistry.getStreamManager();
    } catch (err) {
      logger.warn('Failed to get stream manager', 'EventSearch', err);
      streamManager = null;
    }

    const eventsWithCameraName = mapped.map((evt: Record<string, unknown>) => ({
      ...evt,
      cameraName:
        streamManager?.getCamera(evt.cameraId as string)?.name || `Camera ${evt.cameraId}`,
    }));

    return {
      events: eventsWithCameraName,
      pagination: {
        totalEvents,
        currentPage,
        pageSize: size,
        totalPages: Math.ceil(totalEvents / size),
      },
    };
  }

  async getHistory(filters: HistoryFilters): Promise<{
    events: Record<string, unknown>[];
    pagination: { totalEvents: number; currentPage: number; pageSize: number; totalPages: number };
  }> {
    const {
      limit = '50',
      page = '1',
      pageSize = '50',
      cameraId: cameraIdFilter,
      event_type: detectionType,
      startDate: startDateStr,
      endDate: endDateStr,
      searchQuery,
      sortBy = 'newest',
    } = filters;

    const currentPage = Math.max(1, parseInt(page));
    const size = Math.min(500, Math.max(1, parseInt(limit) || parseInt(pageSize)));
    const offsetCount = (currentPage - 1) * size;

    const conditions: string[] = [
      "e.event_type IN ('motion', 'face', 'person', 'visitor', 'recognition', 'event_motion', 'event_face')",
    ];
    const values: unknown[] = [];
    let paramIndex = 1;

    if (cameraIdFilter && cameraIdFilter !== 'all') {
      conditions.push(`e.camera_id = $${paramIndex++}`);
      values.push(cameraIdFilter);
    }
    if (detectionType && detectionType !== 'all') {
      if (detectionType === 'face')
        conditions.push(`e.event_type IN ('face', 'event_face', 'recognition')`);
      else if (detectionType === 'person')
        conditions.push(
          `e.event_type IN ('person', 'visitor', 'recognition') OR COALESCE(e.persons_detected, 0) > 0`,
        );
      else if (detectionType === 'motion')
        conditions.push(`e.event_type IN ('motion', 'event_motion')`);
    }
    if (startDateStr) {
      conditions.push(`e.timestamp >= $${paramIndex++}`);
      values.push(new Date(startDateStr));
    }
    if (endDateStr) {
      conditions.push(`e.timestamp <= $${paramIndex++}`);
      values.push(new Date(endDateStr));
    }
    if (searchQuery?.trim()) {
      conditions.push(`(e.camera_id ILIKE $${paramIndex++} OR e.file_path ILIKE $${paramIndex++})`);
      values.push(`%${searchQuery.toLowerCase()}%`, `%${searchQuery.toLowerCase()}%`);
    }

    const whereClause = `WHERE ${conditions.join(' AND ')}`;
    const orderClause =
      sortBy === 'oldest'
        ? 'ORDER BY e.timestamp ASC'
        : sortBy === 'confidence'
          ? 'ORDER BY e.confidence DESC, e.timestamp DESC'
          : 'ORDER BY e.timestamp DESC';

    const countResult = await AppDataSource.query(
      `SELECT COUNT(*) as total FROM events e ${whereClause}`,
      values,
    );
    const totalEvents = parseInt(countResult[0]?.total || '0');

    const results = await AppDataSource.query(
      `SELECT e.*, df.file_uuid, df.storage_path, df.file_type
       FROM events e
       LEFT JOIN detection_files df ON e.file_path = df.storage_path OR e.file_path LIKE '%' || df.original_filename
       ${whereClause} ${orderClause} LIMIT $${paramIndex++} OFFSET $${paramIndex}`,
      [...values, size, offsetCount],
    );

    const events = results.map((row: Record<string, unknown>) => {
      let metadata = row.metadata;
      if (typeof metadata === 'string') {
        try {
          metadata = JSON.parse(metadata as string);
        } catch (err) {
          logger.warn('Failed to parse event metadata JSON', 'EventSearch', err);
          metadata = {};
        }
      }
      let confidence = 0.75;
      if (metadata && typeof metadata === 'object') {
        const m = metadata as Record<string, unknown>;
        if (m.confidence !== undefined) confidence = m.confidence as number;
        else if (Array.isArray(m.persons) && m.persons.length > 0)
          confidence = ((m.persons[0] as Record<string, unknown>).confidence as number) || 0.75;
        else if (Array.isArray(m.faces) && m.faces.length > 0)
          confidence = ((m.faces[0] as Record<string, unknown>).confidence as number) || 0.75;
      }
      if (confidence > 1) confidence = confidence / 100;
      let labels = ['motion'];
      const fileType = row.file_type as string;
      if (fileType === 'face') labels = ['face'];
      else if (fileType === 'motion') labels = ['motion'];
      const fp = (row.storage_path as string) || (row.file_path as string) || '';
      const imagePathForFrontend = fp.split('/').pop() || '';
      return {
        id: row.file_uuid || row.id,
        cameraId: row.camera_id || 'unknown',
        timestamp: new Date(row.timestamp as string).toISOString(),
        imagePath: imagePathForFrontend,
        imageUrl: `/events/${imagePathForFrontend}`,
        confidence,
        labels,
        location: `Camera ${row.camera_id || 'unknown'}`,
        duration: 0,
        cameraName: `Camera ${row.camera_id || 'unknown'}`,
        event_type: fileType,
      };
    });

    return {
      events,
      pagination: {
        totalEvents,
        currentPage,
        pageSize: size,
        totalPages: Math.ceil(totalEvents / size),
      },
    };
  }

