import { describe, it, expect, beforeEach } from '@jest/globals';
import { InMemoryStateService, inMemoryState } from './inMemoryStateService.js';
import type { MotionEvent, Alert, SystemSettings } from './inMemoryStateService.js';

describe('InMemoryStateService', () => {
  let service: InMemoryStateService;

  beforeEach(() => {
    service = new InMemoryStateService();
  });

  describe('addRecentEvent / getRecentEvents', () => {
    it('should return empty array when no events added', () => {
      expect(service.getRecentEvents()).toEqual([]);
    });

    it('should return array with 1 item after adding one event', () => {
      const event: MotionEvent = {
        id: 'evt-1',
        cameraId: 'cam1',
        timestamp: '2026-01-01T00:00:00Z',
        imagePath: '/events/motion_1.jpg',
        confidence: 75,
        duration: 100,
      };
      service.addRecentEvent(event);
      const events = service.getRecentEvents();
      expect(events.length).toBe(1);
      expect(events[0].id).toBe('evt-1');
    });

    it('should cap at 100 events when adding more', () => {
      for (let i = 0; i < 101; i++) {
        service.addRecentEvent({
          id: `evt-${i}`,
          cameraId: 'cam1',
          timestamp: `2026-01-01T${String(i).padStart(2, '0')}:00:00Z`,
          imagePath: `/events/motion_${i}.jpg`,
          confidence: 50,
          duration: 100,
        });
      }
      const events = service.getRecentEvents();
      expect(events.length).toBe(100);
    });

    it('should return events in reverse chronological order (newest first)', () => {
      service.addRecentEvent({
        id: 'evt-old',
        cameraId: 'cam1',
        timestamp: '2026-01-01T00:00:00Z',
        imagePath: '/events/old.jpg',
        confidence: 50,
        duration: 100,
      });
      service.addRecentEvent({
        id: 'evt-new',
        cameraId: 'cam1',
        timestamp: '2026-01-01T01:00:00Z',
        imagePath: '/events/new.jpg',
        confidence: 60,
        duration: 100,
      });
      const events = service.getRecentEvents();
      expect(events[0].id).toBe('evt-new');
      expect(events[1].id).toBe('evt-old');
    });

    it('should keep only the most recent 100 events (oldest dropped)', () => {
      for (let i = 0; i < 105; i++) {
        service.addRecentEvent({
          id: `evt-${i}`,
          cameraId: 'cam1',
          timestamp: `2026-01-01T${String(i % 24).padStart(2, '0')}:00:00Z`,
          imagePath: `/events/motion_${i}.jpg`,
          confidence: 50,
          duration: 100,
        });
      }
      const events = service.getRecentEvents();
      // The last event added should be evt-104 (most recent)
      expect(events[0].id).toBe('evt-104');
      // The first event should be evt-5 (oldest kept)
      expect(events[99].id).toBe('evt-5');
    });
  });

  describe('clearRecentEvents', () => {
    it('should clear all events', () => {
      service.addRecentEvent({
        id: 'evt-1',
        cameraId: 'cam1',
        timestamp: '2026-01-01T00:00:00Z',
        imagePath: '/events/1.jpg',
        confidence: 50,
        duration: 100,
      });
      service.clearRecentEvents();
      expect(service.getRecentEvents()).toEqual([]);
    });
  });

  describe('addAlert / getAlerts', () => {
    it('should return empty array when no alerts added', () => {
      expect(service.getAlerts()).toEqual([]);
    });

    it('should add alert with auto-generated id and timestamp', () => {
      service.addAlert({
        type: 'motion',
        severity: 'warning',
        message: 'Motion detected',
      });
      const alerts = service.getAlerts();
      expect(alerts.length).toBe(1);
      expect(alerts[0].id).toBeDefined();
      expect(alerts[0].timestamp).toBeInstanceOf(Date);
      expect(alerts[0].acknowledged).toBe(false);
      expect(alerts[0].type).toBe('motion');
      expect(alerts[0].severity).toBe('warning');
      expect(alerts[0].message).toBe('Motion detected');
    });

    it('should cap at 100 alerts when adding more', () => {
      for (let i = 0; i < 101; i++) {
        service.addAlert({
          type: 'system',
          severity: 'info',
          message: `Alert ${i}`,
        });
      }
      const alerts = service.getAlerts();
      expect(alerts.length).toBe(100);
    });

    it('should return alerts in reverse chronological order', () => {
      service.addAlert({ type: 'motion', severity: 'info', message: 'First' });
      service.addAlert({ type: 'system', severity: 'warning', message: 'Second' });
      const alerts = service.getAlerts();
      expect(alerts[0].message).toBe('Second');
      expect(alerts[1].message).toBe('First');
    });
  });

  describe('acknowledgeAlert', () => {
    it('should mark alert as acknowledged', async () => {
      await service.addAlert({ type: 'motion', severity: 'warning', message: 'Test' });
      const alerts = service.getAlerts();
      const alertId = alerts[0].id;
      const result = await service.acknowledgeAlert(alertId);
      expect(result).toBe(true);
      expect(service.getAlerts()[0].acknowledged).toBe(true);
    });

    it('should return false for non-existent alert', async () => {
      const result = await service.acknowledgeAlert('non-existent-id');
      expect(result).toBe(false);
    });
  });

  describe('deleteAlert', () => {
    it('should remove alert by id', async () => {
      await service.addAlert({ type: 'motion', severity: 'warning', message: 'To Delete' });
      const alerts = service.getAlerts();
      const alertId = alerts[0].id;
      const result = await service.deleteAlert(alertId);
      expect(result).toBe(true);
      expect(service.getAlerts().length).toBe(0);
    });

    it('should return false for non-existent alert', async () => {
      const result = await service.deleteAlert('non-existent-id');
      expect(result).toBe(false);
    });
  });

  describe('clearAlerts', () => {
    it('should clear all alerts', () => {
      service.addAlert({ type: 'motion', severity: 'warning', message: 'Alert 1' });
      service.addAlert({ type: 'system', severity: 'error', message: 'Alert 2' });
      service.clearAlerts();
      expect(service.getAlerts()).toEqual([]);
    });
  });

  describe('System settings CRUD', () => {
    it('should return default settings when none set', () => {
      const settings = service.getSystemSettings();
      expect(settings).toBeDefined();
      expect(settings.general.systemName).toBe('Security System');
      expect(settings.general.timezone).toBe('UTC');
      expect(settings.storage.retentionDays).toBe(7);
      expect(settings.notifications.pushEnabled).toBe(true);
    });

    it('should store and retrieve custom settings', () => {
      const customSettings: SystemSettings = {
        general: {
          systemName: 'My Custom System',
          timezone: 'Asia/Kolkata',
          language: 'hi',
          theme: 'dark',
          autoBackup: false,
          backupFrequency: 'weekly',
        },
        storage: {
          retentionDays: 30,
          maxStorageGB: 500,
          autoCleanup: true,
          compressionEnabled: true,
          compressionQuality: 90,
        },
        notifications: {
          emailEnabled: true,
          emailAddress: 'test@example.com',
          pushEnabled: false,
          pushSoundEnabled: false,
          quietHoursEnabled: true,
          quietHoursStart: '23:00',
          quietHoursEnd: '06:00',
        },
      };
      service.setSystemSettings(customSettings);
      const retrieved = service.getSystemSettings();
      expect(retrieved.general.systemName).toBe('My Custom System');
      expect(retrieved.general.timezone).toBe('Asia/Kolkata');
      expect(retrieved.storage.retentionDays).toBe(30);
      expect(retrieved.notifications.emailEnabled).toBe(true);
    });

    it('should return default settings after clearing', () => {
      service.setSystemSettings({
        general: {
          systemName: 'Custom',
          timezone: 'EST',
          language: 'en',
          theme: 'light',
          autoBackup: false,
          backupFrequency: 'monthly',
        },
        storage: {
          retentionDays: 14,
          maxStorageGB: 200,
          autoCleanup: false,
          compressionEnabled: false,
          compressionQuality: 50,
        },
        notifications: {
          emailEnabled: false,
          emailAddress: '',
          pushEnabled: true,
          pushSoundEnabled: true,
          quietHoursEnabled: false,
          quietHoursStart: '22:00',
          quietHoursEnd: '07:00',
        },
      });
      service.clearSystemSettings();
      const settings = service.getSystemSettings();
      expect(settings.general.systemName).toBe('Security System');
    });

    it('should return a copy of default settings (not reference)', () => {
      const settings1 = service.getDefaultSettings();
      const settings2 = service.getDefaultSettings();
      expect(settings1).toEqual(settings2);
      expect(settings1).not.toBe(settings2); // Different objects
    });
  });

  describe('Thread safety', () => {
    it('should return a copy of events array, not the original', () => {
      service.addRecentEvent({
        id: 'evt-1',
        cameraId: 'cam1',
        timestamp: '2026-01-01T00:00:00Z',
        imagePath: '/events/1.jpg',
        confidence: 50,
        duration: 100,
      });
      const events = service.getRecentEvents();
      events.push({
        id: 'evt-external',
        cameraId: 'cam1',
        timestamp: '2026-01-01T00:00:00Z',
        imagePath: '/events/external.jpg',
        confidence: 99,
        duration: 100,
      });
      // The service's internal array should not be affected
      expect(service.getRecentEvents().length).toBe(1);
    });

    it('should return a copy of alerts array, not the original', () => {
      service.addAlert({ type: 'motion', severity: 'info', message: 'Test' });
      const alerts = service.getAlerts();
      alerts.push({
        id: 'alert-external',
        type: 'system',
        severity: 'error',
        message: 'External',
        timestamp: new Date(),
        acknowledged: false,
      });
      // The service's internal array should not be affected
      expect(service.getAlerts().length).toBe(1);
    });
  });

  describe('Singleton instance', () => {
    it('should export a singleton instance', () => {
      expect(inMemoryState).toBeDefined();
      expect(inMemoryState).toBeInstanceOf(InMemoryStateService);
    });
  });
});

import crypto from 'node:crypto';
import { AppDataSource } from '../database.js';
import { logger } from '../utils/logger.js';

export interface MotionEvent {
  id: string;
  cameraId: string;
  timestamp: string;
  imagePath: string;
  confidence: number;
  duration: number;
  cameraName?: string;
  labels?: string[];
  location?: string;
}

export interface Alert {
  id: string;
  type: 'motion' | 'camera' | 'system';
  severity: 'info' | 'warning' | 'error';
  message: string;
  timestamp: Date;
  acknowledged: boolean;
  cameraId?: string;
}

export interface GeneralSettings {
  systemName: string;
  timezone: string;
  language: string;
  theme: string;
  autoBackup: boolean;
  backupFrequency: string;
}

export interface StorageSettings {
  retentionDays: number;
  maxStorageGB: number;
  autoCleanup: boolean;
  compressionEnabled: boolean;
  compressionQuality: number;
}

export interface NotificationSettings {
  emailEnabled: boolean;
  emailAddress: string;
  pushEnabled: boolean;
  pushSoundEnabled: boolean;
  quietHoursEnabled: boolean;
  quietHoursStart: string;
  quietHoursEnd: string;
}

export interface SystemSettings {
  general: GeneralSettings;
  storage: StorageSettings;
  notifications: NotificationSettings;
}

const MAX_ENTRIES = 100;

const defaultSystemSettings: SystemSettings = {
  general: {
    systemName: 'Security System',
    timezone: 'UTC',
    language: 'en',
    theme: 'system',
    autoBackup: true,
    backupFrequency: 'daily',
  },
  storage: {
    retentionDays: 7,
    maxStorageGB: 100,
    autoCleanup: true,
    compressionEnabled: true,
    compressionQuality: 80,
  },
  notifications: {
    emailEnabled: false,
    emailAddress: '',
    pushEnabled: true,
    pushSoundEnabled: true,
    quietHoursEnabled: false,
    quietHoursStart: '22:00',
    quietHoursEnd: '07:00',
  },
};

export class InMemoryStateService {
  private recentEvents: MotionEvent[] = [];
  private alerts: Alert[] = [];
  private cachedSystemSettings: SystemSettings | null = null;
  private refreshTimer: ReturnType<typeof setInterval> | null = null;
  private readonly refreshIntervalMs: number;

  constructor() {
    this.refreshIntervalMs = parseInt(process.env.IN_MEMORY_REFRESH_INTERVAL || '60000', 10);
  }

  async startPeriodicRefresh(): Promise<void> {
    if (this.refreshTimer) return;
    logger.info(
      `Starting periodic refresh for in-memory state (interval: ${this.refreshIntervalMs}ms)`,
      'InMemoryState',
    );
    this.refreshTimer = setInterval(async () => {
      try {
        await this.loadAlertsFromDb();
      } catch (err) {
        logger.error('Failed to periodically refresh alerts from DB', 'InMemoryState', err);
      }
    }, this.refreshIntervalMs);
  }

  stopPeriodicRefresh(): void {
    if (this.refreshTimer) {
      clearInterval(this.refreshTimer);
      this.refreshTimer = null;
      logger.info('Stopped periodic refresh for in-memory state', 'InMemoryState');
    }
  }

  addRecentEvent(event: MotionEvent): void {
    this.recentEvents.unshift(event);
    if (this.recentEvents.length > MAX_ENTRIES) {
      this.recentEvents.pop();
    }
  }

  getRecentEvents(): MotionEvent[] {
    return [...this.recentEvents];
  }

  clearRecentEvents(): void {
    this.recentEvents = [];
  }

  removeEvent(eventId: string): boolean {
    const index = this.recentEvents.findIndex((e) => e.id === eventId);
    if (index === -1) return false;
    this.recentEvents.splice(index, 1);
    return true;
  }

  // ---- Alerts ----

  async addAlert(alert: Omit<Alert, 'id' | 'timestamp' | 'acknowledged'>): Promise<void> {
    const newAlert: Alert = {
      id: crypto.randomUUID(),
      timestamp: new Date(),
      acknowledged: false,
      ...alert,
    };
    this.alerts.unshift(newAlert);
    if (this.alerts.length > MAX_ENTRIES) {
      this.alerts.pop();
    }

    try {
      await AppDataSource.query(
        `INSERT INTO alerts (id, type, severity, message, camera_id, acknowledged, created_at)
         VALUES ($1, $2, $3, $4, $5, $6, $7)`,
        [
          newAlert.id,
          newAlert.type,
          newAlert.severity,
          newAlert.message,
          newAlert.cameraId || null,
          false,
          newAlert.timestamp,
        ],
      );
    } catch (error: unknown) {
      const msg = error instanceof Error ? error.message : String(error);
      logger.warn(`Failed to persist alert to database: ${msg}`, 'InMemoryState');
    }
  }

  getAlerts(): Alert[] {
    return [...this.alerts];
  }

  async loadAlertsFromDb(): Promise<void> {
    try {
      const rows = (await AppDataSource.query(
        'SELECT id, type, severity, message, camera_id, acknowledged, created_at FROM alerts ORDER BY created_at DESC LIMIT $1',
        [MAX_ENTRIES],
      )) as any[];

      this.alerts = rows.map((r) => ({
        id: r.id,
        type: r.type,
        severity: r.severity,
        message: r.message,
        timestamp: new Date(r.created_at),
        acknowledged: r.acknowledged,
        cameraId: r.camera_id || undefined,
      }));
      logger.info(`Loaded ${this.alerts.length} alerts from database`, 'InMemoryState');
    } catch (error: unknown) {
      const msg = error instanceof Error ? error.message : String(error);
      logger.warn(`Could not load alerts from database: ${msg}`, 'InMemoryState');
    }
  }

  async acknowledgeAlert(alertId: string): Promise<boolean> {
    const alert = this.alerts.find((a) => a.id === alertId);
    if (!alert) return false;
    alert.acknowledged = true;
    try {
      await AppDataSource.query(
        'UPDATE alerts SET acknowledged = TRUE, updated_at = CURRENT_TIMESTAMP WHERE id = $1',
        [alertId],
      );
    } catch (error: unknown) {
      const msg = error instanceof Error ? error.message : String(error);
      logger.warn(`Failed to persist alert acknowledgment to database: ${msg}`, 'InMemoryState');
    }
    return true;
  }

  async deleteAlert(alertId: string): Promise<boolean> {
    const index = this.alerts.findIndex((a) => a.id === alertId);
    if (index === -1) return false;
    this.alerts.splice(index, 1);
    try {
      await AppDataSource.query('DELETE FROM alerts WHERE id = $1', [alertId]);
    } catch (error: unknown) {
      const msg = error instanceof Error ? error.message : String(error);
      logger.warn(`Failed to delete alert from database: ${msg}`, 'InMemoryState');
    }
    return true;
  }

  async clearAlerts(): Promise<void> {
    this.alerts = [];
    try {
      await AppDataSource.query('DELETE FROM alerts');
    } catch (error: unknown) {
      const msg = error instanceof Error ? error.message : String(error);
      logger.warn(`Failed to clear alerts from database: ${msg}`, 'InMemoryState');
    }
  }

  // ---- System Settings ----

  getSystemSettings(): SystemSettings {
    return this.cachedSystemSettings ?? defaultSystemSettings;
  }

  setSystemSettings(settings: SystemSettings): void {
    this.cachedSystemSettings = settings;
  }

  clearSystemSettings(): void {
    this.cachedSystemSettings = null;
  }

  getDefaultSettings(): SystemSettings {
    return { ...defaultSystemSettings };
  }
}

export const inMemoryState = new InMemoryStateService();

import { logger } from '../utils/logger.js';
import webPush from 'web-push';
import { AppDataSource } from '../database.js';
import fs from 'node:fs';
import path from 'node:path';
import type { StreamManager } from '../streams/rtspManager.js';

const VAPID_KEYS_DIR = process.env.VAPID_KEYS_DIR || '/data/vapid';
const VAPID_PUB_KEY_FILE = path.join(VAPID_KEYS_DIR, 'public_key.pem');
const VAPID_PRIV_KEY_FILE = path.join(VAPID_KEYS_DIR, 'private_key.pem');
import { NotificationSubscription } from '../models/NotificationSubscription.js';
import { NotificationLog } from '../models/NotificationLog.js';
import { NotificationPreferences } from '../models/NotificationPreferences.js';
import { Event } from '../models/Event.js';

const notificationSubscriptionRepository = AppDataSource.getRepository(NotificationSubscription);
const notificationLogRepository = AppDataSource.getRepository(NotificationLog);

interface NotificationPayload {
  title: string;
  body: string;
  icon?: string;
  image?: string;
  badge?: string;
  tag?: string;
  data?: Record<string, unknown>;
}

interface PushSubscription {
  endpoint: string;
  keys: {
    p256h: string;
    auth: string;
  };
}

export class NotificationService {
  private static vapidPublicKey: string;
  private static vapidPrivateKey: string;
  private static vapidSubject: string;
  private static cameraNames: Map<string, string> = new Map();

  static loadCameraNames(streamManager: StreamManager): void {
    this.cameraNames.clear();
    const cameras = streamManager.getAllCameras();
    for (const camera of cameras) {
      this.cameraNames.set(camera.id, camera.name);
    }
    logger.info(
      `Loaded ${this.cameraNames.size} camera names for notifications`,
      'NotificationService',
    );
  }

  static getVapidPublicKey(): string | undefined {
    return this.vapidPublicKey || undefined;
  }

  static async initialize(): Promise<void> {
    this.vapidSubject = process.env.VAPID_SUBJECT || 'mailto:admin@sentryvision.local';
    this.vapidPublicKey = process.env.VAPID_PUBLIC_KEY || '';
    this.vapidPrivateKey = process.env.VAPID_PRIVATE_KEY || '';

    if (!this.vapidPublicKey || !this.vapidPrivateKey) {
      try {
        if (fs.existsSync(VAPID_PUB_KEY_FILE)) {
          this.vapidPublicKey = fs.readFileSync(VAPID_PUB_KEY_FILE, 'utf-8').trim();
          this.vapidPrivateKey = fs.readFileSync(VAPID_PRIV_KEY_FILE, 'utf-8').trim();
          logger.info('VAPID keys loaded from filesystem', 'NotificationService');
        }
      } catch (err) {
        logger.warn('Could not load VAPID keys from filesystem', 'NotificationService');
      }
    }

    if (!this.vapidPublicKey || !this.vapidPrivateKey) {
      logger.info('Generating new VAPID keys...', 'NotificationService');
      const keys = webPush.generateVAPIDKeys();
      this.vapidPublicKey = keys.publicKey;
      this.vapidPrivateKey = keys.privateKey;

      try {
        if (!fs.existsSync(VAPID_KEYS_DIR)) {
          fs.mkdirSync(VAPID_KEYS_DIR, { recursive: true });
        }
        fs.writeFileSync(VAPID_PUB_KEY_FILE, this.vapidPublicKey, 'utf-8');
        fs.writeFileSync(VAPID_PRIV_KEY_FILE, this.vapidPrivateKey, 'utf-8');
        fs.chmodSync(VAPID_PUB_KEY_FILE, 0o600);
        fs.chmodSync(VAPID_PRIV_KEY_FILE, 0o600);
        logger.info('VAPID keys persisted to filesystem', 'NotificationService');
      } catch (err) {
        logger.warn(
          'Could not persist VAPID keys to filesystem — will regenerate on next restart',
          'NotificationService',
        );
      }
    }

    webPush.setVapidDetails(this.vapidSubject, this.vapidPublicKey, this.vapidPrivateKey);

    logger.info('Notification service initialized with VAPID keys', 'NotificationService');
  }

  static generateVAPIDKeys() {
    return webPush.generateVAPIDKeys();
  }

  static async subscribe(
    userId: string,
    subscription: PushSubscription,
  ): Promise<NotificationSubscription> {
    try {
      const newSubscription = notificationSubscriptionRepository.create({
        userId,
        endpoint: subscription.endpoint,
        keysP256h: subscription.keys.p256h,
        keysAuth: subscription.keys.auth,
        isActive: true,
      });

      await notificationSubscriptionRepository.save(newSubscription);
      logger.info(`User ${userId} subscribed to notifications`, 'NotificationService');
      return newSubscription;
    } catch (error) {
      logger.error('Failed to save subscription', 'NotificationService', error);
      throw error;
    }
  }

  static async unsubscribe(userId: string, endpoint: string): Promise<void> {
    try {
      await notificationSubscriptionRepository.delete({
        userId,
        endpoint,
      });
      logger.info(`User ${userId} unsubscribed from notifications`, 'NotificationService');
    } catch (error) {
      logger.error('Failed to unsubscribe', 'NotificationService', error);
      throw error;
    }
  }

  static async getSubscription(userId: string): Promise<NotificationSubscription | null> {
    try {
      return await notificationSubscriptionRepository.findOne({
        where: { userId, isActive: true },
      });
    } catch (error) {
      logger.error('Failed to get subscription', 'NotificationService', error);
      throw error;
    }
  }

  static async sendPushNotification(
    subscription: NotificationSubscription,
    payload: NotificationPayload,
  ): Promise<boolean> {
    const pushSubscription = {
      endpoint: subscription.endpoint,
      keys: {
        p256dh: subscription.keysP256h,
        auth: subscription.keysAuth,
      },
    };

    try {
      await webPush.sendNotification(pushSubscription, JSON.stringify(payload));

      await notificationSubscriptionRepository.update(subscription.id, {
        lastUsed: new Date(),
      });

      return true;
    } catch (error: unknown) {
      const notifErr = error as { statusCode?: number };
      if (notifErr.statusCode === 410) {
        await notificationSubscriptionRepository.update(subscription.id, {
          isActive: false,
        });
        logger.info('Subscription expired, marked as inactive', 'NotificationService');
      } else {
        logger.error('Failed to send push notification', 'NotificationService', error);
      }
      return false;
    }
  }

  static async shouldNotify(userId: string, eventType: string): Promise<boolean> {
    try {
      const preferencesRepository = AppDataSource.getRepository(NotificationPreferences);
      const prefs = await preferencesRepository.findOne({ where: { userId } });

      if (!prefs) {
        return true;
      }

      if (eventType === 'motion' && !prefs.motionEnabled) return false;
      if (eventType === 'face' && !prefs.faceEnabled) return false;
      if (eventType === 'object' && !prefs.objectEnabled) return false;

      if (prefs.quietHoursEnabled) {
        const now = new Date();
        const userTimeStr = now.toLocaleTimeString('en-US', {
          timeZone: prefs.quietHoursTimezone || 'UTC',
          hour: '2-digit',
          minute: '2-digit',
          hour12: false,
        });

        const isQuietHours = this.isTimeInQuietHours(
          userTimeStr,
          prefs.quietHoursStart,
          prefs.quietHoursEnd,
        );

        if (isQuietHours) {
          logger.info(
            `Quiet hours active for user ${userId}, skipping notification`,
            'NotificationService',
          );
          return false;
        }
      }

      return true;
    } catch (error) {
      logger.error('Error checking notification preferences', 'NotificationService', error);
      return true;
    }
  }

  private static isTimeInQuietHours(
    currentTime: string,
    startTime: string,
    endTime: string,
  ): boolean {
    if (startTime < endTime) {
      return currentTime >= startTime && currentTime < endTime;
    } else {
      return currentTime >= startTime || currentTime < endTime;
    }
  }

  static async sendNotificationToUser(
    userId: string,
    payload: NotificationPayload,
    eventType: string,
    eventId?: string,
  ): Promise<void> {
    const subscriptions = await notificationSubscriptionRepository.find({
      where: { userId, isActive: true },
    });

    if (subscriptions.length === 0) {
      logger.info(`No active subscriptions found for user ${userId}`, 'NotificationService');
      return;
    }

    let successCount = 0;
    let failCount = 0;

    for (const subscription of subscriptions) {
      const success = await this.sendPushNotification(subscription, payload);

      const log = notificationLogRepository.create({
        userId,
        eventId: eventId || null,
        type: eventType,
        payload: payload as any,
        status: success ? 'success' : 'failed',
        errorMessage: success ? null : 'Failed to deliver push notification',
        retryCount: success ? 0 : 1,
      });

      await notificationLogRepository.save(log);

      if (success) {
        successCount++;
      } else {
        failCount++;
      }
    }

    logger.info(
      `Notification sent to user ${userId}: ${successCount} success, ${failCount} failed`,
      'NotificationService',
    );
  }

  static async notifyMotionEvent(event: Event): Promise<void> {
    const cameraName = event.camera_id
      ? this.cameraNames.get(event.camera_id) || event.camera_id
      : 'Unknown camera';
    const timeStr = new Date(event.timestamp).toLocaleTimeString('en-US', {
      hour: '2-digit',
      minute: '2-digit',
    });

    const payload: NotificationPayload = {
      title: 'Motion Detected',
      body: `Motion detected at ${cameraName} (${timeStr})`,
      icon: '/icon-192.png',
      image: event.file_path ? `/api/events/image/${event.file_path.split('/').pop()}` : undefined,
      badge: '/badge-72.png',
      tag: `motion-${event.camera_id}`,
      data: {
        eventId: event.id,
        cameraId: event.camera_id,
        timestamp: event.timestamp,
        type: 'motion',
      },
    };

    await this.sendNotificationToAllUsers(payload, 'motion', event.id);
  }

  static async notifyUnknownFace(event: Event): Promise<void> {
    const cameraName = event.camera_id
      ? this.cameraNames.get(event.camera_id) || event.camera_id
      : 'Unknown camera';
    const timeStr = new Date(event.timestamp).toLocaleTimeString('en-US', {
      hour: '2-digit',
      minute: '2-digit',
    });

    const payload: NotificationPayload = {
      title: 'Unknown Face Detected',
      body: `Unknown person detected at ${cameraName} (${timeStr})`,
      icon: '/icon-192.png',
      image: event.file_path ? `/api/events/image/${event.file_path.split('/').pop()}` : undefined,
      badge: '/badge-72.png',
      tag: `face-unknown-${event.camera_id}`,
      data: {
        eventId: event.id,
        cameraId: event.camera_id,
        timestamp: event.timestamp,
        type: 'face',
        status: 'unknown',
      },
    };

    await this.sendNotificationToAllUsers(payload, 'face', event.id);
  }

  static async notifyObjectDetected(event: Event, objects: string[]): Promise<void> {
    const cameraName = event.camera_id
      ? this.cameraNames.get(event.camera_id) || event.camera_id
      : 'Unknown camera';
    const timeStr = new Date(event.timestamp).toLocaleTimeString('en-US', {
      hour: '2-digit',
      minute: '2-digit',
    });

    const payload: NotificationPayload = {
      title: `${objects[0]?.charAt(0).toUpperCase() + objects[0]?.slice(1)} Detected`,
      body: `${objects.join(', ')} detected at ${cameraName} (${timeStr})`,
      icon: '/icon-192.png',
      image: event.file_path ? `/api/events/image/${event.file_path.split('/').pop()}` : undefined,
      badge: '/badge-72.png',
      tag: `object-${objects[0]}-${event.camera_id}`,
      data: {
        eventId: event.id,
        cameraId: event.camera_id,
        timestamp: event.timestamp,
        type: 'object',
        objects,
      },
    };

    await this.sendNotificationToAllUsers(payload, 'object', event.id);
  }

  static async notifySystemAlert(title: string, message: string): Promise<void> {
    const payload: NotificationPayload = {
      title,
      body: message,
      icon: '/icon-192.png',
      badge: '/badge-72.png',
      tag: `system-${Date.now()}`,
      data: {
        type: 'system',
        timestamp: new Date().toISOString(),
      },
    };

    await this.sendNotificationToAllUsers(payload, 'system');
  }

  private static async sendNotificationToAllUsers(
    payload: NotificationPayload,
    eventType: string,
    eventId?: string,
  ): Promise<void> {
    const { User } = await import('../models/index.js');
    const userRepository = AppDataSource.getRepository(User);

    const users = await userRepository.find();

    for (const user of users) {
      const shouldNotify = await this.shouldNotify(user.id, eventType);
      if (shouldNotify) {
        await this.sendNotificationToUser(user.id, payload, eventType, eventId);
      } else {
        logger.info(
          `Notification for ${eventType} suppressed for user ${user.id} due to preferences`,
          'NotificationService',
        );
      }
    }
  }

  static async cleanupExpiredSubscriptions(): Promise<number> {
    const thirtyDaysAgo = new Date();
    thirtyDaysAgo.setDate(thirtyDaysAgo.getDate() - 30);

    const result = await notificationSubscriptionRepository
      .createQueryBuilder()
      .delete()
      .where('last_used < :date', { date: thirtyDaysAgo })
      .orWhere('is_active = :isActive', { isActive: false })
      .execute();

    logger.info(`Cleaned up ${result.affected || 0} expired subscriptions`, 'NotificationService');
    return result.affected || 0;
  }

  static async getNotificationLogs(userId: string, limit: number = 50): Promise<NotificationLog[]> {
    return await notificationLogRepository.find({
      where: { userId },
      order: { sentAt: 'DESC' },
      take: limit,
    });
  }
}

export default NotificationService;

