      context.eventType ? `Event Type: ${context.eventType}` : null,
    ]
      .filter(Boolean)
      .join(' | ');

    const userMessage = contextInfo
      ? `Context: ${contextInfo}\n\nRespond with only valid JSON: {`
      : 'Respond with only valid JSON: {';

    const requestBody = {
      model: model,
      messages: [
        {
          role: 'system',
          content: PERSON_SYSTEM_PROMPT,
        },
        {
          role: 'user',
          content: [
            { type: 'text', text: userMessage },
            {
              type: 'image_url',
              image_url: { url: `data:image/jpeg;base64,${base64Image}` },
            },
          ],
        },
      ],
      temperature: 0.0,
      max_tokens: 4096,
      stream: false,
      top_p: 0.9,
    };

    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), timeout);

    const apiKey = process.env.NVIDIA_API_KEY;
    if (!apiKey) {
      throw new Error('NVIDIA_API_KEY not configured');
    }
    const baseUrl = process.env.NVIDIA_API_BASE_URL || 'https://integrate.api.nvidia.com/v1';

    const response = await fetch(`${baseUrl}/chat/completions`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        Authorization: `Bearer ${apiKey}`,
      },
      body: JSON.stringify(requestBody),
      signal: controller.signal,
    });

    clearTimeout(timeoutId);

    if (!response.ok) {
      throw new Error(`NVIDIA API error: ${response.status}`);
    }

    const apiResponse = await response.json();
    const personMessage = apiResponse.choices?.[0]?.message;
    const content =
      personMessage?.content || personMessage?.reasoning_content || personMessage?.reasoning || '';
    const processingTime = Date.now() - startTime;

    let people: PersonDetectionResult['people'] = [];
    let count = 0;
    let sceneDescription = '';
    let sceneContext: PersonDetectionResult['sceneContext'] = undefined;

    try {
      let jsonStr = content.trim();
      if (jsonStr.startsWith('```json')) jsonStr = jsonStr.slice(7);
      else if (jsonStr.startsWith('```')) jsonStr = jsonStr.slice(3);
      if (jsonStr.endsWith('```')) jsonStr = jsonStr.slice(0, -3);

      const parsed = JSON.parse(jsonStr.trim());

      count = parsed.count || 0;
      sceneDescription = parsed.scene_description || '';
      sceneContext = parsed.scene_context;

      if (parsed.people && Array.isArray(parsed.people)) {
        people = parsed.people.map((p: any) => ({
          position: {
            x: p.position?.x || 0,
            y: p.position?.y || 0,
            width: p.position?.width || 0,
            height: p.position?.height || 0,
            label: 'person',
            confidence: 80,
          },
          description: p.description || '',
          clothing: p.clothing || '',
          actions: p.actions || [],
        }));
      }
    } catch (parseError) {
      logger.error('Failed to parse person response', 'NVIDIA', parseError);
      sceneDescription = content.substring(0, 500);
    }

    return {
      count,
      people,
      sceneDescription,
      sceneContext,
      processingTime,
      modelUsed: model,
    };
  } catch (error: unknown) {
    const errMsg = error instanceof Error ? error.message : String(error);
    logger.error('Person detection error: ' + errMsg, 'NVIDIA');
    const processingTime = Date.now() - startTime;

    return {
      count: 0,
      people: [],
      sceneDescription: `Analysis failed: ${errMsg}`,
      sceneContext: undefined,
      processingTime,
      modelUsed: model,
    };
  }
}

import path from 'node:path';
import fs from 'node:fs';
import { logger } from '../../utils/logger.js';
import type { AnalysisContext, NormalizedDetection } from './types.js';

export function normalizeEntityArray(input: unknown, type: string): string[] {
  if (!input) return [];
  if (Array.isArray(input)) {
    return input.map((item) => {
      if (typeof item === 'string') return item;
      if (typeof item === 'object' && item !== null) {
        const obj = item as Record<string, unknown>;
        const parts: string[] = [];
        if (obj.description) parts.push(String(obj.description));
        if (obj.count !== undefined) parts.push(`count:${obj.count}`);
        if (obj.type) parts.push(String(obj.type));
        if (obj.color) parts.push(String(obj.color));
        if (obj.location) parts.push(String(obj.location));
        if (obj.state || obj.behavior) parts.push(String(obj.state || obj.behavior));
        if (obj.clothing) parts.push(String(obj.clothing));
        if (obj.significance) parts.push(String(obj.significance));
        return parts.length > 0 ? parts.join(' | ') : type;
      }
      return String(item);
    });
  }
  return [];
}

export function imageToBase64(imagePath: string): string {
  const absolutePath = path.isAbsolute(imagePath) ? imagePath : path.join(process.cwd(), imagePath);

  const imageBuffer = fs.readFileSync(absolutePath);
  return imageBuffer.toString('base64');
}

export async function callNvidiaApi(
  base64Image: string,
  context: AnalysisContext,
  model: string,
  systemPrompt: string,
): Promise<any> {
  const apiKey = process.env.NVIDIA_API_KEY;
  const baseUrl = process.env.NVIDIA_API_BASE_URL || 'https://integrate.api.nvidia.com/v1';

  if (!apiKey) {
    throw new Error('NVIDIA_API_KEY environment variable is not set');
  }

  const yoloInfo = context.yoloDetections?.length
    ? `YOLO Detections: ${context.yoloDetections.map((d) => `${d.class} (${Math.round(d.confidence * 100)}%) @ [${d.bbox.x.toFixed(2)},${d.bbox.y.toFixed(2)},${d.bbox.width.toFixed(2)},${d.bbox.height.toFixed(2)}]`).join('; ')}`
    : null;

  const contextInfo = [
    context.cameraName ? `Camera: ${context.cameraName}` : null,
    context.triggerReason ? `Trigger: ${context.triggerReason}` : null,
    context.eventType ? `Event Type: ${context.eventType}` : null,
    context.detectedObjects?.length
      ? `Detected Objects: ${context.detectedObjects.join(', ')}`
      : null,
    yoloInfo,
    context.timestamp ? `Timestamp: ${context.timestamp}` : null,
  ]
    .filter(Boolean)
    .join(' | ');

  const userMessage = contextInfo
    ? `Context: ${contextInfo}\n\nAnalyze this image and compare with YOLO detections above. Note any discrepancies. Respond with only valid JSON: {`
    : 'Analyze this image. Respond with only valid JSON: {';

  const requestBody = {
    model: model,
    messages: [
      {
        role: 'system',
        content: systemPrompt,
      },
      {
        role: 'user',
        content: [
          {
            type: 'text',
            text: userMessage,
          },
          {
            type: 'image_url',
            image_url: {
              url: `data:image/jpeg;base64,${base64Image}`,
            },
          },
        ],
      },
    ],
    temperature: 0.0,
    max_tokens: 4096,
    stream: false,
    top_p: 0.9,
  };

  let lastError: Error | null = null;
  for (let attempt = 1; attempt <= 3; attempt++) {
    try {
      const response = await fetch(`${baseUrl}/chat/completions`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${apiKey}`,
        },
        body: JSON.stringify(requestBody),
      });

      if (!response.ok) {
        const errorData = await response.json().catch(() => ({}));
        throw new Error(
          `NVIDIA API error: ${response.status} - ${errorData.message || response.statusText}`,
        );
      }

      return await response.json();
    } catch (err: unknown) {
      lastError = err instanceof Error ? err : new Error(String(err));
      if (attempt < 3) {
        const delay = Math.min(1000 * Math.pow(2, attempt - 1) + Math.random() * 500, 5000);
        await new Promise((resolve) => setTimeout(resolve, delay));
      }
    }
  }

  throw lastError || new Error('NVIDIA API call failed after 3 retries');
}

import sharp from 'sharp';
import { logger } from '../../utils/logger.js';
import { normalizeEntityArray } from './nvidiaClient.js';
import type { NvidianalysisResult, BoundingBox } from './types.js';

function buildResult(parsed: any, processingTime: number, model: string): NvidianalysisResult {
  let p = parsed;
  const topDesc = p.scene_description || p.sceneDescription || '';
  if (typeof topDesc === 'string' && topDesc.trim().startsWith('{')) {
    try {
      const inner = JSON.parse(topDesc);
      if (inner && typeof inner === 'object') {
        p = inner;
      }
    } catch {}
  }

  return {
    sceneDescription: p.scene_description || p.sceneDescription || 'No description available',
    sceneContext: p.scene_context || p.sceneContext || { environment: 'unknown' },
    threatAssessment: {
      level: p.threat_assessment?.level || p.threatAssessment?.level || 'low',
      factors: p.threat_assessment?.reasoning
        ? [p.threat_assessment.reasoning]
        : p.threat_assessment?.factors || p.threatAssessment?.factors || [],
      confidence: p.threat_assessment?.confidence || p.threatAssessment?.confidence || 50,
    },
    detectedEntities: {
      people: normalizeEntityArray(
        p.detected_entities?.people || p.detectedEntities?.people,
        'person',
      ),
      vehicles: normalizeEntityArray(
        p.detected_entities?.vehicles || p.detectedEntities?.vehicles,
        'vehicle',
      ),
      animals: normalizeEntityArray(
        p.detected_entities?.animals || p.detectedEntities?.animals,
        'animal',
      ),
      objects: normalizeEntityArray(
        p.detected_entities?.objects || p.detectedEntities?.objects,
        'object',
      ),
      actions: normalizeEntityArray(
        p.detected_entities?.actions || p.detectedEntities?.actions,
        'action',
      ),
    },
    recommendedActions: p.recommended_actions || p.recommendedActions || [],
    additionalObservations: p.additional_observations || p.additionalObservations || [],
    processingTime,
    modelUsed: model,
  };
}

export function parseAIResponse(
  responseContent: string,
  processingTime: number,
  model: string,
): NvidianalysisResult {
  const tryParse = (str: string): any | null => {
    try {
      return JSON.parse(str);
    } catch {
      return null;
    }
  };

  try {
    let jsonStr = responseContent.trim();

    if (jsonStr.startsWith('{')) {
      const jsonEnd = jsonStr.lastIndexOf('}');
      if (jsonEnd > 0) {
        const parsed = tryParse(jsonStr.substring(0, jsonEnd + 1));
        if (parsed) return buildResult(parsed, processingTime, model);
      }
    }

    const codeBlockMatch = jsonStr.match(/```(?:json)?\s*([\s\S]*?)```/);
    if (codeBlockMatch) {
      const extracted = codeBlockMatch[1].trim();
      let parsed = tryParse(extracted);
      if (parsed) return buildResult(parsed, processingTime, model);
      const clean = extracted.replace(/^[^{]*/, '').replace(/[^}]*$/, '');
      if (clean.trim().startsWith('{')) {
        parsed = tryParse(clean);
        if (parsed) return buildResult(parsed, processingTime, model);
      }
    }

    const jsonStart = jsonStr.indexOf('{');
    if (jsonStart >= 0) {
      const jsonEnd = jsonStr.lastIndexOf('}');
      if (jsonEnd > jsonStart) {
        const extracted = jsonStr.substring(jsonStart, jsonEnd + 1);
        let parsed = tryParse(extracted);
        if (parsed) return buildResult(parsed, processingTime, model);
      }
    }

    const cleaned = jsonStr
      .replace(/\*\*(.*?)\*\*/g, '$1')
      .replace(/#/g, '')
      .replace(/^[-*+]\s+/gm, '')
      .replace(/\n\s*\n/g, '\n')
      .trim();
    const s = cleaned.indexOf('{');
    const e = cleaned.lastIndexOf('}');
    if (s >= 0 && e > s) {
      const parsed = tryParse(cleaned.substring(s, e + 1));
      if (parsed) return buildResult(parsed, processingTime, model);
    }

    if (jsonStr.length > 10) {
      return {
        sceneDescription: jsonStr.replace(/^["'\s]+|["'\s]+$/g, '').substring(0, 500),
        threatAssessment: { level: 'low', factors: [], confidence: 30 },
        detectedEntities: { people: [], vehicles: [], animals: [], objects: [], actions: [] },
        recommendedActions: [],
        additionalObservations: ['Raw text used as description (JSON parsing failed)'],
        processingTime,
        modelUsed: model,
      };
    }

    throw new Error('Failed to parse JSON from response');
  } catch (parseError: unknown) {
    const errMsg = parseError instanceof Error ? parseError.message : String(parseError);
    logger.error('All JSON parse strategies failed: ' + errMsg, 'NVIDIA');

    if (responseContent.trim().length > 10) {
      return {
        sceneDescription: responseContent.trim().substring(0, 500),
        threatAssessment: { level: 'low', factors: [], confidence: 30 },
        detectedEntities: { people: [], vehicles: [], animals: [], objects: [], actions: [] },
        recommendedActions: [],
        additionalObservations: ['Raw text used as description (JSON parsing failed)'],
        processingTime,
        modelUsed: model,
      };
    }

    return {
      sceneDescription: 'No description available',
      threatAssessment: { level: 'low', factors: [], confidence: 30 },
      detectedEntities: { people: [], vehicles: [], animals: [], objects: [], actions: [] },
      recommendedActions: [],
      additionalObservations: ['Response parsing encountered issues'],
      processingTime,
      modelUsed: model,
    };
  }
}

export { buildResult };

export async function drawBoundingBoxes(imagePath: string, boxes: BoundingBox[]): Promise<string> {
  try {
    const metadata = await sharp(imagePath).metadata();
    const width = metadata.width || 1920;
    const height = metadata.height || 1080;

    const boxElements = boxes
      .map((box) => {
        const x = (box.x / 100) * width;
        const y = (box.y / 100) * height;
        const w = (box.width / 100) * width;
        const h = (box.height / 100) * height;

        let strokeColor = '#FF0000';
        if (box.label.toLowerCase().includes('person')) {
          strokeColor = '#00FF00';
        } else if (
          box.label.toLowerCase().includes('vehicle') ||
          box.label.toLowerCase().includes('car')
        ) {
          strokeColor = '#00FFFF';
        } else if (
          box.label.toLowerCase().includes('animal') ||
          box.label.toLowerCase().includes('dog') ||
          box.label.toLowerCase().includes('cat')
        ) {
          strokeColor = '#FF00FF';
        }

        return `
        <rect 
          x="${x}" y="${y}" 
          width="${w}" height="${h}" 
          fill="none" 
          stroke="${strokeColor}" 
          stroke-width="3"
          rx="5"
        />
        <rect 
          x="${x}" y="${Math.max(0, y - 25)}" 
          width="${Math.min(w, 150)}" height="25" 
          fill="${strokeColor}"
        />
        <text 
          x="${x + 5}" y="${Math.max(0, y - 7)}" 
          fill="white" 
          font-family="Arial" 
          font-size="14"
          font-weight="bold"
        >${box.label} (${Math.round(box.confidence)}%)</text>
      `;
      })
      .join('');

    const svg = `
      <svg width="${width}" height="${height}" xmlns="http://www.w3.org/2000/svg">
        ${boxElements}
      </svg>
    `;

    const annotatedBuffer = await sharp(imagePath)
      .composite([
        {
          input: Buffer.from(svg),
          top: 0,
          left: 0,
        },
      ])
      .jpeg({ quality: 90 })
      .toBuffer();

    return annotatedBuffer.toString('base64');
  } catch (error: unknown) {
    logger.error('Error drawing bounding boxes', 'NVIDIA', error);
    const originalBuffer = await sharp(imagePath).jpeg().toBuffer();
    return originalBuffer.toString('base64');
  }
}

import { logger } from '../utils/logger.js';
import axios, { AxiosInstance } from 'axios';
import fs from 'node:fs';
import crypto from 'node:crypto';
import { CircuitBreaker } from './circuitBreaker.js';

// Types for OpenCV microservice communication
export interface DetectionResult {
  success: boolean;
  cached: boolean;
  detections?: Array<{
    class: string;
    confidence: number;
    bbox: { x: number; y: number; width: number; height: number };
  }>;
  faceDetections?: Array<{
    id: string;
    name: string;
    confidence: number;
    bbox: { x: number; y: number; width: number; height: number };
  }>;
  processingTime?: number;
  fileHash: string;
  error?: string;
}

export interface OpenCVServiceStatus {
  status: 'ready' | 'initializing' | 'error';
  initialized: boolean;
  service: string;
}

export class OpenCVMicroserviceClient {
  private client: AxiosInstance;
  private serviceUrl: string;
  private isHealthy: boolean = false;
  private lastHealthCheck: number = 0;
  private healthCheckInterval: number = 30000; // 30 seconds
  private breaker: CircuitBreaker;

  constructor(serviceUrl?: string) {
    this.serviceUrl = serviceUrl || process.env.OPENCV_SERVICE_URL || 'http://localhost:8084';

    this.client = axios.create({
      baseURL: this.serviceUrl,
      timeout: 30000, // 30 second timeout
      headers: {
        'Content-Type': 'application/json',
        ...(process.env.OPENCV_API_TOKEN ? { 'X-API-Token': process.env.OPENCV_API_TOKEN } : {}),
      },
    });

    this.breaker = new CircuitBreaker('OpenCVService', {
      failureThreshold: 5,
      cooldownMs: 30000,
      successThreshold: 2,
    });

    // Request interceptor for logging
    this.client.interceptors.request.use(
      (config) => {
        logger.info(
          `OpenCV Microservice: ${config.method?.toUpperCase()} ${config.url}`,
          'OpenCVClient',
        );
        return config;
      },
      (error) => {
        logger.error('OpenCV Microservice: Request error', 'OpenCVClient', error);
        return Promise.reject(error);
      },
    );

    // Response interceptor for logging
    this.client.interceptors.response.use(
      (response) => {
        logger.info(
          `OpenCV Microservice: Response ${response.status} from ${response.config.url}`,
          'OpenCVClient',
        );
        return response;
      },
      (error) => {
        logger.error(`OpenCV Microservice: Response error: ${error.message}`, 'OpenCVClient');
        return Promise.reject(error);
      },
    );
  }

  /**
   * Check if the OpenCV microservice is healthy and ready
   */
  async checkHealth(): Promise<boolean> {
    try {
      const now = Date.now();

      // Cache health check results for a short period
      if (this.isHealthy && now - this.lastHealthCheck < this.healthCheckInterval) {
        return true;
      }

      const response = await this.breaker.execute(() => this.client.get('/health'));
      const isHealthy = response.status === 200 && response.data?.status === 'healthy';

      if (isHealthy) {
        this.isHealthy = true;
        this.lastHealthCheck = now;
        logger.info('OpenCV Microservice: Health check passed', 'OpenCVClient');
      } else {
        this.isHealthy = false;
        logger.warn(
          'OpenCV Microservice: Health check failed - service not healthy',
          'OpenCVClient',
        );
      }

      return isHealthy;
    } catch (error) {
      this.isHealthy = false;
      logger.error('OpenCV Microservice: Health check failed', 'OpenCVClient', error);
      return false;
    }
  }

  /**
   * Get detailed status of the OpenCV service
   */
  async getStatus(): Promise<OpenCVServiceStatus | null> {
    try {
      const response = await this.client.get('/status');
      return response.data;
    } catch (error) {
      logger.error('OpenCV Microservice: Failed to get status', 'OpenCVClient', error);
      return null;
    }
  }

  /**
   * Detect objects in an image using the OpenCV microservice
   */
  async detectObjects(imagePath: string): Promise<DetectionResult> {
    try {
      if (!fs.existsSync(imagePath)) {
        throw new Error(`Image file not found: ${imagePath}`);
      }

      const imageBuffer = await fs.promises.readFile(imagePath);
      const stats = fs.statSync(imagePath);
      const fileHash = this.generateFileHash(imagePath, stats);

      logger.info(`OpenCV Microservice: Detecting objects in ${imagePath}`, 'OpenCVClient');

      const response = await this.breaker.execute(() =>
        this.client.post('/detect-objects', imageBuffer, {
          headers: { 'Content-Type': 'image/jpeg' },
          params: { fileHash, fileSize: stats.size },
        }),
      );
      return { ...response.data, fileHash };
    } catch (error) {
      logger.error(
        `OpenCV Microservice: Object detection failed for ${imagePath}`,
        'OpenCVClient',
        error,
      );

      if (axios.isAxiosError(error)) {
        throw new Error(`OpenCV service error: ${error.response?.data?.error || error.message}`);
      }

      throw error;
    }
  }

  /**
   * Recognize faces in an image using the OpenCV microservice
   */
  async recognizeFaces(imagePath: string): Promise<DetectionResult> {
    try {
      if (!fs.existsSync(imagePath)) {
        throw new Error(`Image file not found: ${imagePath}`);
      }

      const imageBuffer = await fs.promises.readFile(imagePath);
      const stats = fs.statSync(imagePath);
      const fileHash = this.generateFileHash(imagePath, stats);

      logger.info(`OpenCV Microservice: Recognizing faces in ${imagePath}`, 'OpenCVClient');

      const response = await this.breaker.execute(() =>
        this.client.post('/recognize-faces', imageBuffer, {
          headers: { 'Content-Type': 'image/jpeg' },
          params: { fileHash, fileSize: stats.size },
        }),
      );
      return { ...response.data, fileHash };
    } catch (error) {
      logger.error(
        `OpenCV Microservice: Face recognition failed for ${imagePath}`,
        'OpenCVClient',
        error,
      );

      if (axios.isAxiosError(error)) {
        throw new Error(`OpenCV service error: ${error.response?.data?.error || error.message}`);
      }

      throw error;
    }
  }

  async pushDetectionConfig(cameraId: string, config: Record<string, unknown>): Promise<boolean> {
    try {
      const response = await this.breaker.execute(() =>
        this.client.post(
          '/api/config',
          {
            camera_id: cameraId,
            settings: config,
          },
          {
            timeout: 5000,
          },
        ),
      );
      return response.status === 200;
    } catch (error) {
      logger.error(`Failed to push detection config to Python service: ${error}`, 'OpenCVClient');
      return false;
    }
  }

  /**
   * Generate a hash for file identification and caching
   */
  private generateFileHash(imagePath: string, stats: fs.Stats): string {
    const hash = crypto.createHash('md5');

    // Include file path, size, and modification time in hash
    hash.update(imagePath);
    hash.update(stats.size.toString());
    hash.update(stats.mtime.toISOString());

    return hash.digest('hex');
  }

  /**
   * Wait for service to be ready (with timeout)
   */
  async waitForReady(timeoutMs: number = 120000): Promise<boolean> {
    const startTime = Date.now();
    const checkInterval = 2000; // Check every 2 seconds

    logger.info(
      `OpenCV Microservice: Waiting for service to be ready (timeout: ${timeoutMs}ms)`,
      'OpenCVClient',
    );

    while (Date.now() - startTime < timeoutMs) {
      try {
        const isHealthy = await this.checkHealth();
        const status = await this.getStatus();

        // Consider service ready if it's healthy, even if not fully initialized
        // This allows mock detection to work while real OpenCV initialization continues
        if (isHealthy && status && status.status === 'ready') {
          logger.info('OpenCV Microservice: Service is ready and healthy', 'OpenCVClient');
          this.isHealthy = true;
          this.lastHealthCheck = Date.now();
          return true;
        }

        logger.info(
          `OpenCV Microservice: Service status: ${status?.status || 'unknown'}, healthy: ${isHealthy}, waiting...`,
          'OpenCVClient',
        );
      } catch (error) {
        logger.info('OpenCV Microservice: Service not ready yet, waiting...', 'OpenCVClient');
      }

      await new Promise((resolve) => setTimeout(resolve, checkInterval));
    }

    logger.error('OpenCV Microservice: Timeout waiting for service to be ready', 'OpenCVClient');
    return false;
  }

  /**
   * Get the service URL
   */
  getServiceUrl(): string {
    return this.serviceUrl;
  }

  /**
   * Check if the client is currently healthy
   */
  isServiceHealthy(): boolean {
    return this.isHealthy;
  }

  /**
   * Get circuit breaker state
   */
  getBreakerState(): string {
    return this.breaker.getState();
  }
}

// Singleton instance for the application
let openCVClient: OpenCVMicroserviceClient | null = null;

export function getOpenCVClient(): OpenCVMicroserviceClient {
  if (!openCVClient) {
    openCVClient = new OpenCVMicroserviceClient();
  }
  return openCVClient;
}

export function resetOpenCVClient(): void {
  openCVClient = null;
}

export default OpenCVMicroserviceClient;

import { describe, it, expect, jest, beforeEach, afterEach } from '@jest/globals';
import { PythonWsClient } from './pythonWsClient.js';
import WebSocket from 'ws';
import { WebSocketServer } from 'ws';
import type { AddressInfo } from 'node:net';

/**
 * Helper: create a WebSocketServer on a random port and resolve with the port.
 */
function createMockServer(): Promise<{ server: WebSocketServer; port: number }> {
  return new Promise((resolve) => {
    const server = new WebSocketServer({ port: 0, host: '127.0.0.1' });
    server.on('listening', () => {
      const address = server.address() as AddressInfo;
      resolve({ server, port: address.port });
    });
  });
}

describe('PythonWsClient', () => {
  let client: PythonWsClient;
  let mockServer: WebSocketServer;
  let port: number;

  beforeEach(async () => {
    const created = await createMockServer();
    mockServer = created.server;
    port = created.port;
    client = new PythonWsClient(`ws://127.0.0.1:${port}`);
  });

  afterEach(() => {
    client.disconnect();
    mockServer.close();
  });

  it('should connect to WebSocket server and emit connected', (done) => {
    mockServer.on('connection', () => {
      // Server received connection
    });

    client.on('connected', () => {
      expect(client.connected).toBe(true);
      done();
    });

    client.connect();
  });

  it('should emit frame on binary message', (done) => {
    const testBuffer = Buffer.from([0x01, 0x02, 0x03, 0x04]);

    client.on('connected', () => {
      // Small delay to ensure connection is fully established
      setTimeout(() => {
        const clients = [...mockServer.clients];
        const serverWs = clients[0];
        // The client expects a JSON frame metadata message before the binary payload
        serverWs.send(JSON.stringify({ type: 'frame', cameraId: null, timestamp: Date.now() }));
        serverWs.send(testBuffer);
      }, 50);
    });

    client.on('frame', (message: { cameraId: string | null; data: Buffer; timestamp: number }) => {
      expect(message.data).toEqual(testBuffer);
      expect(message.cameraId).toBeNull();
      expect(typeof message.timestamp).toBe('number');
      done();
    });

    client.connect();
  });

  it('should emit disconnected on server close', (done) => {
    client.on('connected', () => {
      // Close the server-side WebSocket to trigger client disconnect
      const clients = [...mockServer.clients];
      clients[0].close();
    });

    client.on('disconnected', () => {
      expect(client.connected).toBe(false);
      done();
    });

    client.connect();
  });

  it('should reconnect with exponential backoff', (done) => {
    const initialDelay = 1000;

    // After first disconnect, reconnectDelay should double
    client.on('connected', () => {
      // Close the server-side WebSocket to trigger client reconnection
      const clients = [...mockServer.clients];
      clients[0].close();
    });

    client.on('disconnected', () => {
      // After disconnect, reconnectDelay should have doubled
      const delay = (client as any).reconnectDelay as number;
      expect(delay).toBe(initialDelay * 2);
      done();
    });

    client.connect();
  });

  it('should send subscribe message as JSON', (done) => {
    mockServer.on('connection', (serverWs) => {
      serverWs.on('message', (data: Buffer) => {
        const message = JSON.parse(data.toString());
        expect(message).toEqual({ type: 'subscribe', cameraId: 'cam1' });
        done();
      });
    });

    client.on('connected', () => {
      client.subscribe('cam1');
    });

    client.connect();
  });

  it('should send unsubscribe message as JSON', (done) => {
    mockServer.on('connection', (serverWs) => {
      serverWs.on('message', (data: Buffer) => {
        const message = JSON.parse(data.toString());
        expect(message).toEqual({ type: 'unsubscribe', cameraId: 'cam1' });
        done();
      });
    });

    client.on('connected', () => {
      client.unsubscribe('cam1');
    });

    client.connect();
  });

  it('should disconnect cleanly without pending timers', () => {
    jest.useFakeTimers();

    client.connect();
    client.disconnect();

    expect((client as any).reconnectTimer).toBeNull();
    expect((client as any).ws).toBeNull();
    expect(client.connected).toBe(false);

    jest.useRealTimers();
  });
});

import { logger } from '../utils/logger.js';
import WebSocket from 'ws';
import { EventEmitter } from 'node:events';

interface FrameMetadata {
  cameraId: string | null;
  timestamp: number;
}

interface FrameMessage {
  cameraId: string | null;
  data: Buffer;
  timestamp: number;
}

export interface TrackingEvent {
  trackId: number;
  cameraId: string;
  timestamp: number;
  event: 'track_started' | 'track_updated' | 'track_ended';
  bbox: number[];
  score: number;
  class: string;
  classId: number;
  trackState?: string;
  trackletLen?: number;
  identity?: string | null;
  identityConfidence?: number;
}

interface SubscriptionMessage {
  type: 'subscribe' | 'unsubscribe';
  cameraId: string;
}

export class PythonWsClient extends EventEmitter {
  private ws: WebSocket | null = null;
  private reconnectDelay = 1000;
  private readonly maxReconnectDelay = 30000;
  private reconnectTimer: ReturnType<typeof setTimeout> | null = null;
  private connectTimeout: ReturnType<typeof setTimeout> | null = null;
  private silenceTimer: ReturnType<typeof setInterval> | null = null;
  private lastDataAt = 0;
  private readonly CONNECT_TIMEOUT_MS = 10000;
  private readonly SILENCE_CHECK_MS = 30000;
  private readonly SILENCE_TIMEOUT_MS = 60000;
  private url: string;
  private _connected = false;
  private pendingMetadata: FrameMetadata | null = null;
  private retryCount = 0;
  private readonly maxRetries = 50;
  private isDead = false;

  constructor(url?: string) {
    super();
    this.url = url || 'ws://localhost:9090';
  }

  get connected(): boolean {
    return this._connected;
  }

  connect(): void {
    if (this.isDead) {
      logger.warn(
        '[PythonWsClient] Client is dead (max retries exceeded), skipping connect',
        'PythonWsClient',
      );
      return;
    }
    if (this.ws?.readyState === WebSocket.OPEN || this.ws?.readyState === WebSocket.CONNECTING) {
      logger.info('[PythonWsClient] Already connected or connecting, skipping', 'PythonWsClient');
      return;
    }

    this.ws = new WebSocket(this.url);

    this.connectTimeout = setTimeout(() => {
      if (this.ws?.readyState === WebSocket.CONNECTING) {
        logger.warn('[PythonWsClient] Connection timeout, terminating', 'PythonWsClient');
        this.ws.terminate();
      }
    }, this.CONNECT_TIMEOUT_MS);

    this.ws.on('open', () => {
      if (this.connectTimeout) {
        clearTimeout(this.connectTimeout);
        this.connectTimeout = null;
      }
      logger.info('[PythonWsClient] Connected', 'PythonWsClient');
      this.reconnectDelay = 1000;
      this.retryCount = 0;
      this._connected = true;
      this.lastDataAt = Date.now();
      this.startSilenceMonitor();
      this.emit('connected');
    });

    this.ws.on('message', (data: WebSocket.Data, isBinary: boolean) => {
      this.lastDataAt = Date.now();
      if (isBinary) {
        const metadata = this.pendingMetadata;
        this.pendingMetadata = null;
        if (!metadata) {
          return;
        }
        const message: FrameMessage = {
          cameraId: metadata.cameraId,
          data: data as Buffer,
          timestamp: metadata.timestamp,
        };
        this.emit('frame', message);
      } else {
        try {
          const parsed = JSON.parse(data.toString());
          if (parsed.type === 'frame') {
            this.pendingMetadata = {
              cameraId: parsed.cameraId || null,
              timestamp: parsed.timestamp || Date.now(),
            };
          } else if (parsed.type === 'event') {
            this.emit('trackingEvent', {
              trackId: parsed.trackId ?? parsed.track_id,
              cameraId: parsed.cameraId,
              timestamp: parsed.timestamp,
              event: parsed.eventType ?? parsed.event,
              bbox: parsed.bbox ?? [],
              score: parsed.score ?? parsed.confidence ?? 0,
              class: parsed.class ?? '',
              classId: parsed.classId ?? parsed.class_id ?? 0,
              trackState: parsed.trackState ?? parsed.track_state,
              trackletLen: parsed.trackletLen ?? parsed.tracklet_len,
              identity: parsed.identity ?? null,
              identityConfidence: parsed.identityConfidence ?? parsed.identity_confidence ?? 0,
            } as TrackingEvent);
          }
        } catch {
          // ignore malformed messages
        }
      }
    });

    this.ws.on('ping', () => {
      this.lastDataAt = Date.now();
    });

    this.ws.on('close', () => {
      this.stopSilenceMonitor();
      if (this.connectTimeout) {
        clearTimeout(this.connectTimeout);
        this.connectTimeout = null;
      }
      this._connected = false;
      this.retryCount++;
      if (this.retryCount > this.maxRetries) {
        this.isDead = true;
        logger.error(
          `[PythonWsClient] Max reconnect retries (${this.maxRetries}) exceeded. Marking client as dead.`,
          'PythonWsClient',
        );
        this.emit('websocket:dead', { retries: this.retryCount });
        return;
      }
      this.reconnectTimer = setTimeout(() => {
        this.connect();
      }, this.reconnectDelay);
      this.reconnectDelay = Math.min(this.reconnectDelay * 2, this.maxReconnectDelay);
      this.emit('disconnected');
    });

    this.ws.on('error', (err: Error) => {
      logger.error(`[PythonWsClient] Error: ${err.message}`, 'PythonWsClient', err);
      if (this.ws) {
        this.ws.terminate();
      }
    });
  }

  private startSilenceMonitor(): void {
    this.stopSilenceMonitor();
    this.silenceTimer = setInterval(() => {
      if (this.ws?.readyState !== WebSocket.OPEN) return;
      const elapsed = Date.now() - this.lastDataAt;
      if (elapsed > this.SILENCE_TIMEOUT_MS) {
        logger.warn(
          `[PythonWsClient] No data from Python for ${elapsed}ms, terminating connection`,
          'PythonWsClient',
        );
        this.ws.terminate();
      }
    }, this.SILENCE_CHECK_MS);
  }

  private stopSilenceMonitor(): void {
    if (this.silenceTimer) {
      clearInterval(this.silenceTimer);
      this.silenceTimer = null;
    }
  }

  send(data: any): void {
    if (this.ws?.readyState === WebSocket.OPEN) {
      this.ws.send(data);
    }
  }

  subscribe(cameraId: string): void {
    if (this.ws?.readyState === WebSocket.OPEN) {
      const msg: SubscriptionMessage = { type: 'subscribe', cameraId };
      this.ws.send(JSON.stringify(msg));
    }
  }

  unsubscribe(cameraId: string): void {
    if (this.ws?.readyState === WebSocket.OPEN) {
      const msg: SubscriptionMessage = { type: 'unsubscribe', cameraId };
      this.ws.send(JSON.stringify(msg));
    }
  }

  disconnect(): void {
    this.stopSilenceMonitor();
    if (this.connectTimeout) {
      clearTimeout(this.connectTimeout);
      this.connectTimeout = null;
    }
    if (this.reconnectTimer) {
      clearTimeout(this.reconnectTimer);
      this.reconnectTimer = null;
    }
    if (this.ws) {
      this.ws.removeAllListeners();
      this.ws.close();
      this.ws = null;
    }
    this._connected = false;
    this.retryCount = 0;
    this.isDead = false;
  }
}

import { logger } from '../utils/logger.js';
import { AppDataSource } from '../database.js';
import { RetentionPolicy } from '../models/RetentionPolicy.js';
import { promises as fs } from 'fs';
import path from 'path';
import { EventEmitter } from 'events';

interface RetentionConfig {
  camera?: string;
  alertsDays: number;
  detectionsDays: number;
  previewsDays: number;
  snapshotsDays: number;
  eventsDays: number;
  retainIndefinitely: boolean;
}

export class RetentionPolicyService extends EventEmitter {
  private static instance: RetentionPolicyService;
  private initialized = false;
  private policyCache: Map<string, { policy: RetentionPolicy; timestamp: number }> = new Map();
  private readonly CACHE_TTL = 60000; // 1 minute cache
  private readonly DEFAULT_RETENTION_DAYS = {
    alerts: 7,
    snapshots: 7,
    events: 7,
    detections: 30,
    previews: 14,
  };
  private creatingPolicy = false;

  private constructor() {
    super();
    logger.info('RetentionPolicyService: Initializing', 'RetentionPolicyService');
  }

  static getInstance(): RetentionPolicyService {
    if (!RetentionPolicyService.instance) {
      RetentionPolicyService.instance = new RetentionPolicyService();
    }
    return RetentionPolicyService.instance;
  }

  async initialize(): Promise<void> {
    if (this.initialized) return;

    try {
      const hasGlobalPolicy = await AppDataSource.getRepository(RetentionPolicy)
        .createQueryBuilder('rp')
        .where('rp.camera IS NULL')
        .getExists();

      if (!hasGlobalPolicy) {
        await this.createGlobalPolicy();
      }

      this.initialized = true;
      logger.info('RetentionPolicyService initialized', 'RetentionPolicyService');
    } catch (error) {
      logger.error('Failed to initialize RetentionPolicyService', 'RetentionPolicyService', error);
      throw error;
    }
  }

  async createGlobalPolicy(): Promise<RetentionPolicy> {
    try {
      const policy = AppDataSource.getRepository(RetentionPolicy).create({
        camera: null,
        alerts_days: this.DEFAULT_RETENTION_DAYS.alerts,
        detections_days: this.DEFAULT_RETENTION_DAYS.detections,
        previews_days: this.DEFAULT_RETENTION_DAYS.previews,
        snapshots_days: this.DEFAULT_RETENTION_DAYS.snapshots,
        events_days: this.DEFAULT_RETENTION_DAYS.events,
        retain_indefinitely: false,
      });

      return await AppDataSource.getRepository(RetentionPolicy).save(policy);
    } catch (error) {
      logger.error('Error creating global retention policy', 'RetentionPolicyService', error);
      throw error;
    }
  }

  async getPolicy(camera?: string): Promise<RetentionPolicy> {
    try {
      const cacheKey = camera || 'global';
      const cached = this.policyCache.get(cacheKey);
      if (cached && Date.now() - cached.timestamp < this.CACHE_TTL) {
        return cached.policy;
      }

      let policy = await AppDataSource.getRepository(RetentionPolicy)
        .createQueryBuilder('rp')
        .where('rp.camera = :camera', { camera: camera || null })
        .getOne();

      if (!policy) {
        if (this.creatingPolicy) {
          throw new Error('Re-entrant call to getPolicy detected');
        }
        this.creatingPolicy = true;
        try {
          policy = await this.createCameraPolicy(camera);
        } finally {
          this.creatingPolicy = false;
        }
      }

      this.policyCache.set(cacheKey, { policy, timestamp: Date.now() });
      return policy;
    } catch (error) {
      logger.error(
        `Error retrieving retention policy for ${camera || 'global'}`,
        'RetentionPolicyService',
        error,
      );
      throw error;
    }
  }

  async getAllPolicies(): Promise<RetentionPolicy[]> {
    try {
      return await AppDataSource.getRepository(RetentionPolicy)
        .createQueryBuilder('rp')
        .orderBy('rp.camera', 'ASC')
        .getMany();
    } catch (error) {
      logger.error('Error retrieving all retention policies', 'RetentionPolicyService', error);
      throw error;
    }
  }

  async createCameraPolicy(camera?: string): Promise<RetentionPolicy> {
    try {
      const globalPolicy = await AppDataSource.getRepository(RetentionPolicy)
        .createQueryBuilder('rp')
        .where('rp.camera IS NULL')
        .getOne();

      if (!globalPolicy) {
        const created = await this.createGlobalPolicy();
        const policy = AppDataSource.getRepository(RetentionPolicy).create({
          camera: camera || null,
          alerts_days: created.alerts_days,
          detections_days: created.detections_days,
          previews_days: created.previews_days,
          snapshots_days: created.snapshots_days,
          events_days: created.events_days,
          retain_indefinitely: created.retain_indefinitely,
        });
        return await AppDataSource.getRepository(RetentionPolicy).save(policy);
      }

      const policy = AppDataSource.getRepository(RetentionPolicy).create({
        camera: camera || null,
        alerts_days: globalPolicy.alerts_days,
        detections_days: globalPolicy.detections_days,
        previews_days: globalPolicy.previews_days,
        snapshots_days: globalPolicy.snapshots_days,
        events_days: globalPolicy.events_days,
        retain_indefinitely: globalPolicy.retain_indefinitely,
      });

      return await AppDataSource.getRepository(RetentionPolicy).save(policy);
    } catch (error) {
      logger.error(
        `Error creating retention policy for ${camera || 'global'}`,
        'RetentionPolicyService',
        error,
      );
      throw error;
    }
  }

  async updatePolicy(
    camera: string | null,
    config: Partial<RetentionConfig>,
  ): Promise<RetentionPolicy> {
    try {
      const policy = await this.getPolicy(camera || undefined);

      if (config.alertsDays !== undefined) policy.alerts_days = config.alertsDays;
      if (config.detectionsDays !== undefined) policy.detections_days = config.detectionsDays;
      if (config.previewsDays !== undefined) policy.previews_days = config.previewsDays;
      if (config.snapshotsDays !== undefined) policy.snapshots_days = config.snapshotsDays;
      if (config.eventsDays !== undefined) policy.events_days = config.eventsDays;
      if (config.retainIndefinitely !== undefined)
        policy.retain_indefinitely = config.retainIndefinitely;

      const updatedPolicy = await AppDataSource.getRepository(RetentionPolicy).save(policy);

      this.emit('policyUpdated', { camera: camera || 'global', policy: updatedPolicy });

      return updatedPolicy;
    } catch (error) {
      logger.error(
        `Error updating retention policy for ${camera || 'global'}`,
        'RetentionPolicyService',
        error,
      );
      throw error;
    }
  }

  async deletePolicy(camera: string): Promise<void> {
    try {
      await AppDataSource.getRepository(RetentionPolicy)
        .createQueryBuilder('rp')
        .delete()
        .where('rp.camera = :camera', { camera })
        .execute();

      this.emit('policyDeleted', { camera });
    } catch (error) {
      logger.error(
        `Error deleting retention policy for ${camera}`,
        'RetentionPolicyService',
        error,
      );
      throw error;
    }
  }

  async getExpiredFiles(camera?: string, category?: string): Promise<string[]> {
    try {
      const policy = await this.getPolicy(camera);

      if (policy.retain_indefinitely) {
        return [];
      }

      const retentionDays = this.getRetentionDaysForCategory(policy, category);
      const cutoffDate = new Date();
      cutoffDate.setDate(cutoffDate.getDate() - retentionDays);

      const expiredFiles: string[] = [];

      if (category === 'alerts' || !category) {
        expiredFiles.push(...(await this.findExpiredFiles('alerts', camera, cutoffDate)));
      }

      if (category === 'detections' || !category) {
        expiredFiles.push(...(await this.findExpiredFiles('detections', camera, cutoffDate)));
      }

      if (category === 'previews' || !category) {
        expiredFiles.push(...(await this.findExpiredFiles('previews', camera, cutoffDate)));
      }

      if (category === 'snapshots' || !category) {
        expiredFiles.push(...(await this.findExpiredFiles('snapshots', camera, cutoffDate)));
      }

      if (category === 'events' || !category) {
        expiredFiles.push(...(await this.findExpiredFiles('events', camera, cutoffDate)));
      }

      return expiredFiles;
    } catch (error) {
      logger.error(
        `Error finding expired files for ${camera || 'global'}/${category || 'all'}`,
        'RetentionPolicyService',
        error,
      );
      throw error;
    }
  }

  private getRetentionDaysForCategory(policy: RetentionPolicy, category?: string): number {
    switch (category) {
      case 'alerts':
        return policy.alerts_days;
      case 'detections':
        return policy.detections_days;
      case 'previews':
        return policy.previews_days;
      case 'snapshots':
        return policy.snapshots_days;
      case 'events':
        return policy.events_days;
      default:
        return Math.min(
          policy.alerts_days,
          policy.detections_days,
          policy.previews_days,
          policy.snapshots_days,
          policy.events_days,
        );
    }
  }

  private async findExpiredFiles(
    category: string,
    camera: string | undefined,
    cutoffDate: Date,
  ): Promise<string[]> {
    const expiredFiles: string[] = [];
    const detectionsDir = process.env.DETECTIONS_DIR || '/app/data/detections';

    if (category !== 'detections' && category !== 'events') {
      const categoryPath = this.getCategoryPath(category, camera, detectionsDir);
      try {
        await fs.access(categoryPath);
      } catch {
        return expiredFiles;
      }
      try {
        const files = await this.scanDirectory(categoryPath);
        for (const file of files) {
          if (file.mtime < cutoffDate) {
            expiredFiles.push(file.path);
          }
        }
      } catch (error) {
        logger.warn(
          `Error scanning ${category} directory for ${camera || 'global'}`,
          'RetentionPolicyService',
        );
      }
      return expiredFiles;
    }

    try {
      const entries = await fs.readdir(detectionsDir, { withFileTypes: true });
      const monthDirs = entries
        .filter((e) => e.isDirectory() && /^\d{4}-\d{2}$/.test(e.name))
        .map((e) => e.name);

      for (const monthDir of monthDirs) {
        const scanPath = path.join(detectionsDir, monthDir);
        const files = await this.scanDirectory(scanPath, 4);

        for (const file of files) {
          if (file.mtime < cutoffDate) {
            if (camera) {
              const basename = path.basename(file.path);
              if (!basename.includes(`_${camera}_`) && !basename.includes(`_${camera}`)) continue;
            }
            expiredFiles.push(file.path);
          }
        }
      }
    } catch (error) {
      logger.warn(`Error scanning detections for ${camera || 'global'}`, 'RetentionPolicyService');
    }

    return expiredFiles;
  }

  private getCategoryPath(category: string, camera: string | undefined, baseDir: string): string {
    switch (category) {
      case 'alerts':
        return path.join(baseDir, 'alerts');
      case 'snapshots':
        return path.join(baseDir, 'snapshots');
      case 'previews':
        return path.join(baseDir, 'previews');
      case 'detections':
      case 'events':
        return baseDir;
      default:
        return path.join(baseDir, category);
    }
  }

  private async scanDirectory(
    dirPath: string,
    maxDepth = 3,
  ): Promise<Array<{ path: string; mtime: Date }>> {
    const files: Array<{ path: string; mtime: Date }> = [];

    try {
      const entries = await fs.readdir(dirPath, { withFileTypes: true });

      for (const entry of entries) {
        const fullPath = path.join(dirPath, entry.name);

        if (entry.isDirectory() && maxDepth > 0) {
          const subFiles = await this.scanDirectory(fullPath, maxDepth - 1);
          files.push(...subFiles);
        } else if (entry.isFile()) {
          try {
            const stats = await fs.stat(fullPath);
            files.push({
              path: fullPath,
              mtime: stats.mtime,
            });
          } catch (error) {
            logger.warn(`Error reading file stats for ${fullPath}`, 'RetentionPolicyService');
          }
        }
      }
    } catch (error) {
      logger.warn(`Error scanning directory ${dirPath}`, 'RetentionPolicyService');
    }

    return files;
  }

  // Only used by cleanup job - not cached, runs at 3AM
  async getRetentionSummary(camera?: string): Promise<{
    policy: RetentionPolicy;
    expiredCounts: { [key: string]: number };
    totalExpiredFiles: number;
  }> {
    try {
      const policy = await this.getPolicy(camera);
      const expiredCounts: { [key: string]: number } = {};
      let totalExpiredFiles = 0;

      const categories = ['alerts', 'detections', 'previews', 'snapshots', 'events'];

      for (const category of categories) {
        const expiredFiles = await this.getExpiredFiles(camera, category);
        expiredCounts[category] = expiredFiles.length;
        totalExpiredFiles += expiredFiles.length;
      }

      return {
        policy,
        expiredCounts,
        totalExpiredFiles,
      };
    } catch (error) {
      logger.error(
        `Error getting retention summary for ${camera || 'global'}`,
        'RetentionPolicyService',
        error,
      );
      throw error;
    }
  }

  async applyRetentionPolicy(camera?: string, category?: string): Promise<number> {
    try {
      const expiredFiles = await this.getExpiredFiles(camera, category);
      let deletedCount = 0;

      for (const filePath of expiredFiles) {
        try {
          await fs.unlink(filePath);
          deletedCount++;
        } catch (error) {
          logger.warn(`Error deleting expired file ${filePath}`, 'RetentionPolicyService');
        }
      }

      if (deletedCount > 0) {
        this.emit('retentionApplied', {
          camera: camera || 'global',
          category: category || 'all',
          deletedCount,
        });
      }

      return deletedCount;
    } catch (error) {
      logger.error(
        `Error applying retention policy for ${camera || 'global'}/${category || 'all'}`,
        'RetentionPolicyService',
        error,
      );
      throw error;
    }
  }

  isInitialized(): boolean {
    return this.initialized;
  }
}

