      }),
      findOne: jest.fn(),
      create: jest.fn(),
      save: jest.fn(),
      update: jest.fn(),
    };

    mockReviewStatusRepo = {
      findOne: jest.fn(),
      save: jest.fn(),
      update: jest.fn(),
    };

