describe('TimelineService', () => {
  let timelineService: TimelineService;
  let mockTimelineRepo: any;
  let mockRegionRepo: any;

  beforeEach(() => {
    mockTimelineRepo = {
      createQueryBuilder: jest.fn().mockReturnValue({
        where: jest.fn().mockReturnThis(),
        andWhere: jest.fn().mockReturnThis(),
        orderBy: jest.fn().mockReturnThis(),
        limit: jest.fn().mockReturnThis(),
        getMany: jest.fn().mockResolvedValue([]),
        skip: jest.fn().mockReturnThis(),
        take: jest.fn().mockReturnThis(),
        getManyAndCount: jest.fn().mockResolvedValue([[], 0]),
      }),
      findOne: jest.fn(),
      create: jest.fn(),
      save: jest.fn(),
      update: jest.fn(),
      delete: jest.fn(),
    };

    mockRegionRepo = {
      findOne: jest.fn(),
      update: jest.fn(),
      save: jest.fn(),
    };

    timelineService = new TimelineService(mockTimelineRepo, mockRegionRepo);
  });

  afterEach(() => {
    jest.clearAllMocks();
  });

  describe('getTimeline', () => {
    it('should return empty timeline when no events', async () => {
      mockTimelineRepo.createQueryBuilder().getMany.mockResolvedValue([]);

      const result = await timelineService.getTimeline({});

      expect(result.events).toEqual([]);
      expect(result.summary).toEqual({});
    });

    it('should filter by camera', async () => {
      mockTimelineRepo
        .createQueryBuilder()
        .getMany.mockResolvedValue([
          {
            id: '1',
            source: 'tracked_object',
            class_type: 'person',
            data: {},
            timestamp: new Date(),
          },
        ]);

      const result = await timelineService.getTimeline({ camera: 'front_door' });

      expect(mockTimelineRepo.createQueryBuilder().andWhere).toHaveBeenCalledWith(
        'timeline.camera = :camera',
        { camera: 'front_door' },
      );
      expect(result.events).toHaveLength(1);
    });

    it('should apply date range filters', async () => {
      const startDate = new Date('2024-01-01');
      const endDate = new Date('2024-01-31');

      const result = await timelineService.getTimeline({
        after: startDate,
        before: endDate,
      });

      expect(mockTimelineRepo.createQueryBuilder().where).toHaveBeenCalledWith(
        'timeline.timestamp >= :after',
        { after: startDate },
      );
      expect(mockTimelineRepo.createQueryBuilder().andWhere).toHaveBeenCalledWith(
        'timeline.timestamp <= :before',
        { before: endDate },
      );
    });

    it('should limit results', async () => {
      mockTimelineRepo.createQueryBuilder().getMany.mockResolvedValue([]);

      const result = await timelineService.getTimeline({ limit: 50 });

      expect(mockTimelineRepo.createQueryBuilder().limit).toHaveBeenCalledWith(50);
    });
  });

  describe('addTimelineEvent', () => {
    it('should create event with generated ID', async () => {
      const mockEvent = { id: '', save: jest.fn() };
      mockTimelineRepo.create.mockReturnValue(mockEvent);
      mockTimelineRepo.save.mockResolvedValue({} as any);
      mockRegionRepo.findOne.mockResolvedValue(null as any);
      mockRegionRepo.save.mockResolvedValue({} as any);

      const event = {
        timestamp: new Date(),
        camera: 'cam1',
        source: 'tracked_object',
        sourceId: 'obj_1',
        classType: 'person',
        data: { object_id: 'obj_1', label: 'person', score: 0.9 },
      };

      const result = await timelineService.addTimelineEvent(event);

      expect(mockTimelineRepo.create).toHaveBeenCalled();
      expect(mockTimelineRepo.save).toHaveBeenCalled();
      expect(result.id).toMatch(/^tl_/);
    });

    it('should create adaptive region if none exists', async () => {
      mockRegionRepo.findOne.mockResolvedValue(null as any);
      mockRegionRepo.save.mockResolvedValue({} as any);

      const event = {
        timestamp: new Date(),
        camera: 'cam1',
        source: 'tracked_object',
        sourceId: 'region_1',
        classType: 'region',
        data: {
          box: { x: 0, y: 0, width: 640, height: 480 },
          grid: { cells: ['0,0', '0,1'] },
        },
      };

      await timelineService.addTimelineEvent(event);

      expect(mockRegionRepo.save).toHaveBeenCalled();
    });
  });

  describe('getAdaptiveRegions', () => {
    it('should return existing regions', async () => {
      mockRegionRepo.findOne.mockResolvedValue({
        camera: 'cam1',
        grid: { cells: ['0,0', '1,1'], last_update: '2024-01-15T10:00:00Z' },
      } as any);

      const result = await timelineService.getAdaptiveRegions('cam1');

      expect(result.cells).toEqual(['0,0', '1,1']);
      expect(result.last_update).toBe('2024-01-15T10:00:00Z');
    });

    it('should return default regions when none exist', async () => {
      mockRegionRepo.findOne.mockResolvedValue(null as any);

      const result = await timelineService.getAdaptiveRegions('cam1');

      expect(result.cells).toEqual([]);
      expect(result.last_update).toBeNull();
    });
  });

  describe('updateAdaptiveRegions', () => {
    it('should add new cell to grid', async () => {
      mockRegionRepo.findOne.mockResolvedValue({
        camera: 'cam1',
        grid: { cells: ['0,0'], last_update: null },
      } as any);
      mockRegionRepo.update.mockResolvedValue({} as any);

      await (timelineService as any).updateAdaptiveRegions('cam1', {
        box: { x: 32, y: 32, width: 64, height: 64 },
      });

      expect(mockRegionRepo.update).toHaveBeenCalledWith(
        'cam1',
        expect.objectContaining({
          grid: expect.objectContaining({
            cells: expect.arrayContaining(['0,0', '0,0']),
          }),
        }),
      );
    });

    it('should create new grid if none exists', async () => {
      mockRegionRepo.findOne.mockResolvedValue(null as any);
      mockRegionRepo.save.mockResolvedValue({} as any);

      await (timelineService as any).updateAdaptiveRegions('cam1', {
        box: { x: 32, y: 32, width: 64, height: 64 },
      });

      expect(mockRegionRepo.save).toHaveBeenCalledWith(
        expect.objectContaining({
          camera: 'cam1',
          grid: expect.objectContaining({
            cells: expect.arrayContaining(['0,0']),
          }),
        }),
      );
    });
  });

  describe('clearAdaptiveRegions', () => {
    it('should reset grid to empty cells', async () => {
      mockRegionRepo.update.mockResolvedValue({} as any);

      await timelineService.clearAdaptiveRegions('cam1');

      expect(mockRegionRepo.update).toHaveBeenCalledWith('cam1', {
        grid: { cells: [], last_update: expect.any(String) },
        last_update: expect.any(Date),
      });
    });
  });
});

import { Repository } from 'typeorm';
import { Timeline } from '../../models/Timeline.js';
import { AdaptiveRegion } from '../../models/AdaptiveRegion.js';
import { cacheService } from '../cacheService.js';

interface TimelineEvent {
  id: string;
  timestamp: Date;
  camera: string;
  source: string;
  sourceId: string;
  classType: string;
  data: Record<string, unknown>;
}

interface TimelineQuery {
  camera?: string;
  after?: Date;
  before?: Date;
  sources?: string[];
  limit?: number;
}

interface ActiveObject {
  label: string;
  lastSeen: Date;
  score: number;
}

const ACTIVE_OBJECT_TIMEOUT_MS = 10000;
const CACHE_TTL = 300;

export class TimelineService {
  constructor(
    private readonly timelineRepo: Repository<Timeline>,
    private readonly regionRepo: Repository<AdaptiveRegion>,
  ) {}

  async getTimeline(query: TimelineQuery): Promise<{
    events: TimelineEvent[];
    summary: Record<string, number>;
  }> {
    const { camera, after, before, sources, limit = 1000 } = query;

    const queryBuilder = this.timelineRepo
      .createQueryBuilder('timeline')
      .where('timeline.timestamp >= :after', { after: after || new Date(Date.now() - 86400000) })
      .andWhere('timeline.timestamp <= :before', { before: before || new Date() });

    if (camera) {
      queryBuilder.andWhere('timeline.camera = :camera', { camera });
    }

    if (sources && sources.length > 0) {
      queryBuilder.andWhere('timeline.source IN (:...sources)', { sources });
    }

    const events = await queryBuilder.orderBy('timeline.timestamp', 'DESC').limit(limit).getMany();

    const resultEvents: TimelineEvent[] = events.map((event) => ({
      id: event.id,
      timestamp: event.timestamp,
      camera: event.camera,
      source: event.source,
      sourceId: event.source_id,
      classType: event.class_type,
      data: event.data,
    }));

    const summary: Record<string, number> = {};
    for (const event of events) {
      const key = `${event.source}:${event.class_type}`;
      summary[key] = (summary[key] || 0) + 1;
    }

    return { events: resultEvents, summary };
  }

  async getActiveObjects(camera: string): Promise<Map<string, ActiveObject>> {
    const cutoff = new Date(Date.now() - ACTIVE_OBJECT_TIMEOUT_MS);

    const events = await this.timelineRepo
      .createQueryBuilder('timeline')
      .where('timeline.camera = :camera', { camera })
      .andWhere('timeline.source = :source', { source: 'tracked_object' })
      .andWhere('timeline.timestamp >= :cutoff', { cutoff })
      .orderBy('timeline.timestamp', 'DESC')
      .getMany();

    const activeObjects = new Map<string, ActiveObject>();

    for (const event of events) {
      const data = event.data as { object_id?: string; label?: string; score?: number };
      if (!data.object_id) continue;

      const existing = activeObjects.get(data.object_id);
      if (!existing || event.timestamp > existing.lastSeen) {
        activeObjects.set(data.object_id, {
          label: data.label || event.class_type,
          lastSeen: event.timestamp,
          score: data.score || 0,
        });
      }
    }

    return activeObjects;
  }

  async addTimelineEvent(event: Omit<TimelineEvent, 'id'>): Promise<TimelineEvent> {
    const id = `tl_${Date.now().toString(36)}_${Math.random().toString(36).substring(2, 8)}`;

    const timelineEvent = this.timelineRepo.create({
      id,
      timestamp: event.timestamp || new Date(),
      camera: event.camera,
      source: event.source as Timeline['source'],
      source_id: event.sourceId,
      class_type: event.classType,
      data: event.data,
    });

    await this.timelineRepo.save(timelineEvent);

    if (event.source === 'tracked_object') {
      await this.updateAdaptiveRegions(
        event.camera,
        event.data as { box?: { x: number; y: number; width: number; height: number } },
      );
    }

    return { id, ...event };
  }

  async getAdaptiveRegions(
    camera: string,
  ): Promise<{ cells: string[]; last_update: string | null }> {
    const region = await this.regionRepo.findOne({ where: { camera } });
    return region?.grid || { cells: [], last_update: null };
  }

  async clearAdaptiveRegions(camera: string): Promise<void> {
    await this.regionRepo.update(camera, {
      grid: { cells: [], last_update: new Date().toISOString() },
      last_update: new Date(),
    });
  }

  private async updateAdaptiveRegions(
    camera: string,
    data: { box?: { x: number; y: number; width: number; height: number } },
  ): Promise<void> {
    if (!data.box) return;

    const region = await this.regionRepo.findOne({ where: { camera } });
    const grid = region?.grid || { cells: [], last_update: null };

    const cellX = Math.floor(data.box.x / 64);
    const cellY = Math.floor(data.box.y / 64);
    const key = `${cellX},${cellY}`;

    grid.cells = Array.from(new Set([...grid.cells, key]));
    grid.last_update = new Date().toISOString();

    if (region) {
      await this.regionRepo.update(camera, { grid, last_update: new Date() });
    } else {
      await this.regionRepo.save({ camera, grid, last_update: new Date() });
    }
  }
}

import { Router } from 'express';

class VisitorService {
  async getKnownPersons(): Promise<any[]> {
    const { AppDataSource } = await import('../database.js');
    const rows = await AppDataSource.query(
      "SELECT id, name, COALESCE(embedding_count, 0) as image_count, created_at, updated_at FROM visitors WHERE type = 'known' ORDER BY name ASC",
    );
    return rows.map((r: any) => ({
      id: r.id,
      name: r.name,
      imageCount: r.image_count,
      embeddingCount: r.image_count,
      createdAt: r.created_at,
      updatedAt: r.updated_at,
    }));
  }

  async createPerson(name: string): Promise<string> {
    const { AppDataSource } = await import('../database.js');
